function handleLearningExerciseGuidePrimary() {
  const action = els.btnLearningExerciseGuidePrimary?.dataset.action || "return";
  if (action === "practice") completeLearningPracticeStep();
  else if (action === "verify") verifyLearningResult();
  else returnToLearningCockpit(true);
}
function handleFoundationPrimaryAction(cockpit, action) {
  if (!foundationIsActive(cockpit.module_key)) return false;
  const module = learningModuleByKey(cockpit.module_key);
  if (module.key === "market") {
    if (action.key === "open") {
      const button = document.getElementById("btnLivecheck"); button?.click(); scrollToLearningTarget("livecheck"); setActionFeedback("info", "Livecheck lancé", "Attends l’affichage de la source et de l’heure. L’étape 2 sera validée après écriture et relecture IndexedDB."); return true;
    }
  }
  if (module.key === "risk" && action.key === "open") { handleFoundationAction("risk_load_costs"); return true; }
  if (module.key === "spot" && action.key === "verify") { handleFoundationAction("spot_run_safe_btc"); return true; }
  if (module.key === "risk" && action.key === "practice") { handleFoundationAction("risk_run_safe_btc"); return true; }
  if (["open","practice","verify","note"].includes(action.key)) {
    scrollToLearningTarget("learningFoundationLab");
    const stage = action.key === "open" ? "2" : action.key === "practice" ? "3" : action.key === "verify" ? "4" : "5";
    const card = els.learningFoundationLab?.querySelector?.(`[data-foundation-stage="${stage}"]`) || els.learningFoundationLab;
    card?.classList?.add("learning-action-highlight"); setTimeout(() => card?.classList?.remove("learning-action-highlight"), 1800);
    const messages = {
      market:{ practice:["Étape 3 · relever Bitcoin","Lis les trois valeurs affichées, consulte la ligne Bitcoin si nécessaire, puis confirme-les."], verify:["Étape 4 · vérifier la provenance","La source et l’heure sont affichées dans la carte. Valide-les."], note:["Étape 5 · conclusion guidée","Lis la synthèse puis réponds à la question."] },
      spot:{ open:["Étape 2 · Bid / Ask","Identifie le meilleur Ask puis le meilleur Bid."], practice:["Étape 3 · Marché / Limite","Réponds aux deux situations dans la carte."], note:["Étape 5 · exécution guidée","Lis la position créée puis réponds à la question sur l’ordre limite."] },
      risk:{ verify:["Étape 4 · scénarios","Teste −3 %, puis +5 %, et compare brut / net."], note:["Étape 5 · résultat net","Lis la comparaison puis réponds à la question sur les frais."] }
    };
    const msg = messages[module.key]?.[action.key] || [action.title, action.text];
    setActionFeedback("info", msg[0], msg[1], card); return true;
  }
  return false;
}
function handleLearningPrimaryAction() {
  const cockpit = loadLearningCockpitState();
  const action = learningActionState(cockpit);
  if (["open","practice","verify","note"].includes(action.key) && handleFoundationPrimaryAction(cockpit, action)) return;
  if (action.key === "read") {
    if (els.learningLessonPanel) { els.learningLessonPanel.hidden = false; els.learningLessonPanel.open = true; }
    scrollToLearningTarget("learningLessonPanel");
    setActionFeedback("info", "Leçon ouverte", "Lis son contenu, puis clique sur « Valider l’étape 1 après lecture » sous la leçon.", els.learningLessonPanel);
  } else if (action.key === "open") continueLearningJourney(false);
  else if (action.key === "practice") continueLearningJourney(true);
  else if (action.key === "verify") openLearningVerificationTarget();
  else if (action.key === "note") focusLearningConclusion();
  else if (action.key === "complete") {
    scrollToLearningTarget("learningCompletionAction");
    setActionFeedback("info", "Archivage séparé", "Clique sur « Terminer et archiver le module ». L’application écrira puis relira l’archive avant d’annoncer la réussite.", els.learningCompletionAction);
  }
  else if (action.key === "next_module") startNextLearningModule();
}
function learningSessionSnapshot(cockpit) {
  const module = learningModuleByKey(cockpit.module_key);
  const totals = getSimulationTotals();
  const lesson = ATLAS_GUIDED_LESSONS[module.key] || ATLAS_GUIDED_LESSONS.market;
  return {
    ...cockpit,
    archived_at:new Date().toISOString(),
    module_title:module.title,
    lesson,
    profile_label:SIM_PROFILE.label,
    flow_build:ATLAS_LEARNING_FLOW_BUILD,
    simulation:{ cash:state.sim.cash, positions_value:totals.positionsValue, pnl_gross:totals.pnl },
    interface_facts:currentLearningInterfaceFacts(module.key)
  };
}
async function completeLearningSession() {
  let cockpit = loadLearningCockpitState();
  const repaired = restoreReopenedArchivedLearningSession(cockpit);
  cockpit = repaired.cockpit;
  if (cockpit.completed_at) {
    saveLearningCockpitState(cockpit);
    renderLearningJourneyCockpit();
    scrollToLearningTarget("learningCompletionPanel");
    setActionFeedback("ok", "Session déjà archivée", "Aucun doublon n’a été créé. Le bouton distinct du panneau vert conduit au module suivant.");
    return { ok:true, already_archived:true, session_id:cockpit.session_id };
  }
  const missing = ATLAS_LEARNING_SESSION_STEPS.filter(key => !cockpit.steps[key]);
  if (missing.length) {
    setActionFeedback("warn", "Session incomplète", `Étapes restantes : ${missing.map(key => learningStepLabel(key, cockpit.module_key)).join(", ")}. Le bouton principal indique la première action manquante.`);
    renderLearningJourneyCockpit();
    return { ok:false, reason:"missing_steps", missing };
  }
  if (foundationIsActive(cockpit.module_key) && !foundationConclusionReady(cockpit)) {
    setActionFeedback("warn", "Synthèse guidée non validée", "Lis la synthèse du module et réponds à sa question avant l’archivage.");
    focusLearningConclusion();
    return { ok:false, reason:"missing_guided_conclusion" };
  }
  if (!foundationIsActive(cockpit.module_key) && !String(cockpit.takeaway || "").trim()) {
    setActionFeedback("warn", "Conclusion personnelle manquante", "Écris ce que tu retiens avec tes propres mots. Tes notes longues peuvent rester dans le premier champ.");
    focusLearningConclusion();
    return { ok:false, reason:"missing_takeaway" };
  }

  const cacheBackup = atlasLearningClone(atlasLearningNotebookCache);
  const moduleKey = cockpit.module_key;
  cockpit.completed_at = new Date().toISOString();
  cockpit.last_action = "complete";
  cockpit.flow_build = ATLAS_LEARNING_FLOW_BUILD;
  const history = loadLearningHistory();
  const snapshot = learningSessionSnapshot(cockpit);
  const existingIndex = history.findIndex(entry => entry?.session_id === cockpit.session_id);
  if (existingIndex >= 0) history[existingIndex] = snapshot;
  else history.unshift(snapshot);
  saveLearningHistory(history);
  cockpit.completed_sessions = history.length;
  saveLearningCockpitState(cockpit);

  const roadmap = loadExpertRoadmap();
  const current = roadmap.modules[moduleKey];
  if (current) {
    const nextStatus = cockpit.steps.practice && cockpit.steps.verify
      ? "practiced"
      : current.status === "new"
        ? "discovered"
        : current.status === "discovered"
          ? "understood"
          : current.status;
    roadmap.modules[moduleKey] = {
      ...current,
      status:nextStatus,
      note:cockpit.takeaway,
      updated_at:new Date().toISOString(),
      practice_evidence_session_id:cockpit.session_id,
      practice_evidence_completed_at:cockpit.completed_at,
      reconciled_by_build:ATLAS_BUILD
    };
    saveExpertRoadmap(roadmap);
  }

  if (els.btnCompleteLearningSession) els.btnCompleteLearningSession.disabled = true;
  const persisted = await atlasLearningPersistNow("complete_learning_session_28_3_05");
  const persistedHistory = Array.isArray(persisted?.record?.history) ? persisted.record.history : [];
  const persistedArchive = persistedHistory.find(entry => entry?.session_id === cockpit.session_id && entry?.completed_at);
  const persistedRoadmap = persisted?.record?.roadmap?.modules?.[moduleKey] || null;
  const verified = Boolean(
    persisted?.ok
    && persistedArchive
    && ATLAS_LEARNING_SESSION_STEPS.every(key => persistedArchive.steps?.[key] === true)
    && persistedRoadmap?.status === "practiced"
  );

  if (!verified) {
    atlasLearningNotebookCache = cacheBackup;
    renderExpertRoadmap();
    renderLearningJourneyCockpit();
    scrollToLearningTarget("learningCompletionAction");
    const detail = persisted?.error_name || persisted?.error_message || "relecture IndexedDB non conforme";
    setActionFeedback("warn", "Archivage non confirmé", `La session reste à 5/5 sans être marquée archivée. L’état précédent a été restauré. Détail : ${detail}.`);
    return { ok:false, reason:"persistence_verification_failed", persisted };
  }

  atlasLearningReviewOpen = false;
  renderExpertRoadmap();
  renderLearningJourneyCockpit();
  renderLegacyLearningMigration();
  scrollToLearningTarget("learningCompletionPanel");
  const completedModule = learningModuleByKey(moduleKey);
  setActionFeedback("ok", "Session archivée et relue", `${persistedHistory.length} session${persistedHistory.length > 1 ? "s" : ""} conservée${persistedHistory.length > 1 ? "s" : ""} dans IndexedDB. ${completedModule.title} reste visible à 5/5 et le passage au module suivant est séparé.`);
  return { ok:true, verified:true, session_id:cockpit.session_id, history_count:persistedHistory.length };
}
function startNextLearningModule() {
  let previous = loadLearningCockpitState();
  const repaired = restoreReopenedArchivedLearningSession(previous);
  previous = repaired.cockpit;
  if (!previous.completed_at) {
    setActionFeedback("warn", "Session encore en cours", "Termine et archive la séance actuelle avant de créer le module suivant.");
    renderLearningJourneyCockpit();
    return;
  }
  const nextModule = learningModuleAfterCompleted(previous);
  const next = defaultLearningCockpitState();
  next.completed_sessions = loadLearningHistory().length;
  next.module_key = nextModule.key;
  next.previous_session_id = previous.session_id;
  next.flow_build = ATLAS_LEARNING_FLOW_BUILD;
  saveLearningCockpitState(next);
  atlasLearningReviewOpen = false;
  if (els.learningLessonPanel) { els.learningLessonPanel.hidden = false; els.learningLessonPanel.open = false; }
  renderLearningJourneyCockpit();
  scrollToLearningTarget("learningPrimaryActionPanel");
  setActionFeedback("ok", "Module suivant prêt", `${nextModule.title} · nouvelle séance créée. Les ${next.completed_sessions} anciennes sessions restent archivées.`);
}
function newLearningSession() {
  return restartLearningModuleFromStepOne({ source:"session_options" });
}

const AGENT_CRYPTO_RESET_SUCCESS_KEY = "agent_crypto_internal_reset_success_28_2_98";
const AGENT_CRYPTO_RESET_ERROR_PREFIX = "RESET-AGENT-CRYPTO";

function agentCryptoResetLocalStorageTargets() {
  const exact = new Set([
    ATLAS_LEARNING_COCKPIT_KEY,
    ATLAS_LEARNING_HISTORY_KEY,
    ATLAS_EXPERT_ROADMAP_KEY,
    ATLAS_LEARNING_PREVIOUS_COCKPIT_KEY,
    ATLAS_LEARNING_PREVIOUS_ROADMAP_KEY,
    ATLAS_LEARNING_MIGRATION_KEY,
    ATLAS_LEARNING_MIGRATION_BACKUP_KEY,
    ATLAS_LEARNING_RECOVERY_AUDIT_KEY,
    ATLAS_LEARNING_HELP_MODE_KEY,
    ATLAS_PEDAGOGY_VIEW_KEY,
    SIM_ACTIVE_PROFILE_STORAGE_KEY,
    SIM_LEGACY_STORAGE_KEY,
    SIM_COST_STORAGE_KEY,
    SIM_COST_STORAGE_KEY_PREVIOUS
  ]);
  Object.values(SIM_PROFILES).forEach(profile => exact.add(simulationStorageKey(profile)));
  const prefixes = [
    "agent_crypto_learning_",
    "agent_crypto_expert_roadmap_",
    SIM_STORAGE_PREFIX
  ];
  const targets = [];
  try {
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index);
      if (key && (exact.has(key) || prefixes.some(prefix => key.startsWith(prefix)))) targets.push(key);
    }
  } catch (error) {
    const failure = new Error(String(error?.message || error || "lecture localStorage impossible"));
    failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-LOCALSTORAGE-LIST`;
    throw failure;
  }
  return [...new Set(targets)];
}

function agentCryptoSnapshotLocalStorage(keys) {
  const snapshot = {};
  for (const key of keys) {
    try { snapshot[key] = localStorage.getItem(key); }
    catch (error) {
      const failure = new Error(String(error?.message || error || "lecture localStorage impossible"));
      failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-LOCALSTORAGE-SNAPSHOT`;
      throw failure;
    }
  }
  return snapshot;
}

function agentCryptoRestoreLocalStorage(snapshot = {}) {
  const failures = [];
  for (const [key, value] of Object.entries(snapshot)) {
    try {
      if (value === null) localStorage.removeItem(key);
      else localStorage.setItem(key, value);
    } catch (error) {
      failures.push({ key, error:String(error?.message || error) });
    }
  }
  return { ok:failures.length === 0, failures };
}

function agentCryptoClearLocalStorage(keys) {
  const failures = [];
  for (const key of keys) {
    try {
      localStorage.removeItem(key);
      if (localStorage.getItem(key) !== null) failures.push({ key, error:"clé encore présente après suppression" });
    } catch (error) {
      failures.push({ key, error:String(error?.message || error) });
    }
  }
  if (failures.length) {
    const failure = new Error("certaines données Agent-Crypto n’ont pas pu être supprimées");
    failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-LOCALSTORAGE-CLEAR`;
    failure.details = failures;
    throw failure;
  }
  return { ok:true, removed:keys };
}

function agentCryptoResetDbRequest(request, code) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      const failure = new Error(String(request.error?.message || request.error || "requête IndexedDB impossible"));
      failure.code = code;
      reject(failure);
    };
  });
}

function agentCryptoResetDbTransaction(transaction, code) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve(true);
    transaction.onerror = () => {
      const failure = new Error(String(transaction.error?.message || transaction.error || "transaction IndexedDB impossible"));
      failure.code = code;
      reject(failure);
    };
    transaction.onabort = () => {
      const failure = new Error(String(transaction.error?.message || transaction.error || "transaction IndexedDB annulée"));
      failure.code = code;
      reject(failure);
    };
  });
}

async function agentCryptoResetReadNotebook() {
  let db = null;
  try {
    db = await atlasLearningDbOpen();
    const transaction = db.transaction(ATLAS_LEARNING_DB_STORE, "readonly");
    const done = agentCryptoResetDbTransaction(transaction, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-READ-TRANSACTION`);
    const request = transaction.objectStore(ATLAS_LEARNING_DB_STORE).get(ATLAS_LEARNING_DB_RECORD_ID);
    const record = await agentCryptoResetDbRequest(request, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-READ`);
    await done;
    return record || null;
  } catch (error) {
    if (!error.code) error.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-OPEN`;
    throw error;
  } finally {
    if (db) db.close();
  }
}

async function agentCryptoResetWriteNotebook(record) {
  let db = null;
  try {
    db = await atlasLearningDbOpen();
    const transaction = db.transaction(ATLAS_LEARNING_DB_STORE, "readwrite");
    const done = agentCryptoResetDbTransaction(transaction, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-WRITE-TRANSACTION`);
    const request = transaction.objectStore(ATLAS_LEARNING_DB_STORE).put(record);
    await agentCryptoResetDbRequest(request, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-WRITE`);
    await done;
    return true;
  } catch (error) {
    if (!error.code) error.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-OPEN`;
    throw error;
  } finally {
    if (db) db.close();
  }
}

async function agentCryptoResetDeleteNotebookRecord() {
  let db = null;
  try {
    db = await atlasLearningDbOpen();
    const transaction = db.transaction(ATLAS_LEARNING_DB_STORE, "readwrite");
    const done = agentCryptoResetDbTransaction(transaction, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-ROLLBACK-TRANSACTION`);
    const request = transaction.objectStore(ATLAS_LEARNING_DB_STORE).delete(ATLAS_LEARNING_DB_RECORD_ID);
    await agentCryptoResetDbRequest(request, `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-ROLLBACK-DELETE`);
    await done;
    return true;
  } finally {
    if (db) db.close();
  }
}

function agentCryptoBlankNotebook(resetAt) {
  const cockpit = defaultLearningCockpitState();
  cockpit.completed_sessions = 0;
  cockpit.module_key = "market";
  cockpit.flow_build = ATLAS_LEARNING_FLOW_BUILD;
  cockpit.restart_build = ATLAS_BUILD;
  cockpit.foundation_path_build = ATLAS_FOUNDATION_LEARNING_BUILD;
  cockpit.last_action = null;
  return atlasLearningNormalizeNotebook({
    id:ATLAS_LEARNING_DB_RECORD_ID,
    schema:"agent_crypto_learning_notebook_indexeddb_v1",
    build:ATLAS_BUILD,
    cockpit,
    history:[],
    roadmap:atlasLearningNormalizeRoadmap(null),
    recovery:{ status:"fresh_start", verified:true, backend:"IndexedDB", reset_at:resetAt },
    migration:{ status:"fresh_start", block_automatic_reimport:true, backend:"IndexedDB", reset_at:resetAt },
    reset:{
      schema:"agent_crypto_internal_clean_reset_v1",
      status:"complete",
      build:ATLAS_BUILD,
      reset_at:resetAt,
      scope:"Agent-Crypto learning and simulations only"
    },
    last_reset_backup:null,
    updated_at:resetAt
  });
}

function agentCryptoVerifyBlankNotebook(record) {
  const notebook = atlasLearningNormalizeNotebook(record || {});
  const cockpit = notebook.cockpit;
  const stepsEmpty = ATLAS_LEARNING_SESSION_STEPS.every(key => cockpit.steps?.[key] !== true);
  const roadmapEmpty = ATLAS_EXPERT_ROADMAP_MODULES.every(module => {
    const item = notebook.roadmap?.modules?.[module.key];
    return item?.status === "new" && !String(item?.note || "").trim();
  });
  return Boolean(
    cockpit.module_key === "market"
    && cockpit.completed_at === null
    && cockpit.completed_sessions === 0
    && notebook.history.length === 0
    && stepsEmpty
    && !String(cockpit.notes_free || "").trim()
    && !String(cockpit.takeaway || "").trim()
    && roadmapEmpty
    && notebook.reset?.status === "complete"
    && notebook.reset?.build === ATLAS_BUILD
  );
}

function agentCryptoShowResetSuccessOnBoot() {
  let marker = null;
  try {
    marker = JSON.parse(sessionStorage.getItem(AGENT_CRYPTO_RESET_SUCCESS_KEY) || "null");
    sessionStorage.removeItem(AGENT_CRYPTO_RESET_SUCCESS_KEY);
  } catch {}
  if (!marker || marker.build !== ATLAS_BUILD) return false;
  setActionFeedback(
    "ok",
    "Réinitialisation terminée",
    `Module 01 · 0/5 étapes · aucune archive pédagogique · ${fmtEUR.format(SIM_PROFILES[SIM_DEFAULT_PROFILE_KEY].startCash)} virtuels · aucune position.`
  );
  scrollToLearningTarget("learningPrimaryActionPanel");
  return true;
}

async function resetEntireLearningJourney() {
  const message = [
    "Repartir de zéro dans Agent-Crypto ?",
    "",
    "SERA EFFACÉ UNIQUEMENT DANS AGENT-CRYPTO :",
    "• progression, notes, conclusions et archives pédagogiques",
    "• états de récupération du carnet",
    "• simulations fictives, positions et journaux",
    "• frais pédagogiques et scénario temporaire",
    "",
    "SERA CONSERVÉ :",
    "• Market, Métaux, Bridge, collecteurs et réglages généraux",
    "• GitHub, YouTube, mots de passe, cookies et autres interfaces BlueAzur",
    "",
    "L’application reviendra directement au Module 01 · 0/5."
  ].join("\n");
  if (typeof window !== "undefined" && !window.confirm(message)) {
    setActionFeedback("info", "Réinitialisation annulée", "Aucune donnée n’a été modifiée.");
    return { ok:false, cancelled:true };
  }

  const button = els.btnResetLearningJourney;
  if (button) { button.disabled = true; button.textContent = "Réinitialisation…"; }
  let previousNotebook = null;
  let storageSnapshot = null;
  let storageKeys = [];
  let notebookChanged = false;

  try {
    previousNotebook = await agentCryptoResetReadNotebook();
    storageKeys = agentCryptoResetLocalStorageTargets();
    storageSnapshot = agentCryptoSnapshotLocalStorage(storageKeys);

    const resetAt = new Date().toISOString();
    const blankNotebook = agentCryptoBlankNotebook(resetAt);
    await agentCryptoResetWriteNotebook(blankNotebook);
    notebookChanged = true;

    const readBack = await agentCryptoResetReadNotebook();
    if (!agentCryptoVerifyBlankNotebook(readBack)) {
      const failure = new Error("le carnet relu ne correspond pas à un Module 01 vide");
      failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-IDB-VERIFY`;
      throw failure;
    }

    agentCryptoClearLocalStorage(storageKeys);
    atlasLearningNotebookCache = atlasLearningNormalizeNotebook(readBack);
    state.sim = null;
    SIM_PROFILE = SIM_PROFILES[SIM_DEFAULT_PROFILE_KEY];
    atlasSimulationScenarioPct = 0;

    try {
      sessionStorage.setItem(AGENT_CRYPTO_RESET_SUCCESS_KEY, JSON.stringify({ build:ATLAS_BUILD, reset_at:resetAt }));
    } catch {}
    window.location.reload();
    return { ok:true, build:ATLAS_BUILD, reset_at:resetAt };
  } catch (error) {
    const localRestore = storageSnapshot ? agentCryptoRestoreLocalStorage(storageSnapshot) : { ok:true, failures:[] };
    let notebookRestore = { ok:true };
    if (notebookChanged) {
      try {
        if (previousNotebook) await agentCryptoResetWriteNotebook(previousNotebook);
        else await agentCryptoResetDeleteNotebookRecord();
      } catch (restoreError) {
        notebookRestore = { ok:false, error:String(restoreError?.message || restoreError) };
      }
    }
    if (previousNotebook) atlasLearningNotebookCache = atlasLearningNormalizeNotebook(previousNotebook);
    renderExpertRoadmap();
    renderLearningJourneyCockpit();
    if (button) { button.disabled = false; button.textContent = "Repartir de zéro"; }
    const code = error?.code || `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-UNKNOWN`;
    const restored = localRestore.ok && notebookRestore.ok;
    setActionFeedback(
      "warn",
      "Réinitialisation non appliquée",
      `${restored ? "L’ancien état a été restauré. Aucune donnée n’a été perdue." : "La restauration n’a pas été entièrement confirmée."} Code : ${code}.`
    );
    const result = { ok:false, code, error:String(error?.message || error), local_restore:localRestore, notebook_restore:notebookRestore };
    window.__atlasLearningFullResetLastResult = result;
    return result;
  }
}

