function atlasMarketEnsureWatchCoin(coin){if(!coin?.id)return;if(!state.watchIds.includes(coin.id)){state.watchIds.push(coin.id);state.watchIds=[...new Set(state.watchIds)].slice(0,48);saveWatchIds();atlasWatchSyncProfiles();}renderWatchlist();renderAutoReader();}
function atlasMarketPrepareAlert(coin){if(!coin?.id)return;atlasMarketEnsureWatchCoin(coin);renderWatchlist();const s=$("watchAlertCoin");if(s&&[...s.options].some(o=>o.value===coin.id))s.value=coin.id;atlasV2OpenAdvancedForTarget("#watchlist");setTimeout(()=>$("watchAlertThreshold")?.focus(),450);}
function atlasMarketOpenSources(coin){if(!coin?.id)return;atlasSelectMarketCoin(coin);if($("analyste")?.classList.contains("detail-collapsed"))$("detailPanelRail")?.click();const d=$("source-dock");if(d){d.open=true;atlasEnsureSourceDock(coin,{force:false});d.scrollIntoView({behavior:"smooth",block:"center"});}}
function atlasMarketHandleAction(action,coin,event){if(action==="open")atlasMarketOpenCoin(coin);else if(action==="compare")atlasToggleComparisonCoin(coin);else if(action==="watch")atlasMarketEnsureWatchCoin(coin);else if(action==="alert")atlasMarketPrepareAlert(coin);else if(action==="sources")atlasMarketOpenSources(coin);event?.preventDefault?.();}
/* =========================================================
   Build 28.2.74 — TARGET SCANNER DISCRETE CYCLE CONTRACT LOCK

   Le cycle automatique et la sélection manuelle sont deux contrats séparés.

   Cycle du cartouche :
   Top 5 → Hausses 5 → Baisses 5 → Volumes 5 → Top 3 → Top 5

   Contrats protégés :
   - les cinq cartes crypto et Market Flow conservent ajout / retrait ;
   - une modification de carte reste une SÉLECTION LIBRE ;
   - Solo reste indépendant ;
   - la position automatique du cycle n'est pas effacée par la sélection libre ;
   - un scanner en échec conserve le dernier graphique valide.
   ========================================================= */

const ATLAS_TARGET_CYCLE_ORDER = Object.freeze([
  "rank-5",
  "gainers",
  "losers",
  "volume",
  "rank-3"
]);
const ATLAS_TARGET_CYCLE_STORAGE_KEY =
  "agent_crypto_target_cycle_preset_v1";

function atlasTargetCycleIsPreset(value) {
  return ATLAS_TARGET_CYCLE_ORDER.includes(String(value || ""));
}

function atlasTargetCycleStoredPreset() {
  try {
    const stored = String(
      localStorage.getItem(ATLAS_TARGET_CYCLE_STORAGE_KEY) || ""
    ).trim();
    return atlasTargetCycleIsPreset(stored) ? stored : "rank-5";
  } catch {
    return "rank-5";
  }
}

function atlasTargetCycleRememberPreset(value) {
  const preset = atlasTargetCycleIsPreset(value)
    ? String(value)
    : atlasTargetCycleStoredPreset();

  const root = document.getElementById("targetTop5Cycle");
  if (root) root.dataset.cyclePreset = preset;

  try {
    localStorage.setItem(ATLAS_TARGET_CYCLE_STORAGE_KEY, preset);
  } catch {}

  return preset;
}

function atlasTargetCycleCurrentPreset() {
  const requested = String(
    atlasScannerTransaction?.preset
    || atlasScannerQueuedRequest?.preset
    || ""
  );

  if (atlasTargetCycleIsPreset(requested)) {
    return atlasTargetCycleRememberPreset(requested);
  }

  const displayed = String(
    state.dataBroker?.comparison?.preset || ""
  );

  if (atlasTargetCycleIsPreset(displayed)) {
    return atlasTargetCycleRememberPreset(displayed);
  }

  const rootPreset = String(
    document.getElementById("targetTop5Cycle")
      ?.dataset?.cyclePreset
    || ""
  );

  if (atlasTargetCycleIsPreset(rootPreset)) {
    return rootPreset;
  }

  return atlasTargetCycleRememberPreset(
    atlasTargetCycleStoredPreset()
  );
}

function atlasTargetCycleNextPreset(value) {
  const current = atlasTargetCycleIsPreset(value)
    ? String(value)
    : atlasTargetCycleCurrentPreset();
  const index = ATLAS_TARGET_CYCLE_ORDER.indexOf(current);

  return ATLAS_TARGET_CYCLE_ORDER[
    (index + 1) % ATLAS_TARGET_CYCLE_ORDER.length
  ];
}

function atlasTargetTopFiveDisplay(preset) {
  const map = {
    "rank-5": {
      label: "TARGET TOP 5 LIVE",
      shortLabel: "Top 5"
    },
    "gainers": {
      label: "HAUSSES 5",
      shortLabel: "Hausses 5"
    },
    "losers": {
      label: "BAISSES 5",
      shortLabel: "Baisses 5"
    },
    "volume": {
      label: "VOLUMES 5",
      shortLabel: "Volumes 5"
    },
    "rank-3": {
      label: "TOP 3 LIVE",
      shortLabel: "Top 3"
    },
    "manual": {
      label: "SÉLECTION LIBRE",
      shortLabel: "Sélection libre"
    },
    "solo": {
      label: "SOLO",
      shortLabel: "Solo"
    },
    "empty": {
      label: "SÉLECTION VIDE",
      shortLabel: "Sélection vide"
    }
  };

  return map[preset] || map.manual;
}

function atlasSyncTargetTopFiveCycleLabel() {
  const root = document.getElementById("targetTop5Cycle");
  const label = document.getElementById("targetTop5CycleLabel");
  const symbols = document.getElementById("targetTop5CycleSymbols");
  const button = document.getElementById("targetTop5CycleButton");
  if (!root || !label || !symbols || !button) return;

  const chartReady = state.dataBroker?.chart?.status === "ready"
    && atlasChartContextMatches(state.dataBroker.chart)
    && !!state.chartEngineV2?.realChart;

  const displayedPreset = chartReady
    ? String(state.dataBroker?.comparison?.preset || "manual")
    : String(state.dataBroker?.comparison?.preset || "rank-5");

  const cyclePreset = atlasTargetCycleCurrentPreset();
  const nextPreset = atlasTargetCycleNextPreset(cyclePreset);
  const display = atlasTargetTopFiveDisplay(displayedPreset);
  const nextDisplay = atlasTargetTopFiveDisplay(nextPreset);

  const ids = chartReady ? atlasComparisonIds() : [];
  const symbolLine = ids
    .map(id => state.coins.find(coin => coin.id === id)?.symbol)
    .filter(Boolean)
    .map(symbol => String(symbol).toUpperCase())
    .join(" · ");

  root.dataset.cyclePreset = cyclePreset;
  root.dataset.cycleNext = nextPreset;
  root.dataset.cycleMode = atlasTargetCycleIsPreset(displayedPreset)
    ? "automatic"
    : "manual";

  label.textContent = display.label;
  symbols.textContent =
    symbolLine || "BTC · ETH · BNB · XRP · SOL";

  root.title =
    `Mode affiché : ${display.shortLabel}`
    + ` · Cycle automatique : ${
      atlasTargetTopFiveDisplay(cyclePreset).shortLabel
    }`
    + ` · Cliquer pour : ${nextDisplay.shortLabel}`;

  root.setAttribute(
    "aria-label",
    `Mode affiché : ${display.shortLabel}. `
    + `Cliquer pour afficher ${nextDisplay.shortLabel}.`
  );

  const busy = !!atlasScannerTransaction
    || !!atlasScannerQueuedRequest;

  button.classList.toggle("is-loading", busy);
  root.setAttribute("aria-busy", busy ? "true" : "false");
}

function atlasTargetTopFiveCyclePreset() {
  return atlasTargetCycleNextPreset(
    atlasTargetCycleCurrentPreset()
  );
}

function atlasActivateTargetTopFiveCycle() {
  if (
    !state.liveOk
    || !Array.isArray(state.coins)
    || !state.coins.length
  ) {
    return false;
  }

  const next = atlasTargetTopFiveCyclePreset();
  const period = Number(state.chartPeriodDays || 1);

  if (
    next === "gainers"
    || next === "losers"
    || next === "volume"
  ) {
    const started = atlasScannerStart(next, 5, {
      period,
      source: "target-top5-cycle-28.2.57"
    });

    if (started) atlasTargetCycleRememberPreset(next);
    atlasSyncTargetTopFiveCycleLabel();
    return started;
  }

  atlasScannerCancel(
    "target top 5 cycle",
    {
      keepUi: false,
      keepOverlay: false
    }
  );

  atlasTargetCycleRememberPreset(next);
  atlasSelectTopComparison(next === "rank-3" ? 3 : 5);
  atlasSyncTargetTopFiveCycleLabel();
  return true;
}

function atlasInitMarketRibbonInteractions() {
  const act = event => {
    const target = event.target.closest("[data-market-open]");
    if (!target) return;
    if (event.type === "keydown" && !["Enter", " "].includes(event.key)) return;
    const coin = state.coins.find(item => item.id === target.dataset.marketOpen);
    if (!coin) return;
    if (event.type === "keydown") event.preventDefault();
    atlasToggleComparisonCoin(coin);
  };

  els.top5Track?.addEventListener("click", act);
  els.top5Track?.addEventListener("keydown", act);
  els.tickerTrack?.addEventListener("click", act);
  els.tickerTrack?.addEventListener("keydown", act);

  const cycleTrigger = document.getElementById("targetTop5Cycle");
  const cycle = event => {
    if (event.type === "keydown" && !["Enter", " "].includes(event.key)) return;
    if (event.type === "keydown") event.preventDefault();
    event.stopPropagation();
    atlasActivateTargetTopFiveCycle();
  };

  cycleTrigger?.addEventListener("click", cycle);
  if (cycleTrigger && cycleTrigger.tagName !== "BUTTON") cycleTrigger.addEventListener("keydown", cycle);

  const flowTrigger = document.getElementById("marketFlowCycle");
  const cycleFlow = event => {
    if (event.type === "keydown" && !["Enter", " "].includes(event.key)) return;
    if (event.type === "keydown") event.preventDefault();
    event.stopPropagation();
    atlasCycleMarketFlowMode();
  };
  flowTrigger?.addEventListener("click", cycleFlow);
  if (flowTrigger && flowTrigger.tagName !== "BUTTON") flowTrigger.addEventListener("keydown", cycleFlow);
}


function atlasMarketBasketStatus(coin, selection = atlasComparisonIds()) {
  const index = selection.indexOf(coin?.id);
  if (index >= 0) return `Panier ${index + 1}/${ATLAS_COMPARISON_MAX_SERIES}`;
  const free = Math.max(0, ATLAS_COMPARISON_MAX_SERIES - selection.length);
  return free > 0 ? `${free} place${free > 1 ? "s" : ""} libre${free > 1 ? "s" : ""}` : "Panier complet";
}

function atlasComparisonResultForCoin(coin, selection = atlasComparisonIds()) {
  if (!coin?.id || !selection.includes(coin.id)) return null;

  const comparisonResult = state.dataBroker?.comparison?.results?.[coin.id];
  if (comparisonResult) return comparisonResult;

  const chart = state.dataBroker?.chart;
  if (
    selection.length === 1
    && chart?.status === "ready"
    && chart?.coinId === coin.id
    && atlasChartContextMatches(chart)
  ) {
    return chart.result || null;
  }

  return null;
}

function atlasComparisonSeriesReadiness(coin, selection = atlasComparisonIds()) {
  const selected = !!coin?.id && selection.includes(coin.id);
  if (!selected) {
    return {
      selected: false,
      state: "available",
      label: "",
      title: "Actif non sélectionné"
    };
  }

  const comparison = state.dataBroker?.comparison || {};
  const result = atlasComparisonResultForCoin(coin, selection);
  const pending = new Set(comparison.pendingIds || []).has(coin.id);
  const unavailable = new Set(comparison.unavailableIds || []).has(coin.id);
  const rendered = new Set(comparison.renderedIds || []).has(coin.id)
    || (
      selection.length === 1
      && state.dataBroker?.chart?.status === "ready"
      && state.dataBroker?.chart?.coinId === coin.id
      && atlasChartContextMatches(state.dataBroker.chart)
    );

  if (pending || (comparison.status === "loading" && !result && !unavailable)) {
    return {
      selected: true,
      state: "loading",
      label: "Chargement…",
      title: `Chargement de la série ${atlasChartPeriodLabel(state.chartPeriodDays)}`
    };
  }

  if (result) {
    const points = Math.max(
      0,
      Number(
        result?.integrity?.metrics?.pointCount
        ?? result?.series?.length
        ?? 0
      )
    );
    const rules = atlasChartRules(state.chartPeriodDays);
    const integrityOk = result?.integrity?.ok !== false;
    const coverageHours = Number(result?.integrity?.metrics?.coverageHours || 0);
    const complete = integrityOk
      && points >= Number(rules?.minPoints || 1)
      && coverageHours >= Number(rules?.minCoverageHours || 0);

    if (!complete) {
      return {
        selected: true,
        state: "incomplete",
        label: `Incomplète · ${points} pts`,
        title: result?.integrity?.reason || "Série historique incomplète"
      };
    }

    const freshness = atlasChartWorstFreshness(result, state.chartPeriodDays);
    const normalizedMode = atlasChartSourceMode(result);
    const rawMode = String(
      result?.originalSourceMode
      || result?.sourceMode
      || ""
    ).toLowerCase();
    const sourceMode = normalizedMode === "direct" || rawMode.includes("direct")
      ? "direct"
      : normalizedMode === "cache" || rawMode.includes("cache")
        ? "cache"
        : normalizedMode;
    const provider = atlasChartProviderLabel(result);

    if (freshness === "archive") {
      return {
        selected: true,
        state: "archive",
        label: `Archive · ${points} pts`,
        title: `${provider} · série réelle archivée · ${points} points`
      };
    }

    if (freshness === "delayed") {
      return {
        selected: true,
        state: sourceMode === "cache" ? "cache" : "delayed",
        label: `${sourceMode === "cache" ? "Cache retardé" : "Direct retardé"} · ${points} pts`,
        title: `${provider} · historique retardé · ${points} points`
      };
    }

    if (sourceMode === "cache") {
      return {
        selected: true,
        state: "cache",
        label: `Cache récent · ${points} pts`,
        title: `${provider} · cache historique récent · ${points} points`
      };
    }

    if (sourceMode === "direct") {
      return {
        selected: true,
        state: rendered ? "direct" : "validated",
        label: `${rendered ? "Direct" : "Validée"} · ${points} pts`,
        title: `${provider} · série historique ${rendered ? "affichée" : "validée"} · ${points} points`
      };
    }

    return {
      selected: true,
      state: rendered ? "ready" : "validated",
      label: `${rendered ? "Prête" : "Validée"} · ${points} pts`,
      title: `${provider} · ${points} points historiques`
    };
  }

  if (unavailable || ["partial", "blocked"].includes(comparison.status)) {
    const quote = atlasCurrentQuoteForCoin(coin);
    const spotOnly = atlasQuoteIsUsable(quote);
    return {
      selected: true,
      state: spotOnly ? "spot-only" : "unavailable",
      label: spotOnly ? "Prix direct seul" : "Indisponible",
      title: spotOnly
        ? "Prix courant disponible, historique non affichable"
        : "Prix et historique indisponibles"
    };
  }

  return {
    selected: true,
    state: "waiting",
    label: "Historique en attente",
    title: "Série sélectionnée, chargement historique non démarré"
  };
}

function atlasComparisonSeriesReadinessMarkup(coin, selection = atlasComparisonIds()) {
  const readiness = atlasComparisonSeriesReadiness(coin, selection);
  return `<small class="market-series-status is-${escapeHtml(readiness.state)}" data-series-state="${escapeHtml(readiness.state)}" title="${escapeHtml(readiness.title)}" ${readiness.selected ? "" : "hidden"}>${escapeHtml(readiness.label)}</small>`;
}

function atlasMarketCompactName(coin) {
  const full = String(coin?.name || coin?.symbol || "Actif").trim();
  if (full.length <= 34) return full;
  const explicit = [
    [/^Tradable APAC\b/i, "Tradable APAC"],
    [/^BlackRock USD Institutional\b/i, "BlackRock USD"],
    [/^Spiko US T-Bills\b/i, "Spiko US T-Bills"]
  ];
  for (const [pattern, label] of explicit) {
    if (pattern.test(full)) return label;
  }
  const words = full.split(/\s+/).filter(Boolean);
  const kept = [];
  for (const word of words) {
    const candidate = [...kept, word].join(" ");
    if (kept.length >= 2 && candidate.length > 28) break;
    kept.push(word);
    if (kept.join(" ").length >= 24) break;
  }
  return kept.join(" ") || full;
}

