let atlasHelpActiveTarget = null;
let atlasHelpHideTimer = null;

function atlasHelpDefinitionFor(target) {
  if (!target) return null;
  if (target.matches?.(".period-btn[data-period]")) {
    const label = atlasChartPeriodLabel(Number(target.dataset.period || 1));
    return { title: `Période ${label}`, body: `Charge les chandelles Binance pour le Top 5, sinon les séries CoinGecko, sur ${label}. En comparaison, chaque actif est normalisé à 100 au premier point disponible.` };
  }
  if (target.matches?.("[data-math-position]")) {
    const position = target.dataset.mathPosition;
    return { title: `Math Core · ${position === "top" ? "Dessus" : position === "side" ? "Latéral" : "Réduit"}`, body: position === "top" ? "Affiche une synthèse compacte au-dessus du Market Snapshot." : position === "side" ? "Affiche le Math Core à droite, avec une hauteur indépendante du tableau." : "Réduit le Math Core en rail pour libérer la largeur du Market Snapshot." };
  }
  if (target.matches?.("[data-compare-primary]")) {
    return { title: "Actif principal", body: "Définit cet actif comme référence principale sans retirer les autres séries." };
  }
  if (target.matches?.("[data-compare-remove]")) {
    return { title: "Retirer de la comparaison", body: "Retire uniquement cet actif du graphique comparatif." };
  }
  if (target.matches?.("[data-market-open]")) {
    return { title: "Comparaison", body: "Ajoute ou retire cet actif du graphique comparatif. L’action Solo reste disponible dans le Market Snapshot." };
  }
  if (target.matches?.("[data-market-action]")) {
    const action = target.dataset.marketAction;
    const labels = { compare: ["Comparaison", "Ajoute ou retire cet actif du graphique comparatif."], open: ["Solo", "Ouvre cet actif seul dans le graphique."], watch: ["Suivre", "Ajoute ou conserve cet actif dans la Watchlist."], alert: ["Alerte", "Prépare une condition locale pour cet actif."], sources: ["Sources", "Ouvre le Source Dock de cet actif."] };
    const item = labels[action];
    return item ? { title: item[0], body: item[1] } : null;
  }
  return ATLAS_HELP_DEFINITIONS[target.id] || null;
}

function atlasHelpTargetFromNode(node) {
  if (!(node instanceof Element)) return null;
  const marketRow = node.closest?.("[data-market-help-id]");
  if (marketRow) return marketRow;
  const candidate = node.closest?.("input, textarea, select, button[id], button.period-btn, button.compare-btn, [data-math-position], [data-market-action], [data-compare-primary], [data-compare-remove], [data-market-open]");
  return candidate && atlasHelpDefinitionFor(candidate) ? candidate : null;
}

function atlasMarketHelpDefinition(row) {
  const coin = state.coins.find(item => item.id === row?.dataset?.marketHelpId);
  if (!coin) return null;
  const selection = atlasComparisonIds();
  const compared = selection.includes(coin.id);
  const score = scoreCoin(coin);
  const snapshot = atlasMarketSnapshotSurface(coin);
  const ratio = coin.volume24h && coin.marketCap ? coin.volume24h / coin.marketCap * 100 : null;
  const priceUsd = atlasHasPositiveQuote(snapshot.priceUsd) ? atlasFormatUSD(snapshot.priceUsd) : "USD —";
  const image = coin.image
    ? `<img class="atlas-help-market-icon" src="${escapeHtml(coin.image)}" alt="" loading="eager">`
    : `<span class="atlas-help-market-fallback" aria-hidden="true">${escapeHtml(coin.symbol.slice(0, 1))}</span>`;
  return {
    rich: true,
    marketCoinId: coin.id,
    liveText: `${coin.name} ${coin.symbol}. ${compared ? "Présent dans la comparaison. Clique la ligne pour le retirer." : "Clique la ligne pour l’ajouter à la comparaison."}`,
    html: `<div class="atlas-help-kicker">FICHE CRYPTO · MARKET SNAPSHOT</div>
      <div class="atlas-help-market-head">${image}<span><strong>${escapeHtml(coin.name)}</strong><b>${escapeHtml(coin.symbol)}</b><small>Rang ${escapeHtml(coin.rank ?? "—")} · ${escapeHtml(classifyAsset(coin))}</small></span></div>
      <div class="atlas-help-market-grid">
        <span><small>Prix direct EUR</small><strong data-help-live="price-eur">${escapeHtml(snapshot.quoteUsable ? atlasCurrentQuotePriceText(snapshot.quote) : atlasFormatEUR(snapshot.priceEur))}</strong></span>
        <span><small>Prix USD marché</small><strong>${escapeHtml(priceUsd)}</strong></span>
        <span><small>24 h direct</small><strong data-help-live="change24h" class="${clsPct(snapshot.change24h)}">${escapeHtml(atlasMarketSnapshotChange24Text(snapshot))}</strong></span>
        <span><small>7 j marché</small><strong data-help-live="change7d" class="${clsPct(snapshot.change7d)}">${escapeHtml(fmtPct(snapshot.change7d))}</strong></span>
        <span><small>30 j marché</small><strong data-help-live="change30d" class="${clsPct(snapshot.change30d)}">${escapeHtml(fmtPct(snapshot.change30d))}</strong></span>
        <span><small>Vol./cap.</small><strong>${Number.isFinite(ratio) ? `${ratio.toFixed(2)} %` : "—"}</strong></span>
        <span><small>Capitalisation</small><strong>${escapeHtml(num(coin.marketCap, fmtCompactEUR.format.bind(fmtCompactEUR)))}</strong></span>
        <span><small>Volume 24 h</small><strong>${escapeHtml(num(coin.volume24h, fmtCompactEUR.format.bind(fmtCompactEUR)))}</strong></span>
        <span><small>Score Atlas</small><strong>${escapeHtml(score.score ?? "—")}</strong></span>
        <span><small>Décision</small><strong>${escapeHtml(beginnerDecision(coin))}</strong></span>
      </div>
      <div class="atlas-help-market-sources">
        <span><b>Cotation et 24 h observés</b><em data-help-live="observed-source">${escapeHtml(snapshot.truthLabel)} · ${escapeHtml(snapshot.freshnessLabel)}</em></span>
        <span><b>Référence marché 24 h</b><em data-help-live="market-reference">${escapeHtml(Number.isFinite(snapshot.marketChange24h) ? fmtPct(snapshot.marketChange24h) : "—")} · ${escapeHtml(snapshot.marketSourceLabel)} · ${escapeHtml(snapshot.marketFrameLabel)}</em></span>
      </div>
      <div class="atlas-help-market-action ${compared ? "is-remove" : "is-add"}">${compared ? `Sélectionné ${selection.indexOf(coin.id) + 1}/${selection.length} · clique ou appuie sur Entrée pour retirer` : `Non sélectionné · clique ou appuie sur Entrée pour ajouter · ${selection.length}/${ATLAS_COMPARISON_MAX_SERIES}`}</div>`
  };
}

function atlasPatchOpenMarketHelp(coinOrId) {
  const coin = typeof coinOrId === "string"
    ? state.coins.find(item => item.id === coinOrId)
    : coinOrId;
  if (!coin?.id) return false;

  const layer = document.getElementById("atlasHelpLayer");
  if (!layer || layer.hidden || layer.getAttribute("aria-hidden") === "true") return false;

  const activeCoinId = atlasHelpActiveTarget?.dataset?.marketHelpId || "";
  const layerCoinId = layer.dataset.marketHelpCoinId || "";
  if (coin.id !== activeCoinId && coin.id !== layerCoinId) return false;

  const snapshot = atlasMarketSnapshotSurface(coin);
  const priceNode = layer.querySelector('[data-help-live="price-eur"]');
  const change24Node = layer.querySelector('[data-help-live="change24h"]');
  const change7Node = layer.querySelector('[data-help-live="change7d"]');
  const change30Node = layer.querySelector('[data-help-live="change30d"]');
  const observedSourceNode = layer.querySelector('[data-help-live="observed-source"]');
  const marketReferenceNode = layer.querySelector('[data-help-live="market-reference"]');

  if (priceNode) {
    priceNode.textContent = snapshot.quoteUsable
      ? atlasCurrentQuotePriceText(snapshot.quote)
      : atlasFormatEUR(snapshot.priceEur);
  }

  if (change24Node) {
    change24Node.textContent = atlasMarketSnapshotChange24Text(snapshot);
    change24Node.classList.remove("pos", "neg", "neutral");
    change24Node.classList.add(clsPct(snapshot.change24h));
  }

  if (change7Node) {
    change7Node.textContent = fmtPct(snapshot.change7d);
    change7Node.classList.remove("pos", "neg", "neutral");
    change7Node.classList.add(clsPct(snapshot.change7d));
  }

  if (change30Node) {
    change30Node.textContent = fmtPct(snapshot.change30d);
    change30Node.classList.remove("pos", "neg", "neutral");
    change30Node.classList.add(clsPct(snapshot.change30d));
  }

  if (observedSourceNode) {
    observedSourceNode.textContent = `${snapshot.truthLabel} · ${snapshot.freshnessLabel}`;
    observedSourceNode.title = atlasCurrentQuoteTitle(snapshot.quote);
  }

  if (marketReferenceNode) {
    const marketChange = Number.isFinite(snapshot.marketChange24h)
      ? fmtPct(snapshot.marketChange24h)
      : "—";
    marketReferenceNode.textContent =
      `${marketChange} · ${snapshot.marketSourceLabel} · ${snapshot.marketFrameLabel}`;
  }

  layer.dataset.marketHelpCoinId = coin.id;
  return true;
}

function atlasHelpMarkup(definition) {
  if (definition.rich) return definition.html;
  return `<div class="atlas-help-kicker">HELP LAYER V1</div><strong class="atlas-help-title">${escapeHtml(definition.title)}</strong><p>${escapeHtml(definition.body)}</p>${definition.example ? `<div class="atlas-help-example"><b>Exemple</b><span>${escapeHtml(definition.example.replace(/^Exemple\s*:\s*/i, ""))}</span></div>` : ""}${definition.rule ? `<div class="atlas-help-rule">${escapeHtml(definition.rule)}</div>` : ""}`;
}

function atlasPositionHelpLayer(layer, target, pointer = null) {
  layer.hidden = false;
  layer.style.visibility = "hidden";
  const measured = layer.getBoundingClientRect();
  const margin = 12;
  let left;
  let top;
  if (pointer && Number.isFinite(pointer.clientX) && Number.isFinite(pointer.clientY)) {
    left = pointer.clientX + 18;
    top = pointer.clientY + 18;
  } else {
    const rect = target.getBoundingClientRect();
    left = rect.right + margin;
    top = rect.top;
    if (left + measured.width > window.innerWidth - margin) left = rect.left - measured.width - margin;
  }
  left = clamp(margin, Math.max(margin, window.innerWidth - measured.width - margin), left);
  top = clamp(margin, Math.max(margin, window.innerHeight - measured.height - margin), top);
  layer.style.left = `${Math.round(left)}px`;
  layer.style.top = `${Math.round(top)}px`;
  layer.style.visibility = "visible";
}

function atlasShowHelpLayer(target, pointer = null) {
  window.clearTimeout(atlasHelpHideTimer);
  const layer = document.getElementById("atlasHelpLayer");
  const live = document.getElementById("atlasHelpLive");
  if (!layer || !target) return;
  const definition = target.matches?.("[data-market-help-id]") ? atlasMarketHelpDefinition(target) : atlasHelpDefinitionFor(target);
  if (!definition) return;
  if (atlasHelpActiveTarget && atlasHelpActiveTarget !== target) atlasRestoreHelpDescription(atlasHelpActiveTarget);
  atlasHelpActiveTarget = target;
  layer.innerHTML = atlasHelpMarkup(definition);
  if (definition.marketCoinId) layer.dataset.marketHelpCoinId = definition.marketCoinId;
  else delete layer.dataset.marketHelpCoinId;
  layer.setAttribute("aria-hidden", "false");
  if (!("atlasHelpOriginalDescribedby" in target.dataset)) {
    target.dataset.atlasHelpOriginalDescribedby = target.getAttribute("aria-describedby") || "";
  }
  const describedBy = new Set((target.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
  describedBy.add("atlasHelpLayer");
  target.setAttribute("aria-describedby", [...describedBy].join(" "));
  if (live) live.textContent = definition.liveText || `${definition.title}. ${definition.body}${definition.example ? ` ${definition.example}` : ""}`;
  atlasPositionHelpLayer(layer, target, pointer);
}

function atlasRestoreHelpDescription(target) {
  if (!target) return;
  const original = target.dataset.atlasHelpOriginalDescribedby;
  if (original) target.setAttribute("aria-describedby", original);
  else target.removeAttribute("aria-describedby");
  delete target.dataset.atlasHelpOriginalDescribedby;
}

function atlasHideHelpLayer(immediate = false) {
  const hide = () => {
    const layer = document.getElementById("atlasHelpLayer");
    if (layer) {
      layer.hidden = true;
      layer.setAttribute("aria-hidden", "true");
      delete layer.dataset.marketHelpCoinId;
    }
    atlasRestoreHelpDescription(atlasHelpActiveTarget);
    atlasHelpActiveTarget = null;
  };
  window.clearTimeout(atlasHelpHideTimer);
  if (immediate) hide();
  else atlasHelpHideTimer = window.setTimeout(hide, 110);
}

function initAtlasHelpLayerV1() {
  document.addEventListener("pointerover", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target) return;
    if (atlasHelpActiveTarget === target) return;
    atlasShowHelpLayer(target, event);
  });
  document.addEventListener("pointerout", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target || target !== atlasHelpActiveTarget) return;
    if (event.relatedTarget instanceof Node && target.contains(event.relatedTarget)) return;
    atlasHideHelpLayer();
  });
  document.addEventListener("focusin", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (target) atlasShowHelpLayer(target);
  });
  document.addEventListener("focusout", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target || target !== atlasHelpActiveTarget) return;
    atlasHideHelpLayer();
  });
  document.addEventListener("keydown", event => {
    if (event.key === "Escape") atlasHideHelpLayer(true);
  });
  window.addEventListener("scroll", () => atlasHideHelpLayer(true), { passive: true });
  window.addEventListener("resize", () => atlasHideHelpLayer(true), { passive: true });
}

els.btnSourceDockRefresh?.addEventListener("click", () => {
  const coin = getSelectedCoin() || state.coins[0] || null;
  if (!coin) return;
  atlasSourceDockClearRetryTimer();
  delete state.sourceDock.nextRetryAt[coin.id];
  void atlasLoadSourceDockMetadata(coin, { force: true });
});

els.sourceDockPortals?.addEventListener("click", event => {
  const portal = event.target.closest?.("[data-portal-kind]");
  if (!portal || portal.classList.contains("is-disabled")) return;
  const coin = getSelectedCoin() || null;
  atlasTrackAudience("source_dock_portal_opened", {
    asset: coin?.id || null,
    portal: portal.dataset.portalKind || null
  });
});

document.addEventListener("visibilitychange", () => {
  renderAutoReader();
  renderMemoryTruth();
  if (document.hidden) {
    atlasSourceDockClearRetryTimer();
    return;
  }
  const coin = getSelectedCoin() || null;
  if (!coin || state.sourceDock.activeCoinId !== coin.id) return;
  if (atlasSourceDockRetryRemaining(coin.id) <= 0 && state.sourceDock.failures?.[coin.id]) {
    void atlasLoadSourceDockMetadata(coin, { retry: true });
  } else {
    atlasSourceDockScheduleRetry(coin);
  }
});

initAtlasCleanLensPanel();
initAtlasDetailWindows();
initNewsSentinelV1();
initAtlasHelpLayerV1();


/* =========================================================
   Build 28.1.44 — Single-Line Home + Admin Command Bar + Graph Three-State
   Interface envelope only. Protected Graphique, Détail actif,
   Target Top 5, Market Flow and Market internals stay unchanged.
   ========================================================= */
const ATLAS_ADMIN_CENTER_KEY = "atlas.admin.command.center.open.v1";
const ATLAS_ADMIN_CENTER_TARGET_KEY = "atlas.admin.command.center.target.v1";
const ATLAS_ADMIN_MODULE_KEY = "atlas.admin.last.module.v1";
const ATLAS_ADMIN_GRAPH_MODE_KEY = "atlas.admin.graph.mode.v2";
const ATLAS_ADMIN_GRAPH_MODES = Object.freeze(["normal", "focus", "closed"]);
const ATLAS_ADMIN_CLUSTERS = Object.freeze(["decision", "analysis", "system", "projects"]);

/* Build 28.1.88R4 — restauration de l’entrée Administration.
   Un ancien workspace public ne doit jamais annuler l’ouverture demandée
   juste après la validation du mot de passe Christophe. */
let atlasAdminForceWorkspacePending = false;
let atlasAdminForceWorkspaceTimer = 0;

function atlasAdminForceWorkspaceOpen(durationMs = 120000) {
  atlasAdminForceWorkspacePending = true;
  window.clearTimeout(atlasAdminForceWorkspaceTimer);
  atlasAdminForceWorkspaceTimer = window.setTimeout(() => {
    atlasAdminForceWorkspacePending = false;
  }, Math.max(10000, Number(durationMs) || 120000));
}

function atlasAdminForceWorkspaceIsActive() {
  return atlasAdminForceWorkspacePending && atlasAccessIsAuthorized();
}

function atlasAdminForceWorkspaceRelease() {
  atlasAdminForceWorkspacePending = false;
  window.clearTimeout(atlasAdminForceWorkspaceTimer);
  atlasAdminForceWorkspaceTimer = 0;
}

function atlasAdminCenterSavedOpen() {
  try { return localStorage.getItem(ATLAS_ADMIN_CENTER_KEY) === "1"; }
  catch { return false; }
}

function atlasAdminCenterSavedTarget() {
  try {
    const target = localStorage.getItem(ATLAS_ADMIN_CENTER_TARGET_KEY) || "";
    return ATLAS_ADMIN_CLUSTERS.includes(target) ? target : "";
  } catch { return ""; }
}

function atlasAdminLastModuleRead() {
  try { return localStorage.getItem(ATLAS_ADMIN_MODULE_KEY) || ""; }
  catch { return ""; }
}

function atlasAdminLastModuleWrite(id) {
  const value = String(id || "").replace(/^#/, "");
  if (!value || !document.getElementById(value)) return;
  try { localStorage.setItem(ATLAS_ADMIN_MODULE_KEY, value); } catch {}
}

function atlasAdminClusterForModule(id) {
  const value = String(id || "").replace(/^#/, "");
  if (["watchlist", "decision-board", "news-sentinel", "nofomo"].includes(value)) return "decision";
  if (["math", "multi-horizon", "lecture-froide", "risques", "debutant"].includes(value)) return "analysis";
  if (["auto-reader", "shared-memory", "github-memory", "safety", "simulation", "commandes", "newsSourceRegistry", "news-plan", "local-ai-hub"].includes(value)) return "system";
  if (["missions-vie", "forge-aerith"].includes(value)) return "projects";
  return "";
}

function atlasAdminCenterElements() {
  return {
    dock: document.querySelector(".atlas-admin-dock"),
    drawer: document.getElementById("atlasAdminCenterDrawer"),
    toggle: document.getElementById("atlasAdminCenterToggle"),
    state: document.getElementById("atlasAdminCenterToggleState"),
    close: document.getElementById("atlasAdminCenterClose")
  };
}

function atlasAdminCenterSet(open, options = {}) {
  const { drawer, toggle, state } = atlasAdminCenterElements();
  if (!drawer || !toggle) return;

  const next = !!open && atlasV2IsExpandedMode();
  const requestedTarget = String(options.target || "");
  const target = ATLAS_ADMIN_CLUSTERS.includes(requestedTarget)
    ? requestedTarget
    : next
      ? atlasAdminCenterSavedTarget()
      : "";

  drawer.hidden = !next;
  toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (state) state.textContent = next ? "Replier −" : "Déployer +";

  document.querySelectorAll("[data-admin-cluster-target]").forEach(button => {
    const selected = next && !!target && button.dataset.adminClusterTarget === target;
    button.setAttribute("aria-expanded", next ? "true" : "false");
    button.classList.toggle("is-selected", selected);
  });

  document.querySelectorAll("[data-admin-cluster]").forEach(cluster => {
    cluster.classList.toggle("is-targeted", next && !!target && cluster.dataset.adminCluster === target);
  });

  if (target) drawer.dataset.activeCluster = target;
  document.body.classList.toggle("atlas-admin-center-open", next);

  if (options.persist !== false) {
    try {
      localStorage.setItem(ATLAS_ADMIN_CENTER_KEY, next ? "1" : "0");
      if (target) localStorage.setItem(ATLAS_ADMIN_CENTER_TARGET_KEY, target);
    } catch {}
  }

  if (next && target && options.scrollTarget !== false) {
    const cluster = drawer.querySelector(`[data-admin-cluster="${target}"]`);
    if (cluster) {
      window.setTimeout(() => {
        cluster.scrollIntoView({
          block: "nearest",
          inline: "nearest",
          behavior: options.instant ? "auto" : "smooth"
        });
      }, 30);
    }
  }

  window.dispatchEvent(new CustomEvent("atlas:admin-center", {
    detail: { open: next, target: target || drawer.dataset.activeCluster || "" }
  }));
}

function atlasAdminOpenWorkspace(options = {}) {
  if (!atlasAccessIsAuthorized()) return false;

  if (atlasV2Mode() !== "advanced") {
    atlasV2WriteSetting(ATLAS_V2_MODE_KEY, "advanced");
    atlasV2ApplyMode("advanced", { persist: false, silentAuth: true });
  }

  const lastModule = atlasAdminLastModuleRead();
  const target = atlasAdminClusterForModule(lastModule)
    || atlasAdminCenterSavedTarget()
    || "analysis";

  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  if (selector && lastModule && [...selector.options].some(option => option.value === lastModule)) {
    selector.value = lastModule;
  }

  atlasAdminCenterSet(true, {
    persist: true,
    target,
    scrollTarget: false,
    instant: true
  });

  return true;
}

function initAtlasAdminCommandCenter() {
  const { drawer, toggle, close } = atlasAdminCenterElements();
  if (!drawer || !toggle) return;
  if (drawer.parentElement !== document.body) document.body.appendChild(drawer);

  const restoreCenter = () => {
    if (!atlasV2IsExpandedMode()) {
      atlasAdminCenterSet(false, { persist: false, scrollTarget: false });
      return;
    }
    const forcedOpen = atlasAdminForceWorkspaceIsActive();
    atlasAdminCenterSet(forcedOpen || atlasAdminCenterSavedOpen(), {
      persist: forcedOpen,
      target: forcedOpen
        ? (atlasAdminClusterForModule(atlasAdminLastModuleRead()) || atlasAdminCenterSavedTarget() || "analysis")
        : atlasAdminCenterSavedTarget(),
      scrollTarget: false,
      instant: true
    });
  };

  toggle.addEventListener("click", () => atlasAdminCenterSet(drawer.hidden));
  close?.addEventListener("click", () => atlasAdminCenterSet(false));

  document.querySelectorAll("[data-admin-cluster-target]").forEach(button => {
    button.addEventListener("click", () => {
      const target = button.dataset.adminClusterTarget || "";
      const alreadyOpen = !drawer.hidden;
      const alreadySelected = button.classList.contains("is-selected");
      if (alreadyOpen && alreadySelected) atlasAdminCenterSet(false);
      else atlasAdminCenterSet(true, { target });
    });
  });

  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  selector?.addEventListener("change", () => {
    if (selector.value) atlasAdminLastModuleWrite(selector.value);
  });

  drawer.addEventListener("click", event => {
    const link = event.target.closest("a[href^='#']");
    if (!link) return;
    const id = String(link.getAttribute("href") || "").replace(/^#/, "");
    if (id) atlasAdminLastModuleWrite(id);
    atlasAdminCenterSet(false);
  });

  document.addEventListener("pointerdown", event => {
    const { dock } = atlasAdminCenterElements();
    if (!drawer.hidden && dock && !dock.contains(event.target) && !drawer.contains(event.target)) {
      atlasAdminCenterSet(false);
    }
  });

  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && !drawer.hidden) atlasAdminCenterSet(false);
  });

  window.addEventListener("atlas:v2mode", event => {
    if (!atlasV2IsExpandedMode(event.detail?.mode)) {
      atlasAdminCenterSet(false, { persist: false, scrollTarget: false });
    } else {
      window.requestAnimationFrame(restoreCenter);
    }
  });

  window.requestAnimationFrame(restoreCenter);
}

function atlasAdminGraphRead() {
  try {
    const saved = localStorage.getItem(ATLAS_ADMIN_GRAPH_MODE_KEY);
    if (ATLAS_ADMIN_GRAPH_MODES.includes(saved)) return saved;
    const legacy = localStorage.getItem("atlas.admin.graph.open.v1");
    return legacy === "0" ? "closed" : "normal";
  } catch { return "normal"; }
}

function atlasAdminGraphLabel(mode) {
  return mode === "focus" ? "Focus" : mode === "closed" ? "Fermé" : "Normal";
}

function atlasAdminGraphNext(mode) {
  const index = ATLAS_ADMIN_GRAPH_MODES.indexOf(mode);
  return ATLAS_ADMIN_GRAPH_MODES[(index + 1 + ATLAS_ADMIN_GRAPH_MODES.length) % ATLAS_ADMIN_GRAPH_MODES.length];
}

function atlasAdminGraphSyncControls(mode) {
  const label = atlasAdminGraphLabel(mode);
  const cycle = document.querySelector("[data-admin-graph-cycle]");
  if (cycle) {
    cycle.classList.remove("is-normal", "is-focus", "is-closed", "is-open");
    cycle.classList.add(`is-${mode}`);
    cycle.setAttribute("aria-pressed", mode === "closed" ? "false" : "true");
    const compactState = cycle.querySelector("b");
    if (compactState) compactState.textContent = label;
    const nextLabel = atlasAdminGraphLabel(atlasAdminGraphNext(mode));
    cycle.setAttribute("aria-label", `Vue graphique en mode ${label}. Passer au mode ${nextLabel}.`);
  }
  document.querySelectorAll("[data-admin-graph-mode]").forEach(button => {
    const active = button.dataset.adminGraphMode === mode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function atlasAdminGraphSet(mode, options = {}) {
  const zone = document.getElementById("market-zone");
  if (!zone) return;
  const next = ATLAS_ADMIN_GRAPH_MODES.includes(mode) ? mode : "normal";
  zone.classList.remove("atlas-graph-closed", "atlas-graph-mode-normal", "atlas-graph-mode-focus", "atlas-graph-mode-closed");
  zone.classList.add(`atlas-graph-mode-${next}`);
  zone.dataset.graphMode = next;
  zone.dataset.graphOpen = next === "closed" ? "false" : "true";
  atlasAdminGraphSyncControls(next);
  if (options.closeCenter !== false) atlasAdminCenterSet(false, { persist: false });
  if (options.persist !== false && atlasV2IsExpandedMode()) {
    try { localStorage.setItem(ATLAS_ADMIN_GRAPH_MODE_KEY, next); } catch {}
  }
  if (options.scroll !== false) window.requestAnimationFrame(() => {
    const behavior = options.instant ? "auto" : "smooth";
    if (next === "closed") {
      document.getElementById("market-workspace")?.scrollIntoView({ block: "start", behavior });
    } else {
      document.getElementById("analyste")?.scrollIntoView({ block: "start", behavior });
      try { atlasScheduleStableChartResize(); } catch {}
      window.setTimeout(() => { try { atlasScheduleStableChartResize(); } catch {} }, 240);
    }
  });
  window.dispatchEvent(new CustomEvent("atlas:admin-graph", { detail: { mode: next, open: next !== "closed" } }));
}

function initAtlasAdminGraphToggle() {
  const zone = document.getElementById("market-zone");
  if (!zone) return;

  document.querySelector("[data-admin-graph-cycle]")?.addEventListener("click", () => {
    const current = zone.dataset.graphMode || "normal";
    atlasAdminGraphSet(atlasAdminGraphNext(current));
  });

  document.querySelectorAll("[data-admin-graph-mode]").forEach(button => {
    button.addEventListener("click", () => atlasAdminGraphSet(button.dataset.adminGraphMode || "normal"));
  });

  document.querySelectorAll('a[href="#analyste"]').forEach(link => {
    link.addEventListener("click", () => {
      if ((zone.dataset.graphMode || "normal") === "closed") {
        atlasAdminGraphSet("normal", { persist: atlasV2IsExpandedMode(), instant: true });
      }
    });
  });

  window.addEventListener("atlas:v2mode", event => {
    const mode = event.detail?.mode;
    if (mode === "essential") {
      atlasAdminGraphSet("normal", { persist: false, instant: true, scroll: false, closeCenter: false });
    } else if (atlasV2IsExpandedMode(mode)) {
      atlasAdminGraphSet(atlasAdminGraphRead(), { persist: false, instant: true, scroll: false, closeCenter: false });
    }
  });

  const initialMode = atlasV2IsExpandedMode() ? atlasAdminGraphRead() : "normal";
  atlasAdminGraphSet(initialMode, { persist: false, instant: true, scroll: false, closeCenter: false });
}

initAtlasAdminCommandCenter();
initAtlasAdminGraphToggle();








/* =========================================================
   Build 28.1.48 — Toggleable enriched quantitative overlay
   ========================================================= */
let atlasChartOverlayLastReady = null;

function atlasChartOverlayModeLabelFor(preset, count) {
  if (count <= 1) return "SOLO";
  if (preset === "rank-3") return "TOP 3";
  if (preset === "rank-5") return "TOP 5";
  if (preset === "gainers") return "HAUSSES 5";
  if (preset === "losers") return "BAISSES 5";
  if (preset === "volume") return "VOLUMES 5";
  return `${count} SÉRIES`;
}

function atlasChartOverlayCaptureReady(chart) {
  if (!chart?.result || chart.status !== "ready") return null;

  const comparison = chart.result?.comparison && Array.isArray(chart.result.entries);
  const entries = comparison ? chart.result.entries : [];
  const preset = String(state.dataBroker?.comparison?.preset || (comparison ? "manual" : "solo"));
  const ids = comparison
    ? entries.map(entry => entry?.coin?.id).filter(Boolean)
    : [chart.result?.coin?.id || chart.coinId].filter(Boolean);

  atlasChartOverlayLastReady = {
    chart: { ...chart, result: chart.result },
    period: Number(chart.period || state.chartPeriodDays || 1),
    preset,
    count: ids.length || (comparison ? entries.length : 1),
    modeLabel: atlasChartOverlayModeLabelFor(preset, ids.length || entries.length || 1),
    viewLabel: comparison || atlasChartV2EffectiveView() === "base100" ? "BASE 100" : "PRIX EUR",
    scaleLabel: comparison || atlasChartV2EffectiveScale() !== "logarithmic" ? "NORMALE" : "LOG",
  };

  return atlasChartOverlayLastReady;
}

function atlasChartOverlayTruthKey(label) {
  const value = String(label || "").toLowerCase();
  if (/indisponible|échec|aucune|attente|non mesur/.test(value)) return "unavailable";
  if (/archive|daté|datée/.test(value)) return "archive";
  if (/cache|retard/.test(value)) return "cache";
  if (/direct|coin.?gecko/.test(value)) return "direct";
  return "archive";
}

function atlasChartOverlaySet(titleHtml, seriesHtml, summaryHtml, truthLabel = "", layout = "comparison") {
  const overlay = document.getElementById("atlasChartInsightOverlay");
  const titleNode = document.getElementById("atlasChartInsightOverlayTitle");
  const seriesNode = document.getElementById("atlasChartInsightOverlaySeries");
  const summaryNode = document.getElementById("atlasChartInsightOverlaySummary");
  if (!overlay || !titleNode || !seriesNode || !summaryNode) return;

  titleNode.innerHTML = titleHtml;
  seriesNode.innerHTML = seriesHtml;
  summaryNode.innerHTML = summaryHtml;
  overlay.dataset.truth = atlasChartOverlayTruthKey(truthLabel);
  overlay.dataset.layout = layout;
  const chartShell = overlay.closest(".chart-shell");
  if (chartShell) chartShell.dataset.analysisLayout = layout;
  overlay.hidden = state.chartViewV2.analysis === false;
  overlay.setAttribute("aria-hidden", overlay.hidden ? "true" : "false");
}

function atlasChartOverlayModeLabel() {
  const count = atlasComparisonIds().length;
  const preset = String(state.dataBroker?.comparison?.preset || "solo");
  return atlasChartOverlayModeLabelFor(preset, count);
}

function atlasChartOverlayTruth(result, period) {
  try {
    return atlasChartTruth(result, period);
  } catch {
    return { label: "source non mesurée" };
  }
}

function atlasChartOverlayOrderedEntries(result) {
  const order = atlasComparisonIds();
  const entries = Array.isArray(result?.entries) ? result.entries : [];
  return [...entries].sort((a, b) => {
    const ai = order.indexOf(a?.coin?.id);
    const bi = order.indexOf(b?.coin?.id);
    return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi);
  });
}

function atlasChartOverlayPointCoverage(rows) {
  const values = rows.map(row => row.points).filter(value => Number.isFinite(value) && value > 0);
  if (!values.length) return "points non mesurés";
  const min = Math.min(...values);
  const max = Math.max(...values);
  return min === max ? `${min} pts/série` : `${min}–${max} pts/série`;
}

function atlasChartOverlayCoinColor(coin, index = 0) {
  try {
    return atlasCryptoPalette(coin || {}, index).primary || "#eaf8ff";
  } catch {
    return "#eaf8ff";
  }
}

function atlasChartOverlayCoinHtml(row, index, value) {
  const color = atlasChartOverlayCoinColor(row.coin, index);
  return `<span class="atlas-hud-coin" style="--coin-color:${escapeHtml(color)}">`
    + `<b>${escapeHtml(row.symbol)}</b><em>${escapeHtml(value)}</em></span>`;
}

function atlasChartOverlayTitleHtml(context, mode, truthLabel) {
  return `<span class="atlas-hud-context">${escapeHtml(context)}</span>`
    + ` · <span class="atlas-hud-mode">${escapeHtml(mode)}</span>`
    + `<span class="atlas-hud-truth">${escapeHtml(String(truthLabel || "source non mesurée").toUpperCase())}</span>`;
}

function atlasChartOverlayComparison(chart, period, options = {}) {
  const result = chart?.result || {};
  const entries = atlasChartOverlayOrderedEntries(result);
  const selectedCount = Number(options.selectedCount || atlasComparisonIds().length || entries.length);
  const periodLabel = atlasChartPeriodLabel(period);
  const preset = String(options.preset || state.dataBroker?.comparison?.preset || "manual");
  const truth = atlasChartOverlayTruth(
    { comparison: true, entries, sourceMode: "comparison-base100" },
    period
  );
  const scaleLabel = String(options.scaleLabel || (atlasChartV2EffectiveScale() === "logarithmic" ? "LOG" : "NORMALE"));

  const rows = entries.map(entry => {
    const coin = entry?.coin || {};
    const marketCoin = state.coins.find(item => item.id === coin.id) || coin;
    const metrics = entry?.result?.integrity?.metrics || {};
    return {
      coin,
      symbol: String(coin.symbol || coin.name || "ACTIF").toUpperCase(),
      change: Number.isFinite(Number(entry?.atlasMarketMetric))
        ? Number(entry.atlasMarketMetric)
        : Number(metrics.changePct),
      volume: Number.isFinite(Number(entry?.atlasMarketMetric)) && preset === "volume"
        ? Number(entry.atlasMarketMetric)
        : Number(marketCoin?.volume24h),
      timestamp: Number(metrics.lastTimestamp || 0),
      points: Number(metrics.pointCount || entry?.result?.series?.length || 0),
    };
  });

  const seriesLine = rows.map((row, index) => {
    const value = preset === "volume"
      ? (Number.isFinite(row.volume) ? fmtCompactEUR.format(row.volume) : "non mesuré")
      : (Number.isFinite(row.change) ? fmtPct(row.change) : "non mesuré");
    return atlasChartOverlayCoinHtml(row, index, value);
  }).join("");

  const oldest = rows.map(row => row.timestamp).filter(value => value > 0);
  const oldestText = oldest.length
    ? atlasExactTimestampLabel(Math.min(...oldest))
    : "horodatage inconnu";
  const coverage = atlasChartOverlayPointCoverage(rows);

  const scannerHistorySummary = String(
    result?.scanner?.historySummary || ""
  ).trim();
  const scannerMarketBasis = String(
    result?.scanner?.marketBasisLabel || ""
  ).trim();
  const providerLabel = atlasChartProviderLabel({
    comparison: true,
    entries
  });

  let primarySummaryItems = [
    {
      className: "atlas-hud-detail",
      text: `${coverage} · ${providerLabel} EUR`
    }
  ];
  let secondarySummaryItems = [
    {
      className: "atlas-hud-oldest",
      label: "plus ancienne",
      value: oldestText,
      dateTime: true
    }
  ];

  if (scannerHistorySummary) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text: `historiques ${scannerHistorySummary}`
    });
  }
  if (scannerMarketBasis) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text: `classement ${scannerMarketBasis}`
    });
  }

  if (preset === "volume") {
    const valid = rows
      .filter(row => Number.isFinite(row.volume))
      .sort((a, b) => b.volume - a.volume);

    if (valid.length) {
      primarySummaryItems = [
        {
          className: "atlas-hud-leader",
          text:
            `Volume supérieur ${valid[0].symbol} `
            + fmtCompactEUR.format(valid[0].volume)
        }
      ];

      if (valid.length > 1) {
        primarySummaryItems.push({
          className: "atlas-hud-laggard",
          text:
            `inférieur ${valid[valid.length - 1].symbol} `
            + fmtCompactEUR.format(valid[valid.length - 1].volume)
        });
      }

      secondarySummaryItems = [
        {
          className: "atlas-hud-detail",
          text: coverage
        },
        {
          className: "atlas-hud-detail",
          text: `${providerLabel} EUR`
        },
        {
          className: "atlas-hud-oldest",
          label: "plus ancienne",
          value: oldestText,
          dateTime: true
        }
      ];
    }
  } else {
    const valid = rows
      .filter(row => Number.isFinite(row.change))
      .sort((a, b) => b.change - a.change);

    if (valid.length) {
      const max = valid[0].change;
      const min = valid[valid.length - 1].change;
      const leaders = valid
        .filter(row => Math.abs(row.change - max) < 0.005)
        .map(row => row.symbol)
        .join("/");
      const laggards = valid
        .filter(row => Math.abs(row.change - min) < 0.005)
        .map(row => row.symbol)
        .join("/");
      const gap = max - min;

      primarySummaryItems = [
        {
          className: "atlas-hud-leader",
          text: `Leader ${leaders} ${fmtPct(max)}`
        },
        {
          className: "atlas-hud-laggard",
          text: `retard ${laggards} ${fmtPct(min)}`
        },
        {
          className: "atlas-hud-detail",
          text: `écart ${gap.toFixed(2)} pt`
        }
      ];

      secondarySummaryItems = [
        {
          className: "atlas-hud-detail",
          text: coverage
        },
        {
          className: "atlas-hud-oldest",
          label: "plus ancienne",
          value: oldestText,
          dateTime: true
        }
      ];
    }
  }

  if (options.preserved) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text:
        `mise à jour ${
          atlasChartPeriodLabel(
            Number(
              options.requestedPeriod
              || state.chartPeriodDays
              || period
            )
          )
        } en cours`
    });
  }

  const summaryItemHtml = item => {
    const className = escapeHtml(
      String(item?.className || "atlas-hud-detail")
    );

    if (item?.dateTime) {
      return `<span class="${className}">`
        + `${escapeHtml(String(item.label || ""))} `
        + `<time class="atlas-hud-datetime">`
        + `${escapeHtml(String(item.value || "horodatage inconnu"))}`
        + `</time></span>`;
    }

    return `<span class="${className}">`
      + `${escapeHtml(String(item?.text || ""))}`
      + `</span>`;
  };

  const summaryHtml =
    `<span class="atlas-hud-summary-row atlas-hud-summary-primary">`
      + primarySummaryItems.map(summaryItemHtml).join("")
    + `</span>`
    + `<span class="atlas-hud-summary-row atlas-hud-summary-secondary">`
      + secondarySummaryItems.map(summaryItemHtml).join("")
    + `</span>`;

  const truthLabel = String(truth.label || "source non mesurée");
  const displayedTruthLabel = options.preserved
    ? "historique conservé"
    : truthLabel;
  const displayedModeLabel = String(
    options.modeLabel || atlasChartOverlayModeLabel()
  );
  const titleHtml = atlasChartOverlayTitleHtml(
    `${displayedModeLabel} · ${periodLabel} · BASE 100`,
    `${scaleLabel} · ${entries.length}/${selectedCount} SÉRIES`,
    displayedTruthLabel
  );

  atlasChartOverlaySet(
    titleHtml,
    seriesLine || '<span class="atlas-hud-detail">Mesures non disponibles</span>',
    summaryHtml,
    options.preserved ? "cache retardé" : truthLabel,
    "comparison"
  );
}

function atlasChartOverlaySolo(chart, period, options = {}) {
  const result = chart?.result || {};
  const coin = result?.coin || getSelectedCoin() || {};
  const metrics = result?.integrity?.metrics || {};
  const periodLabel = atlasChartPeriodLabel(period);
  const view = String(options.viewLabel || (atlasChartV2EffectiveView() === "base100" ? "BASE 100" : "PRIX EUR"));
  const scaleLabel = String(options.scaleLabel || (atlasChartV2EffectiveScale() === "logarithmic" ? "LOG" : "NORMALE"));
  const truth = atlasChartOverlayTruth(result, period);

  const first = Number(metrics.firstPrice);
  const last = Number(metrics.lastPrice);
  const min = Number(metrics.minPrice);
  const max = Number(metrics.maxPrice);
  const change = Number(metrics.changePct);
  const points = Number(metrics.pointCount || result?.series?.length || 0);
  const lastTimestamp = Number(metrics.lastTimestamp || 0);
  const amplitude = Number.isFinite(min) && min > 0 && Number.isFinite(max)
    ? (max - min) / min * 100
    : null;

  const symbol = String(coin?.symbol || "ACTIF").toUpperCase();
  const name = String(coin?.name || "Analyse du marché");
  const truthLabel = String(truth.label || "source non mesurée");
  const displayedTruthLabel = options.preserved ? "historique conservé" : truthLabel;

  const seriesParts = [];
  if (Number.isFinite(last)) seriesParts.push(atlasFormatEUR(last));
  if (Number.isFinite(change)) seriesParts.push(fmtPct(change));
  if (Number.isFinite(min)) seriesParts.push(`bas ${atlasFormatEUR(min)}`);
  if (Number.isFinite(max)) seriesParts.push(`haut ${atlasFormatEUR(max)}`);
  if (Number.isFinite(amplitude)) seriesParts.push(`amplitude ${amplitude.toFixed(2)} %`);

  const summaryParts = [];
  if (Number.isFinite(first)) summaryParts.push(`départ ${atlasFormatEUR(first)}`);
  if (Number.isFinite(last)) summaryParts.push(`dernière ${atlasFormatEUR(last)}`);
  if (points) summaryParts.push(`${points} points`);
  if (lastTimestamp > 0) summaryParts.push(`série ${atlasExactTimestampLabel(lastTimestamp)}`);
  summaryParts.push(`${atlasChartProviderLabel(result)} EUR`);

  const soloTitleHtml = atlasChartOverlayTitleHtml(
    `${symbol} · ${name} · ${periodLabel}`,
    `${view} · ${scaleLabel}`,
    displayedTruthLabel
  );

  const soloColor = atlasChartOverlayCoinColor(coin, 0);
  const soloSeriesHtml = `<span class="atlas-hud-coin" style="--coin-color:${escapeHtml(soloColor)}">`
    + `<b>${escapeHtml(symbol)}</b><em>${escapeHtml(seriesParts.join(" · ") || "Mesures historiques non disponibles")}</em></span>`;

  if (options.preserved) {
    summaryParts.push(`mise à jour ${atlasChartPeriodLabel(Number(options.requestedPeriod || state.chartPeriodDays || period))} en cours`);
  }

  atlasChartOverlaySet(
    soloTitleHtml,
    soloSeriesHtml,
    `<span class="atlas-hud-detail">${escapeHtml(summaryParts.join(" · "))}</span>`,
    options.preserved ? "cache retardé" : truthLabel,
    "solo"
  );
}

function atlasChartOverlayUpdate() {
  const chart = state.dataBroker?.chart;
  const requestedPeriod = Number(state.chartPeriodDays || 1);
  const chartReady = !!chart
    && chart.status === "ready"
    && atlasChartContextMatches(chart)
    && !!chart.result;

  if (chartReady) {
    atlasChartOverlayCaptureReady(chart);
  }

  if (state.chartViewV2.analysis === false) {
    const overlay = document.getElementById("atlasChartInsightOverlay");
    if (overlay) {
      overlay.hidden = true;
      overlay.setAttribute("aria-hidden", "true");
    }
    return;
  }

  if (chartReady) {
    if (chart.result?.comparison && Array.isArray(chart.result.entries)) {
      atlasChartOverlayComparison(chart, Number(chart.period || requestedPeriod));
    } else {
      atlasChartOverlaySolo(chart, Number(chart.period || requestedPeriod));
    }
    atlasSyncTargetTopFiveCycleLabel();
    return;
  }

  const displayedChartStillVisible = !!state.chartEngineV2?.realChart;
  const preserved = displayedChartStillVisible ? atlasChartOverlayLastReady : null;

  if (preserved?.chart?.result) {
    const options = {
      preserved: true,
      requestedPeriod,
      preset: preserved.preset,
      selectedCount: preserved.count,
      modeLabel: preserved.modeLabel,
      viewLabel: preserved.viewLabel,
      scaleLabel: preserved.scaleLabel,
    };

    if (preserved.chart.result?.comparison && Array.isArray(preserved.chart.result.entries)) {
      atlasChartOverlayComparison(preserved.chart, preserved.period, options);
    } else {
      atlasChartOverlaySolo(preserved.chart, preserved.period, options);
    }
    return;
  }

  atlasChartOverlaySet(
    `<span class="atlas-hud-context">ANALYSE DU MARCHÉ</span> · <span class="atlas-hud-mode">${escapeHtml(atlasChartPeriodLabel(requestedPeriod))}</span><span class="atlas-hud-truth">EN ATTENTE</span>`,
    '<span class="atlas-hud-detail">Première série réelle en cours de chargement</span>',
    '<span class="atlas-hud-detail">Aucune courbe valide n’est encore affichée · CoinGecko EUR</span>',
    "attente",
    "empty"
  );
}

const atlasChartOverlayCaption = document.getElementById("chartCaption");
if (atlasChartOverlayCaption) {
  new MutationObserver(() => atlasChartOverlayUpdate()).observe(
    atlasChartOverlayCaption,
    { childList: true, characterData: true, subtree: true }
  );
}

document.addEventListener("click", event => {
  if (event.target.closest(".period-btn, [data-chart-view], [data-chart-scale], .compare-btn, [data-compare-remove], [data-compare-primary]")) {
    window.setTimeout(atlasChartOverlayUpdate, 0);
    window.setTimeout(atlasChartOverlayUpdate, 360);
  }
});

window.addEventListener("atlas:admin-graph", () => atlasChartOverlayUpdate());
window.addEventListener("atlas:v2mode", () => atlasChartOverlayUpdate());
window.setTimeout(atlasChartOverlayUpdate, 0);
window.setTimeout(atlasChartOverlayUpdate, 800);





