/* =========================================================
   Build 28.1.52 — Forge header + 8-step workshop only
   The autonomous Forge remains complete in atlas_10_full.
   ========================================================= */
const atlasForgeFrame = document.getElementById("forgeAerithEmbedded");
const atlasForgeStage = document.getElementById("forgeEmbeddedStage");
const atlasForgeCollapse = document.getElementById("forge-aerith");
const atlasForgeStatus = document.getElementById("forgeEmbeddedStatus");
const atlasForgeTitle = document.getElementById("forge-aerith-title");

let atlasForgeResizeObserver = null;
let atlasForgeMutationObserver = null;
let atlasForgeResizeTimer = 0;
let atlasForgeLastHeight = 0;
let atlasForgePrepared = false;

function atlasForgeSetStatus(message, state = "loading") {
  if (atlasForgeStatus) atlasForgeStatus.textContent = message;
  if (atlasForgeStage) atlasForgeStage.dataset.state = state;
}

function atlasForgeInjectWorkshopMode() {
  if (!atlasForgeFrame) return null;

  const forgeDocument = atlasForgeFrame.contentDocument;
  if (!forgeDocument?.head || !forgeDocument?.body) return null;

  forgeDocument.body.classList.add("agent-crypto-workshop-embed");

  let styleNode = forgeDocument.getElementById("agentCryptoWorkshopEmbedStyle");
  if (!styleNode) {
    styleNode = forgeDocument.createElement("style");
    styleNode.id = "agentCryptoWorkshopEmbedStyle";
    styleNode.textContent = `
      html {
        scroll-behavior: auto !important;
        background: #060914 !important;
        overflow-x: hidden !important;
      }

      body.agent-crypto-workshop-embed {
        margin: 0 !important;
        min-height: 0 !important;
        background: #060914 !important;
        overflow: hidden !important;
      }

      body.agent-crypto-workshop-embed > .diagnostic {
        display: none !important;
      }

      body.agent-crypto-workshop-embed > header.topbar {
        position: relative !important;
        inset: auto !important;
        z-index: 30 !important;
        width: 100% !important;
      }

      body.agent-crypto-workshop-embed > main#top {
        min-height: 0 !important;
        padding-top: 0 !important;
      }

      body.agent-crypto-workshop-embed > main#top > section:not(#unifiedForge) {
        display: none !important;
      }

      body.agent-crypto-workshop-embed #unifiedForge {
        display: grid !important;
        min-height: 0 !important;
        margin-top: 0 !important;
        padding-top: 10px !important;
      }

      body.agent-crypto-workshop-embed {
        font-size: 17px !important;
      }

      body.agent-crypto-workshop-embed header.topbar,
      body.agent-crypto-workshop-embed #unifiedForge {
        font-size: 1.08em !important;
      }

      body.agent-crypto-workshop-embed #unifiedForge p,
      body.agent-crypto-workshop-embed #unifiedForge li,
      body.agent-crypto-workshop-embed #unifiedForge label,
      body.agent-crypto-workshop-embed #unifiedForge button,
      body.agent-crypto-workshop-embed #unifiedForge input,
      body.agent-crypto-workshop-embed #unifiedForge textarea,
      body.agent-crypto-workshop-embed #unifiedForge select,
      body.agent-crypto-workshop-embed #unifiedForge small,
      body.agent-crypto-workshop-embed #unifiedForge span {
        font-size: max(14px, 1em) !important;
        line-height: 1.45 !important;
      }

      body.agent-crypto-workshop-embed #unifiedForge h1 {
        font-size: clamp(28px, 3vw, 42px) !important;
      }

      body.agent-crypto-workshop-embed #unifiedForge h2 {
        font-size: clamp(22px, 2.25vw, 32px) !important;
      }

      body.agent-crypto-workshop-embed #unifiedForge h3 {
        font-size: clamp(18px, 1.8vw, 25px) !important;
      }

      body.agent-crypto-workshop-embed footer {
        display: none !important;
      }
    `;
    forgeDocument.head.appendChild(styleNode);
  }

  const fullForgeUrl = new URL("../atlas_10_full/index.html", window.location.href);

  forgeDocument.querySelectorAll('header.topbar nav a[href="#lineage"], header.topbar nav a[href="#constellation"], header.topbar nav a[href="#profiles"]').forEach(link => {
    const hash = link.getAttribute("href") || "";
    link.href = `${fullForgeUrl.href}${hash}`;
    link.target = "_blank";
    link.rel = "noopener noreferrer";
    link.setAttribute("aria-label", `${link.textContent?.trim() || "Section"} — ouvrir dans la Forge complète`);
  });

  const agentCryptoLink = forgeDocument.querySelector('header.topbar nav a[href="../web/index.html"]');
  if (agentCryptoLink) {
    agentCryptoLink.target = "_top";
    agentCryptoLink.rel = "noopener";
  }

  const workshopLink = forgeDocument.querySelector('header.topbar nav a[href="#unifiedForge"]');
  if (workshopLink) workshopLink.removeAttribute("target");

  const exportLink = forgeDocument.querySelector('header.topbar nav a[href="#exportCenter"]');
  if (exportLink) exportLink.removeAttribute("target");

  const buildBadge = forgeDocument.getElementById("buildBadge");
  const forgeVersion = String(buildBadge?.textContent || "V3").trim();

  if (atlasForgeTitle) {
    atlasForgeTitle.textContent = `Forge d’Aerith Pro · Atelier Créatrice · ${forgeVersion}`;
  }
  atlasForgeSetStatus(`Atelier prêt · 8 étapes · ${forgeVersion}`, "ready");

  atlasForgePrepared = true;
  return forgeDocument;
}

function atlasMeasureForgeWorkshop() {
  if (!atlasForgeFrame) return;

  try {
    const forgeDocument = atlasForgeFrame.contentDocument;
    if (!forgeDocument) return;

    const header = forgeDocument.querySelector("body > header.topbar");
    const workshop = forgeDocument.getElementById("unifiedForge");
    const body = forgeDocument.body;
    const root = forgeDocument.documentElement;

    const visibleBottom = Math.max(
      header?.getBoundingClientRect().bottom || 0,
      workshop?.getBoundingClientRect().bottom || 0,
      body?.scrollHeight || 0,
      root?.scrollHeight || 0,
      940
    );

    const measuredHeight = Math.ceil(visibleBottom + 4);

    if (Math.abs(measuredHeight - atlasForgeLastHeight) > 3) {
      atlasForgeLastHeight = measuredHeight;
      atlasForgeFrame.style.height = `${measuredHeight}px`;
    }
  } catch (error) {
    atlasForgeSetStatus("Atelier chargé · hauteur automatique indisponible", "warning");
    console.warn("Redimensionnement Atelier Forge indisponible :", error);
  }
}

function atlasScheduleForgeResize(delay = 70) {
  window.clearTimeout(atlasForgeResizeTimer);
  atlasForgeResizeTimer = window.setTimeout(() => {
    window.requestAnimationFrame(atlasMeasureForgeWorkshop);
  }, delay);
}

function atlasObserveForgeWorkshop(forgeDocument) {
  atlasForgeResizeObserver?.disconnect();
  atlasForgeMutationObserver?.disconnect();

  const workshop = forgeDocument?.getElementById("unifiedForge");
  if (!workshop) return;

  if ("ResizeObserver" in window) {
    atlasForgeResizeObserver = new ResizeObserver(() => atlasScheduleForgeResize(50));
    atlasForgeResizeObserver.observe(workshop);
    const topbar = forgeDocument.querySelector("body > header.topbar");
    if (topbar) atlasForgeResizeObserver.observe(topbar);
  }

  atlasForgeMutationObserver = new MutationObserver(() => atlasScheduleForgeResize(90));
  atlasForgeMutationObserver.observe(workshop, {
    childList: true,
    subtree: true,
    attributes: true,
    characterData: false,
  });

  forgeDocument.addEventListener("click", () => atlasScheduleForgeResize(130), true);
  forgeDocument.addEventListener("change", () => atlasScheduleForgeResize(130), true);
  forgeDocument.addEventListener("input", () => atlasScheduleForgeResize(180), true);
}

atlasForgeFrame?.addEventListener("load", () => {
  try {
    const forgeDocument = atlasForgeInjectWorkshopMode();
    if (!forgeDocument) {
      atlasForgeSetStatus("Source Forge indisponible", "error");
      return;
    }

    atlasForgeStage?.classList.add("is-ready");
    atlasObserveForgeWorkshop(forgeDocument);

    atlasScheduleForgeResize(0);
    window.setTimeout(() => atlasScheduleForgeResize(0), 240);
    window.setTimeout(() => atlasScheduleForgeResize(0), 800);
    window.setTimeout(() => atlasScheduleForgeResize(0), 1600);
  } catch (error) {
    atlasForgeSetStatus("Source Forge indisponible · ouvrir la Forge complète", "error");
    console.warn("Préparation de l’Atelier Forge indisponible :", error);
  }
});

atlasForgeCollapse?.addEventListener("toggle", () => {
  if (atlasForgeCollapse.open) {
    if (!atlasForgePrepared) atlasForgeSetStatus("Chargement de l’atelier en huit étapes…", "loading");
    atlasScheduleForgeResize(40);
  }
});

window.addEventListener("resize", () => atlasScheduleForgeResize(90));
window.addEventListener("orientationchange", () => atlasScheduleForgeResize(180));


/* =========================================================
   Build 28.2.74 — Parallel Markets Foundation

   One chart area, two isolated domains:
   - Crypto remains the complete validated production market.
   - Metals is a no-fake-data foundation awaiting real adapters.

   Long press on the title or normal click on the visible domain badge:
   Crypto ↔ Metals.
   ========================================================= */

const ATLAS_PARALLEL_MARKET_HOLD_MS = 720;
let atlasParallelMarketHoldTimer = 0;
let atlasParallelMarketHoldConsumed = false;

function atlasParallelMarketSafeRead(key) {
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || "null");
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function atlasParallelMarketReadDomain() {
  try {
    const value = String(
      localStorage.getItem(ATLAS_PARALLEL_MARKET_DOMAIN_KEY) || ""
    ).trim();
    return ATLAS_PARALLEL_MARKET_DOMAINS.includes(value)
      ? value
      : "crypto";
  } catch {
    return "crypto";
  }
}

function atlasParallelMarketDomain() {
  return ATLAS_PARALLEL_MARKET_DOMAINS.includes(state.marketDomain)
    ? state.marketDomain
    : "crypto";
}

function atlasParallelMarketMetalsState() {
  return state.parallelMarkets.metals;
}

function atlasParallelMarketValidMetalIds(ids) {
  const available = new Set(ATLAS_METALS_ASSETS.map(asset => asset.id));
  const normalized = Array.isArray(ids)
    ? ids
        .map(id => String(id || ""))
        .filter(id => available.has(id))
        .filter((id, index, list) => list.indexOf(id) === index)
        .slice(0, ATLAS_METALS_ASSETS.length)
    : [];

  return normalized.length
    ? normalized
    : ATLAS_METALS_ASSETS.map(asset => asset.id);
}

function atlasParallelMarketMetalsRead() {
  const saved = atlasParallelMarketSafeRead(
    ATLAS_PARALLEL_MARKET_METALS_STATE_KEY
  );
  const metals = atlasParallelMarketMetalsState();
  if (!saved) {
    metals.period = 7;
    metals.resultVisibilityVersion = "28.2.62";
    return metals;
  }

  metals.period = [1, 7, 30, 90, 365].includes(Number(saved.period))
    ? Number(saved.period)
    : 7;
  const visibilityMigrated = String(saved.resultVisibilityVersion || "") === "28.2.61";
  if (!visibilityMigrated && metals.period === 1) metals.period = 7;
  metals.resultVisibilityVersion = "28.2.62";
  metals.view = saved.view === "base100" ? "base100" : "price";
  metals.scale = saved.scale === "logarithmic"
    ? "logarithmic"
    : "linear";
  metals.section = saved.section === "critical"
    ? "critical"
    : "prices";
  metals.activeId = ATLAS_METALS_ASSETS.some(
    asset => asset.id === String(saved.activeId || "")
  )
    ? String(saved.activeId)
    : "gold";
  metals.marketFilter = [
    "all",
    "monetary",
    "precious-industrial",
    "industrial"
  ].includes(String(saved.marketFilter || ""))
    ? String(saved.marketFilter)
    : "all";
  metals.selectionIds = atlasParallelMarketValidMetalIds(
    saved.selectionIds
  );
  if (!visibilityMigrated) atlasParallelMarketMetalsWrite();
  return metals;
}

function atlasParallelMarketMetalsWrite() {
  const metals = atlasParallelMarketMetalsState();
  const payload = {
    schema: "agent_crypto_parallel_market_metals_state_v1",
    savedAt: new Date().toISOString(),
    period: Number(metals.period || 7),
    resultVisibilityVersion: "28.2.61",
    view: metals.view === "base100" ? "base100" : "price",
    scale: metals.scale === "logarithmic"
      ? "logarithmic"
      : "linear",
    section: metals.section === "critical"
      ? "critical"
      : "prices",
    activeId: ATLAS_METALS_ASSETS.some(
      asset => asset.id === String(metals.activeId || "")
    )
      ? String(metals.activeId)
      : "gold",
    marketFilter: [
      "all",
      "monetary",
      "precious-industrial",
      "industrial"
    ].includes(String(metals.marketFilter || ""))
      ? String(metals.marketFilter)
      : "all",
    selectionIds: [...metals.selectionIds]
  };

  try {
    localStorage.setItem(
      ATLAS_PARALLEL_MARKET_METALS_STATE_KEY,
      JSON.stringify(payload)
    );
    return true;
  } catch {
    return false;
  }
}

function atlasParallelMarketSelectedMetals() {
  const selected = new Set(
    atlasParallelMarketMetalsState().selectionIds
  );
  return ATLAS_METALS_ASSETS.filter(asset => selected.has(asset.id));
}

function atlasParallelMarketSetControlsDisabled(disabled) {
  document
    .querySelectorAll(
      "#analyste .chart-v2-toolbar button, "
      + "#analyste .compare-actions button"
    )
    .forEach(button => {
      if (disabled) {
        if (!button.hasAttribute("data-parallel-market-disabled")) {
          button.dataset.parallelMarketDisabled =
            button.disabled ? "1" : "0";
        }
        button.disabled = true;
        button.setAttribute("aria-disabled", "true");
      } else if (button.hasAttribute("data-parallel-market-disabled")) {
        button.disabled =
          button.dataset.parallelMarketDisabled === "1";
        button.removeAttribute("data-parallel-market-disabled");
        if (!button.disabled) button.removeAttribute("aria-disabled");
      }
    });
}

function atlasParallelMarketActiveMetal() {
  const metals = atlasParallelMarketMetalsState();
  return ATLAS_METALS_ASSETS.find(
    asset => asset.id === String(metals.activeId || "")
  ) || ATLAS_METALS_ASSETS[0];
}

function atlasParallelMarketMetalsAllIds() {
  return ATLAS_METALS_ASSETS.map(asset => asset.id);
}

function atlasParallelMarketMetalsAllActive() {
  const metals = atlasParallelMarketMetalsState();
  const selected = new Set(metals.selectionIds);
  return metals.view === "base100"
    && ATLAS_METALS_ASSETS.every(asset => selected.has(asset.id));
}

function atlasParallelMarketSetActiveMetal(metalId) {
  const id = String(metalId || "");
  if (!ATLAS_METALS_ASSETS.some(asset => asset.id === id)) {
    return false;
  }
  const metals = atlasParallelMarketMetalsState();
  metals.activeId = id;
  // A single metal is always read on its real price scale.
  metals.view = "price";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketShowAllMetals() {
  const metals = atlasParallelMarketMetalsState();
  metals.selectionIds = atlasParallelMarketMetalsAllIds();
  metals.view = "base100";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketHiddenState(element, hidden, key) {
  if (!element) return;
  const attribute = `data-parallel-market-${key}-hidden-state`;

  if (hidden) {
    if (!element.hasAttribute(attribute)) {
      element.setAttribute(attribute, element.hidden ? "1" : "0");
    }
    element.hidden = true;
    return;
  }

  if (element.hasAttribute(attribute)) {
    element.hidden = element.getAttribute(attribute) === "1";
    element.removeAttribute(attribute);
  }
}

function atlasParallelMarketSetMetalsMarketFilter(filter) {
  const value = [
    "all",
    "monetary",
    "precious-industrial",
    "industrial"
  ].includes(String(filter || ""))
    ? String(filter)
    : "all";

  atlasParallelMarketMetalsState().marketFilter = value;
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetalsMarket();
  atlasWorkspaceScheduleSave?.(120);
  return value;
}



function atlasMetalsStructuralArray(value) {
  return Array.isArray(value) ? value : [];
}

function atlasMetalsStructuralRegistry() {
  return (
    atlasMetalsStructuralState.registry
    || ATLAS_METALS_STRUCTURAL_FALLBACK
  );
}

function atlasMetalsStructuralAsset(assetId = null) {
  const id = String(
    assetId
    || atlasParallelMarketActiveMetal()?.id
    || "gold"
  );

  return atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.assets
  ).find(asset => asset?.id === id)
    || atlasMetalsStructuralArray(
      ATLAS_METALS_STRUCTURAL_FALLBACK?.assets
    ).find(asset => asset?.id === id)
    || ATLAS_METALS_STRUCTURAL_FALLBACK.assets[0];
}

function atlasMetalsStructuralSource(sourceId) {
  const id = String(sourceId || "");

  return atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.sources
  ).find(source => source?.id === id)
    || atlasMetalsStructuralArray(
      ATLAS_METALS_STRUCTURAL_FALLBACK?.sources
    ).find(source => source?.id === id)
    || null;
}

function atlasMetalsStructuralSourceRow(source, note = "") {
  const row = document.createElement("span");
  const name = document.createElement("b");
  const description = document.createElement("small");
  const status = document.createElement("em");

  name.textContent = String(
    source?.short_name || source?.name || "Source"
  );
  description.textContent = String(
    note
    || source?.title
    || source?.role
    || "Source publique"
  );
  status.textContent = String(
    source?.status_label || "RÉFÉRENCE"
  );
  status.classList.add(
    atlasMarketRegistrySourceToneClass(
      source?.status_tone || "reference"
    )
  );

  row.dataset.marketSourceId = String(source?.id || "");
  row.dataset.structuralSource = "true";
  row.append(name, description, status);
  return row;
}

function atlasMetalsStructuralValidate(payload) {
  if (
    payload?.schema
    !== "agent_crypto_metals_structural_registry_v1"
  ) {
    throw new Error("Registre structurel incompatible");
  }

  const assets = atlasMetalsStructuralArray(payload?.assets);
  const sources = atlasMetalsStructuralArray(payload?.sources);
  const required = new Set([
    "gold",
    "silver",
    "platinum",
    "palladium",
    "copper"
  ]);

  if (
    assets.length !== required.size
    || assets.some(asset => !required.has(asset?.id))
  ) {
    throw new Error("Registre structurel incomplet");
  }

  if (sources.length < 4) {
    throw new Error("Sources structurelles incomplètes");
  }

  assets.forEach(asset => {
    if (
      !asset?.production?.display
      || !asset?.reserves?.display
      || !asset?.production?.top_display
      || !asset?.uses?.display
      || !asset?.eu_status?.display
      || !Array.isArray(asset?.source_ids)
    ) {
      throw new Error(
        `Données structurelles invalides : ${asset?.id || "?"}`
      );
    }
  });

  return payload;
}

async function atlasMetalsStructuralLoad() {
  atlasMetalsStructuralState.status = "loading";
  atlasMetalsStructuralState.error = null;

  try {
    const payload = await atlasMarketRegistryFetchJson(
      ATLAS_METALS_STRUCTURAL_REGISTRY_PATH
    );

    atlasMetalsStructuralState.registry =
      atlasMetalsStructuralValidate(payload);
    atlasMetalsStructuralState.status = "loaded";
    atlasMetalsStructuralState.origin = "json_local";
    atlasMetalsStructuralState.loadedAt =
      new Date().toISOString();
  } catch (error) {
    atlasMetalsStructuralState.registry =
      ATLAS_METALS_STRUCTURAL_FALLBACK;
    atlasMetalsStructuralState.status = "fallback";
    atlasMetalsStructuralState.origin =
      "fallback_intégré";
    atlasMetalsStructuralState.loadedAt = null;
    atlasMetalsStructuralState.error = String(
      error?.message || error || "Erreur structure"
    );
  }

  atlasParallelMarketRenderMetals();
  return atlasMetalsStructuralState.status;
}

function atlasMetalsStructuralRenderSourceDock(assetId = null) {
  const asset = atlasMetalsStructuralAsset(assetId);
  const list = document.getElementById(
    "atlasMetalsSourceList"
  );
  const stateLabel = document.getElementById(
    "atlasMetalsSourceDockState"
  );

  if (!list || !asset) return;

  const sources = atlasMetalsStructuralArray(
    asset.source_ids
  )
    .map(atlasMetalsStructuralSource)
    .filter(Boolean);

  list.replaceChildren();

  sources.forEach(source => {
    let note = source.title;

    if (source.id === "usgs_mcs_2026") {
      note = "Production · réserves · usages";
    } else if (source.id === "rmis_eu_2023") {
      note = "Criticité et statut stratégique UE";
    } else if (source.id === "iea_critical_minerals_2026") {
      note = "Scénarios offre-demande du cuivre";
    } else if (source.id === "world_bank_pink_sheet_2026") {
      note = "Historique mensuel public · non importé";
    }

    list.append(
      atlasMetalsStructuralSourceRow(source, note)
    );
  });

  if (stateLabel) {
    stateLabel.textContent =
      `${sources.length} source`
      + `${sources.length > 1 ? "s" : ""}`
      + " publique"
      + `${sources.length > 1 ? "s" : ""}`;
  }

  const meta = atlasMarketRegistryAssetMeta(asset.id);
  setText(
    document.getElementById("atlasMetalsSourceDockTitle"),
    `${meta.name} · ${meta.symbol}`
  );
}

function atlasMetalsStructuralRenderCatalog() {
  const list = document.getElementById(
    "atlasMetalsRegistryList"
  );
  const summary = document.getElementById(
    "atlasMetalsRegistrySummary"
  );
  if (!list) return;

  const sources = atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.sources
  );

  list.replaceChildren();

  sources.forEach(source => {
    list.append(
      atlasMetalsStructuralSourceRow(
        source,
        source.title
      )
    );
  });

  if (summary) {
    const origin =
      atlasMetalsStructuralState.status === "loaded"
        ? "registre JSON local"
        : "fallback public intégré";

    summary.textContent =
      `${sources.length} sources publiques · `
      + "5 métaux · données 2025 · "
      + `${origin} · aucun prix`;
  }

  list.dataset.registryStatus =
    atlasMetalsStructuralState.status;
}

function atlasMetalsStructuralRenderMarketRows() {
  atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.assets
  ).forEach(record => {
    const row = document.querySelector(
      `[data-metals-market-row="${record.id}"]`
    );
    if (!row) return;

    const cells = row.querySelectorAll("td");
    if (cells.length < 8) return;

    cells[4].textContent = "—";
    cells[5].textContent = "—";
    cells[6].textContent = "USGS 2026";
    cells[7].textContent = "Structure disponible";
    row.dataset.structuralState = "available";
    row.dataset.structuralYear =
      String(record.data_year || 2025);
  });
}

