/* =========================================================
   Build 28.1.88R15 — Scanner Live Collector
   Collecte silencieuse et horodatée de quatre paniers :
   Target Top 5, Hausses 5, Baisses 5 et Volumes 5.
   - Le classement reste exclusivement CoinGecko Market Snapshot.
   - Le prix courant vient de Binance lorsqu'une cotation déjà sûre existe,
     sinon de la dernière valeur CoinGecko réellement chargée.
   - Le Bridge V1.7 peut compléter et persister localement les relevés.
   - Aucune action financière, aucun nouveau panneau, aucune écriture GitHub.
   ========================================================= */
const ATLAS_SCANNER_COLLECTOR_SCHEMA = "atlas_scanner_live_snapshot_v1";
const ATLAS_SCANNER_COLLECTOR_ARCHIVE_KEY = "agent_crypto_scanner_live_archive_v1";
const ATLAS_SCANNER_COLLECTOR_PENDING_KEY = "agent_crypto_scanner_live_pending_v1";
const ATLAS_SCANNER_COLLECTOR_INTERVAL_MS = 60_000;
const ATLAS_SCANNER_COLLECTOR_LOCAL_LIMIT = 240;
const ATLAS_SCANNER_COLLECTOR_PENDING_LIMIT = 60;
const ATLAS_SCANNER_COLLECTOR_BRIDGE_URL = `${ATLAS_LOCAL_BRIDGE_BASE}/scanner-snapshot`;
const ATLAS_SCANNER_COLLECTOR_LATEST_URL = `${ATLAS_LOCAL_BRIDGE_BASE}/scanner-latest`;
const atlasScannerCollectorRuntime = {
  timer: 0,
  flushTimer: 0,
  busy: false,
  latestBusy: false,
  latestBridgeSnapshot: null,
  latestBridgeReadAt: 0,
  lastFingerprint: "",
  lastSavedAt: 0,
  bridgeBackoffUntil: 0,
  bridgeFailures: 0
};

function atlasScannerCollectorRead(key) {
  try {
    const rows = JSON.parse(localStorage.getItem(key) || "[]");
    return Array.isArray(rows) ? rows : [];
  } catch {
    return [];
  }
}

function atlasScannerCollectorWrite(key, rows, limit) {
  const safe = (Array.isArray(rows) ? rows : []).slice(-Math.max(1, Number(limit) || 1));
  try { localStorage.setItem(key, JSON.stringify(safe)); } catch {}
  return safe;
}

function atlasScannerCollectorFinite(value, digits = null) {
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  if (digits === null) return number;
  const factor = 10 ** Math.max(0, Number(digits) || 0);
  return Math.round(number * factor) / factor;
}

function atlasScannerCollectorBasketCoins(kind) {
  if (kind === "top5") {
    return ["BTC", "ETH", "BNB", "XRP", "SOL"]
      .map(symbol => atlasStrictCoinBySymbol(symbol))
      .filter(Boolean)
      .slice(0, 5);
  }
  if (kind === "gainers" || kind === "losers" || kind === "volume") {
    return atlasScannerPool(kind, 1).slice(0, 5);
  }
  return [];
}

function atlasScannerCollectorAsset(coin, basket, scannerRank, now = Date.now()) {
  const quote = atlasCurrentQuoteForCoin(coin, now);
  const quotePrice = atlasScannerCollectorFinite(quote?.price, Number(quote?.price) < 1 ? 8 : 4);
  const marketPrice = atlasScannerCollectorFinite(coin?.priceEur ?? coin?.price, Number(coin?.priceEur ?? coin?.price) < 1 ? 8 : 4);
  const marketChange = atlasScannerCollectorFinite(coin?.change24h, 4);
  const quoteChange = atlasScannerCollectorFinite(quote?.change24h, 4);
  const safeSymbol = atlasScannerSafeExchangeSymbol(coin);
  const metric = basket === "volume"
    ? atlasScannerCollectorFinite(coin?.volume24h, 2)
    : marketChange;

  return {
    coin_id: coin?.id || null,
    symbol: String(coin?.symbol || "").toUpperCase() || null,
    name: coin?.name || null,
    market_rank: atlasScannerCollectorFinite(coin?.rank, 0),
    scanner_rank: scannerRank,
    classification_source: "CoinGecko Market Snapshot",
    classification_metric: basket === "volume" ? "volume_24h_eur" : "change_24h_pct",
    classification_value: metric,
    market_price_eur: marketPrice,
    market_change_24h_pct: marketChange,
    market_volume_24h_eur: atlasScannerCollectorFinite(coin?.volume24h, 2),
    observed_price_eur: quotePrice ?? marketPrice,
    observed_change_24h_pct: quoteChange ?? marketChange,
    observed_source: quote?.source || coin?.source || state.mainSource || "CoinGecko",
    observed_status: quote?.status || (marketPrice !== null ? "conserved" : "unavailable"),
    observed_at: quote?.timestamp ? new Date(quote.timestamp).toISOString() : atlasStrictTimestamp(state.timestamp),
    binance_symbol_candidate: safeSymbol || null,
    binance_candidate_allowed: !!safeSymbol
  };
}

function atlasScannerCollectorBuildBasket(kind, now = Date.now()) {
  const coins = atlasScannerCollectorBasketCoins(kind);
  const labels = {
    top5: "Target Top 5",
    gainers: "Hausses 5",
    losers: "Baisses 5",
    volume: "Volumes 5"
  };
  return {
    id: kind,
    label: labels[kind] || kind,
    ranking_source: kind === "top5" ? "Agent-Crypto canonical definition" : "CoinGecko Market Snapshot",
    ranking_metric: kind === "volume" ? "volume_24h_eur" : kind === "top5" ? "canonical_order" : "change_24h_pct",
    assets: coins.map((coin, index) => atlasScannerCollectorAsset(coin, kind, index + 1, now))
  };
}

function atlasScannerCollectorBuildSnapshot(reason = "timer") {
  if (!state.liveOk || !Array.isArray(state.coins) || state.coins.length < 5) return null;
  const collectedAt = new Date().toISOString();
  const minute = collectedAt.slice(0, 16);
  const collectorId = typeof getCollectorId === "function" ? getCollectorId() : "local-browser";
  const marketTimestamp = atlasStrictTimestamp(state.dataBroker?.market?.timestamp || state.timestamp);
  const baskets = {
    top5: atlasScannerCollectorBuildBasket("top5"),
    gainers: atlasScannerCollectorBuildBasket("gainers"),
    losers: atlasScannerCollectorBuildBasket("losers"),
    volume: atlasScannerCollectorBuildBasket("volume")
  };
  const signature = Object.values(baskets)
    .map(basket => basket.assets.map(asset => asset.coin_id).join(","))
    .join("|");
  const fingerprint = `${minute}|${marketTimestamp || "none"}|${signature}`;
  const snapshotId = `${String(collectorId || "local-browser").replace(/[^a-zA-Z0-9_-]/g, "-")}_${collectedAt.slice(0, 19).replace(/[:T]/g, "-")}`;

  return {
    schema: ATLAS_SCANNER_COLLECTOR_SCHEMA,
    snapshot_id: snapshotId,
    collector_id: collectorId || "local-browser",
    collector_type: "agent_crypto_browser",
    release: ATLAS_RELEASE,
    collected_at: collectedAt,
    reason: String(reason || "timer"),
    market: {
      source: state.dataBroker?.market?.source || "CoinGecko",
      mode: state.dataBroker?.market?.mode || state.sourceLock?.mode || null,
      status: state.dataBroker?.market?.status || (state.liveOk ? "ready" : "unavailable"),
      timestamp: marketTimestamp,
      snapshot_id: state.dataBroker?.market?.snapshotId || state.sourceLock?.snapshotId || null,
      assets_loaded: Number(state.coins.length || 0),
      target_assets: 250,
      quote_currency: "EUR"
    },
    exchange_feed: {
      source: state.dataBroker?.exchangeFeed?.source || "Binance WebSocket",
      status: state.dataBroker?.exchangeFeed?.status || null,
      last_message_at: atlasStrictTimestamp(state.dataBroker?.exchangeFeed?.lastMessageAt),
      direct_pairs: atlasScannerCollectorFinite(state.dataBroker?.exchangeFeed?.directCount, 0),
      derived_pairs: atlasScannerCollectorFinite(state.dataBroker?.exchangeFeed?.derivedCount, 0)
    },
    baskets,
    safety: {
      observation_only: true,
      no_exchange_action: true,
      no_wallet_action: true,
      no_github_write: true,
      ranking_never_decided_by_binance: true
    },
    fingerprint
  };
}

function atlasScannerCollectorStore(snapshot) {
  if (!snapshot) return false;
  const archive = atlasScannerCollectorRead(ATLAS_SCANNER_COLLECTOR_ARCHIVE_KEY);
  const last = archive[archive.length - 1];
  if (last?.fingerprint === snapshot.fingerprint) return false;
  archive.push(snapshot);
  atlasScannerCollectorWrite(ATLAS_SCANNER_COLLECTOR_ARCHIVE_KEY, archive, ATLAS_SCANNER_COLLECTOR_LOCAL_LIMIT);

  const pending = atlasScannerCollectorRead(ATLAS_SCANNER_COLLECTOR_PENDING_KEY);
  if (!pending.some(row => row?.snapshot_id === snapshot.snapshot_id)) pending.push(snapshot);
  atlasScannerCollectorWrite(ATLAS_SCANNER_COLLECTOR_PENDING_KEY, pending, ATLAS_SCANNER_COLLECTOR_PENDING_LIMIT);
  atlasScannerCollectorRuntime.lastFingerprint = snapshot.fingerprint;
  atlasScannerCollectorRuntime.lastSavedAt = Date.now();
  return true;
}

function atlasScannerCollectorLatest() {
  const archive = atlasScannerCollectorRead(ATLAS_SCANNER_COLLECTOR_ARCHIVE_KEY);
  return archive[archive.length - 1] || null;
}

function atlasScannerCollectorSnapshotIsUsable(snapshot) {
  return !!snapshot
    && snapshot.schema === ATLAS_SCANNER_COLLECTOR_SCHEMA
    && snapshot.baskets
    && typeof snapshot.baskets === "object";
}

function atlasScannerCollectorAcceptBridgeSnapshot(snapshot) {
  if (!atlasScannerCollectorSnapshotIsUsable(snapshot)) return false;
  atlasScannerCollectorRuntime.latestBridgeSnapshot = snapshot;
  atlasScannerCollectorRuntime.latestBridgeReadAt = Date.now();
  window.requestAnimationFrame(() => atlasPatchVisibleChartLiveEndpoints());
  return true;
}

function atlasScannerCollectorEffectiveLatest() {
  const bridge = atlasScannerCollectorRuntime.latestBridgeSnapshot;
  if (atlasScannerCollectorSnapshotIsUsable(bridge)) return bridge;
  return atlasScannerCollectorLatest();
}

function atlasScannerCollectorBasketKeyForPreset(preset) {
  const key = String(preset || "").toLowerCase();
  if (key === "gainers") return "gainers";
  if (key === "losers") return "losers";
  if (key === "volume") return "volume";
  if (key === "rank-5" || key === "top5") return "top5";
  return "";
}

function atlasScannerCollectorFindAsset(coin, preset = "") {
  const snapshot = atlasScannerCollectorEffectiveLatest();
  if (!atlasScannerCollectorSnapshotIsUsable(snapshot) || !coin) return null;
  const coinId = String(coin.id || "").toLowerCase();
  const symbol = String(coin.symbol || "").toUpperCase();
  const preferred = atlasScannerCollectorBasketKeyForPreset(preset);
  const keys = preferred
    ? [preferred, ...["top5", "gainers", "losers", "volume"].filter(key => key !== preferred)]
    : ["top5", "gainers", "losers", "volume"];

  for (const key of keys) {
    const assets = snapshot.baskets?.[key]?.assets;
    if (!Array.isArray(assets)) continue;
    const match = assets.find(asset =>
      (coinId && String(asset?.coin_id || "").toLowerCase() === coinId)
      || (symbol && String(asset?.symbol || "").toUpperCase() === symbol)
    );
    if (match) return { ...match, basket: key, snapshot };
  }
  return null;
}

function atlasScannerCollectorQuoteForCoin(coin, preset = "") {
  const asset = atlasScannerCollectorFindAsset(coin, preset);
  const price = Number(asset?.observed_price_eur);
  if (!Number.isFinite(price) || price <= 0) return null;
  const timestamp = Date.parse(asset?.observed_at || asset?.snapshot?.collected_at || "");
  return {
    price,
    change24h: Number.isFinite(Number(asset?.observed_change_24h_pct))
      ? Number(asset.observed_change_24h_pct)
      : null,
    source: String(asset?.observed_source || "CoinGecko collecté"),
    status: String(asset?.observed_status || "collected"),
    timestamp: Number.isFinite(timestamp) ? timestamp : Date.now(),
    kind: /binance/i.test(String(asset?.observed_source || ""))
      ? "scanner-binance-observed"
      : "scanner-coingecko-observed",
    basket: asset?.basket || null,
    scannerSnapshotId: asset?.snapshot?.snapshot_id || null
  };
}

function atlasObservationKind(quote = null) {
  const status = String(quote?.status || "").toLowerCase();
  const source = String(quote?.source || "").toLowerCase();
  const kind = String(quote?.kind || "").toLowerCase();

  if (status === "live" && source.includes("binance")) return "live-binance";
  if (
    status === "collected"
    || kind.includes("scanner-")
    || source.includes("collect")
  ) return "collected";
  if (status === "conserved") return "conserved";
  if (status === "snapshot") return "snapshot";
  if (["direct", "live"].includes(status)) return "direct";
  return "unavailable";
}

function atlasComparisonEndpointComposition(coins = [], chart = null) {
  const rows = (Array.isArray(coins) ? coins : [])
    .filter(Boolean)
    .map(coin => {
      const quote = atlasCurrentChartObservation(coin, chart);
      const timestamp = Number(quote?.timestamp);
      return {
        coin,
        quote,
        kind: atlasObservationKind(quote),
        timestamp: Number.isFinite(timestamp) && timestamp > 0 ? timestamp : null
      };
    });

  const count = kind => rows.filter(row => row.kind === kind).length;
  const timestamps = rows
    .map(row => row.timestamp)
    .filter(value => Number.isFinite(value) && value > 0);

  return {
    rows,
    total: rows.length,
    liveBinance: count("live-binance"),
    collected: count("collected"),
    conserved: count("conserved"),
    snapshot: count("snapshot"),
    direct: count("direct"),
    unavailable: count("unavailable"),
    latestTimestamp: timestamps.length ? Math.max(...timestamps) : null
  };
}

function atlasComparisonEndpointLabel(composition) {
  const parts = [];
  if (composition?.liveBinance) {
    parts.push(`${composition.liveBinance} live Binance`);
  }
  if (composition?.collected) {
    parts.push(`${composition.collected} collecté${composition.collected > 1 ? "s" : ""}`);
  }
  if (composition?.snapshot) {
    parts.push(`${composition.snapshot} snapshot${composition.snapshot > 1 ? "s" : ""}`);
  }
  if (composition?.conserved) {
    parts.push(`${composition.conserved} conservé${composition.conserved > 1 ? "s" : ""}`);
  }
  if (composition?.direct) {
    parts.push(`${composition.direct} direct${composition.direct > 1 ? "s" : ""}`);
  }
  if (composition?.unavailable) {
    parts.push(`${composition.unavailable} indisponible${composition.unavailable > 1 ? "s" : ""}`);
  }

  const timestamp = composition?.latestTimestamp
    ? atlasExactTimestampLabel(composition.latestTimestamp)
    : "heure inconnue";

  return parts.length
    ? `${parts.join(" · ")} · observation ${timestamp}`
    : "Aucune observation terminale disponible";
}

function atlasRefreshComparisonEndpointTruth(coins = null, chart = null) {
  const node = document.querySelector("[data-comparison-endpoint-truth]");
  if (!node) return false;

  const selectedCoins = Array.isArray(coins) && coins.length
    ? coins
    : atlasComparisonCoins();
  const composition = atlasComparisonEndpointComposition(
    selectedCoins,
    chart || state.chartEngineV2?.realChart || null
  );

  node.textContent = atlasComparisonEndpointLabel(composition);
  node.dataset.endpointState =
    composition.liveBinance
      ? "live"
      : composition.collected
        ? "collected"
        : composition.conserved || composition.snapshot
          ? "stored"
          : "unavailable";
  return true;
}

function atlasCurrentChartObservation(coin, chart = null) {
  const direct = atlasExchangeQuoteForCoin(coin?.id || "");
  const directPrice = Number(direct?.price);
  if (direct?.status === "live" && Number.isFinite(directPrice) && directPrice > 0) {
    return direct;
  }

  const preset = String(
    chart?.$atlasPreset || state.dataBroker?.comparison?.preset || "manual"
  );
  const collected = atlasScannerCollectorQuoteForCoin(coin, preset);
  if (collected) return collected;

  const current = atlasCurrentQuoteForCoin(coin, Date.now());
  const currentPrice = Number(current?.price);
  return Number.isFinite(currentPrice) && currentPrice > 0 ? current : null;
}

async function atlasScannerCollectorFetchLatest(options = {}) {
  if (atlasScannerCollectorRuntime.latestBusy) return false;
  atlasScannerCollectorRuntime.latestBusy = true;
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), 6000);
  try {
    const response = await fetch(ATLAS_SCANNER_COLLECTOR_LATEST_URL, {
      method: "GET",
      cache: "no-store",
      signal: controller.signal
    });
    if (!response.ok) return false;
    const payload = await response.json();
    return atlasScannerCollectorAcceptBridgeSnapshot(payload?.snapshot || null);
  } catch (error) {
    if (options.silent !== true) {
      console.debug("Scanner Live Readback différé", String(error?.message || error || ""));
    }
    return false;
  } finally {
    window.clearTimeout(timer);
    atlasScannerCollectorRuntime.latestBusy = false;
  }
}

async function atlasScannerCollectorPost(snapshot) {
  const controller = new AbortController();
  const timer = window.setTimeout(() => controller.abort(), 14_000);
  try {
    const response = await fetch(ATLAS_SCANNER_COLLECTOR_BRIDGE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(snapshot),
      cache: "no-store",
      signal: controller.signal
    });
    if (!response.ok) throw new Error(`Bridge collector HTTP ${response.status}`);
    const payload = await response.json();
    if (!payload?.ok) throw new Error(payload?.error || "Bridge collector a refusé le snapshot");
    atlasScannerCollectorAcceptBridgeSnapshot(payload?.snapshot || null);
    return payload;
  } finally {
    window.clearTimeout(timer);
  }
}

async function atlasScannerCollectorFlush() {
  if (atlasScannerCollectorRuntime.busy) return false;
  if (Date.now() < Number(atlasScannerCollectorRuntime.bridgeBackoffUntil || 0)) return false;
  const pending = atlasScannerCollectorRead(ATLAS_SCANNER_COLLECTOR_PENDING_KEY);
  if (!pending.length) return true;

  atlasScannerCollectorRuntime.busy = true;
  try {
    const batch = pending.slice(0, 6);
    const sent = new Set();
    for (const snapshot of batch) {
      await atlasScannerCollectorPost(snapshot);
      sent.add(snapshot.snapshot_id);
    }
    const remaining = pending.filter(row => !sent.has(row?.snapshot_id));
    atlasScannerCollectorWrite(ATLAS_SCANNER_COLLECTOR_PENDING_KEY, remaining, ATLAS_SCANNER_COLLECTOR_PENDING_LIMIT);
    atlasScannerCollectorRuntime.bridgeFailures = 0;
    atlasScannerCollectorRuntime.bridgeBackoffUntil = 0;
    return true;
  } catch (error) {
    atlasScannerCollectorRuntime.bridgeFailures += 1;
    const delay = Math.min(10 * 60_000, 60_000 * atlasScannerCollectorRuntime.bridgeFailures);
    atlasScannerCollectorRuntime.bridgeBackoffUntil = Date.now() + delay;
    console.debug("Scanner Live Collector : Bridge différé", String(error?.message || error || ""));
    return false;
  } finally {
    atlasScannerCollectorRuntime.busy = false;
  }
}

function atlasScannerCollectorCapture(reason = "timer", options = {}) {
  const snapshot = atlasScannerCollectorBuildSnapshot(reason);
  if (!snapshot) return false;
  const stored = atlasScannerCollectorStore(snapshot);
  if (!atlasScannerCollectorRuntime.latestBridgeSnapshot) {
    window.requestAnimationFrame(() => atlasPatchVisibleChartLiveEndpoints());
  }
  if (stored || options.forceFlush) void atlasScannerCollectorFlush();
  return stored;
}

function atlasScannerCollectorSchedule(reason = "market") {
  window.clearTimeout(atlasScannerCollectorRuntime.flushTimer);
  atlasScannerCollectorRuntime.flushTimer = window.setTimeout(() => {
    atlasScannerCollectorRuntime.flushTimer = 0;
    atlasScannerCollectorCapture(reason);
  }, 1200);
}

function atlasScannerCollectorInit() {
  if (!atlasScannerCollectorRuntime.timer) {
    atlasScannerCollectorRuntime.timer = window.setInterval(() => {
      if (document.visibilityState === "visible") atlasScannerCollectorCapture("minute-pulse");
      else void atlasScannerCollectorFlush();
    }, ATLAS_SCANNER_COLLECTOR_INTERVAL_MS);
  }
  window.addEventListener("online", () => {
    void atlasScannerCollectorFlush();
    void atlasScannerCollectorFetchLatest({ silent: true });
  });
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") {
      atlasScannerCollectorCapture("visibility-resume", { forceFlush: true });
      void atlasScannerCollectorFetchLatest({ silent: true });
    }
  });
  window.setTimeout(() => void atlasScannerCollectorFetchLatest({ silent: true }), 1800);
  window.setTimeout(() => atlasScannerCollectorCapture("startup", { forceFlush: true }), 5000);
}

/* Hook non destructif : tout snapshot Market validé programme une collecte. */
const atlasBrokerCommitMarketR12 = atlasBrokerCommitMarket;
atlasBrokerCommitMarket = function atlasBrokerCommitMarketR13(snapshot, mode) {
  const result = atlasBrokerCommitMarketR12(snapshot, mode);
  atlasScannerCollectorSchedule(`market-${String(mode || "unknown")}`);
  return result;
};

/* Prépare déjà la donnée pour la future fiabilisation Atlas, sans changer ses rapports R12. */
const atlasBuildStrictFactContractR12 = atlasBuildStrictFactContract;
atlasBuildStrictFactContract = function atlasBuildStrictFactContractR13(period, chart, chartResult, comparisonIds, chartTruth) {
  const contract = atlasBuildStrictFactContractR12(period, chart, chartResult, comparisonIds, chartTruth);
  const latest = atlasScannerCollectorEffectiveLatest();
  contract.scanner_collector = latest ? {
    status: "available",
    schema: latest.schema,
    collected_at: latest.collected_at,
    market_timestamp: latest.market?.timestamp || null,
    market_mode: latest.market?.mode || null,
    baskets: latest.baskets || null,
    note: "Classements CoinGecko ; cotations observées Binance lorsqu'elles sont sûres, sinon CoinGecko."
  } : {
    status: "empty",
    note: "La collecte commence automatiquement dès qu'un Market Snapshot est disponible."
  };
  return contract;
};

atlasScannerCollectorInit();



/* =========================================================
   Build 28.2.0 — Deterministic Market Frame · Price Truth · Scanner Coherence
   Empreinte analytique SHA-256, Source Truth V2, Evidence Layer,
   Quality Gates Math Core et conservation transactionnelle.
   L'identité visuelle, le Graphique, Target, Market Flow, Forge,
   Bridge V1.7.6 et Control Center V2.1.0 restent inchangés.
   ========================================================= */
const ATLAS_ANALYTICAL_STATE_SCHEMA = "agent_crypto_analytical_state_v2";
const ATLAS_ANALYTICAL_FINGERPRINT_VERSION = "sha256-canonical-v2";
const ATLAS_SOURCE_TRUTH_SCHEMA = "agent_crypto_source_truth_v2";
const ATLAS_EVIDENCE_SCHEMA = "agent_crypto_evidence_layer_v2";
const ATLAS_MATH_GATES_SCHEMA = "agent_crypto_math_quality_gates_v2";
const ATLAS_CONTRADICTION_SCHEMA = "agent_crypto_contradictions_v2";
const ATLAS_SOURCE_TRUTH_MODES = Object.freeze({
  DIRECT: "DIRECT",
  DIRECT_CONSERVED: "DIRECT_CONSERVÉ",
  DERIVED_DIRECT: "DÉRIVÉ_DIRECT",
  CACHE_RECENT: "CACHE_RÉCENT",
  CACHE_DATED: "CACHE_DATÉ",
  ARCHIVE: "ARCHIVE",
  COMPOSITE: "COMPOSITE",
  BACKEND_REQUIRED: "BACKEND_REQUIS",
  UNAVAILABLE: "INDISPONIBLE"
});
const atlasAnalyticalTruthState = {
  currentEnvelope: null,
  currentFingerprint: "",
  analysisFingerprint: "",
  lastRenderedFingerprint: "",
  initialized: false,
  timer: 0
};

function atlasCanonicalNormalize(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.map(atlasCanonicalNormalize);
  if (typeof value === "object") {
    const output = {};
    Object.keys(value).sort().forEach(key => {
      if (value[key] !== undefined && typeof value[key] !== "function") {
        output[key] = atlasCanonicalNormalize(value[key]);
      }
    });
    return output;
  }
  return String(value);
}

function atlasCanonicalStringify(value) {
  return JSON.stringify(atlasCanonicalNormalize(value));
}

/* SHA-256 synchrone UTF-8 : l'empreinte doit rester disponible dans
   les chemins synchrones historiques de génération des rapports. */
function atlasSha256(value) {
  const ascii = unescape(encodeURIComponent(String(value ?? "")));
  const rightRotate = (v, amount) => (v >>> amount) | (v << (32 - amount));
  const mathPow = Math.pow;
  const maxWord = mathPow(2, 32);
  const lengthProperty = "length";
  let i, j;
  let result = "";
  const words = [];
  const asciiBitLength = ascii[lengthProperty] * 8;
  atlasSha256.h = atlasSha256.h || [];
  atlasSha256.k = atlasSha256.k || [];
  const initialHash = atlasSha256.h;
  const k = atlasSha256.k;
  let primeCounter = k[lengthProperty];
  const isComposite = {};
  for (let candidate = 2; primeCounter < 64; candidate += 1) {
    if (!isComposite[candidate]) {
      for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
      initialHash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
      k[primeCounter] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
      primeCounter += 1;
    }
  }
  const hash = initialHash.slice(0);
  let working = ascii + "\x80";
  while ((working[lengthProperty] % 64) !== 56) working += "\x00";
  for (i = 0; i < working[lengthProperty]; i += 1) {
    j = working.charCodeAt(i);
    if (j >> 8) throw new Error("SHA-256 UTF-8 invalide");
    words[i >> 2] |= j << (((3 - i) % 4) * 8);
  }
  words[words[lengthProperty]] = ((asciiBitLength / maxWord) | 0);
  words[words[lengthProperty]] = asciiBitLength;
  for (j = 0; j < words[lengthProperty];) {
    const w = words.slice(j, j += 16);
    const oldHash = hash.slice(0);
    let a = hash[0];
    let b = hash[1];
    let c = hash[2];
    let d = hash[3];
    let e = hash[4];
    let f = hash[5];
    let g = hash[6];
    let h = hash[7];
    for (i = 0; i < 64; i += 1) {
      const w15 = w[i - 15];
      const w2 = w[i - 2];
      const word = w[i] = i < 16 ? w[i] : (
        w[i - 16]
        + (rightRotate(w15, 7) ^ rightRotate(w15, 18) ^ (w15 >>> 3))
        + w[i - 7]
        + (rightRotate(w2, 17) ^ rightRotate(w2, 19) ^ (w2 >>> 10))
      ) | 0;
      const sigma1 = rightRotate(e, 6) ^ rightRotate(e, 11) ^ rightRotate(e, 25);
      const choice = (e & f) ^ ((~e) & g);
      const temp1 = (h + sigma1 + choice + k[i] + word) | 0;
      const sigma0 = rightRotate(a, 2) ^ rightRotate(a, 13) ^ rightRotate(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (sigma0 + majority) | 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) | 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) | 0;
    }
    hash[0] = (oldHash[0] + a) | 0;
    hash[1] = (oldHash[1] + b) | 0;
    hash[2] = (oldHash[2] + c) | 0;
    hash[3] = (oldHash[3] + d) | 0;
    hash[4] = (oldHash[4] + e) | 0;
    hash[5] = (oldHash[5] + f) | 0;
    hash[6] = (oldHash[6] + g) | 0;
    hash[7] = (oldHash[7] + h) | 0;
  }
  for (i = 0; i < 8; i += 1) {
    for (j = 3; j + 1; j -= 1) {
      const byte = (hash[i] >> (j * 8)) & 255;
      result += (byte < 16 ? "0" : "") + byte.toString(16);
    }
  }
  return result;
}

function atlasSourceTruthMode(rawMode, source = "", status = "") {
  const text = `${rawMode || ""} ${source || ""} ${status || ""}`.toLocaleLowerCase("fr-FR");
  if (/backend|required auth|authentification|jwt|coinbase advanced/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.BACKEND_REQUIRED;
  if (/unavailable|indisponible|blocked|bloqué|error|échec|none|empty/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE;
  if (/direct[-_ ]?conserved|direct conservé|dernière lecture directe/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.DIRECT_CONSERVED;
  if (/derived|dérivé|conversion/.test(text) && /direct|binance/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.DERIVED_DIRECT;
  if (/comparison|base100|composite|mixed|mixte/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.COMPOSITE;
  if (/archive|github/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.ARCHIVE;
  if (/stale|daté|dated|ancien/.test(text) && /cache/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.CACHE_DATED;
  if (/cache|browser-cache|local/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.CACHE_RECENT;
  if (/direct|websocket|klines|ready|live/.test(text)) return ATLAS_SOURCE_TRUTH_MODES.DIRECT;
  return ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE;
}

function atlasSourceTruthDescriptor({ id, provider, rawMode, status, timestamp, role, instrument = null, transformation = null, limitations = [] }) {
  const observedAt = atlasStrictTimestamp(timestamp);
  const ageMs = observedAt ? Math.max(0, Date.now() - Date.parse(observedAt)) : null;
  const mode = atlasSourceTruthMode(rawMode, provider, status);
  let freshness = "UNKNOWN";
  if (Number.isFinite(ageMs)) {
    if (ageMs <= 120000) freshness = "FRESH";
    else if (ageMs <= 3600000) freshness = "RECENT";
    else freshness = "DATED";
  }
  return {
    id: String(id || provider || "source").toLowerCase().replace(/[^a-z0-9_-]+/g, "-").replace(/^-|-$/g, ""),
    provider: provider || "Source inconnue",
    role: role || null,
    instrument,
    mode,
    raw_mode: rawMode || null,
    status: status || null,
    observed_at: observedAt,
    age_ms: Number.isFinite(ageMs) ? ageMs : null,
    freshness,
    transformation,
    limitations: Array.isArray(limitations) ? limitations : []
  };
}

function atlasSourceTruthBuild(contract) {
  const descriptors = [];
  const market = contract?.market || {};
  const cg = contract?.sources?.coingecko || {};
  const bn = contract?.sources?.binance || {};
  descriptors.push(atlasSourceTruthDescriptor({
    id: "market-coingecko",
    provider: market.source || "CoinGecko",
    rawMode: market.mode || cg.mode,
    status: market.status || cg.status,
    timestamp: market.timestamp || cg.timestamp,
    role: "Marché global, classement et largeur",
    instrument: `Univers ${market.assets_loaded || 0}/${market.target_assets || 250}`,
    limitations: Number(market.assets_loaded || 0) < Number(market.target_assets || 250) ? ["Couverture partielle"] : []
  }));
  descriptors.push(atlasSourceTruthDescriptor({
    id: "target-binance",
    provider: bn.source || "Binance WebSocket",
    rawMode: bn.feed_status === "ready" ? "direct-live" : bn.feed_status,
    status: bn.feed_status,
    timestamp: bn.last_message_at,
    role: "Cotations du Target Top 5",
    instrument: `${bn.direct_pairs || 0} directes · ${bn.derived_pairs || 0} dérivées`
  }));
  const graph = contract?.graph || {};
  const graphRows = Array.isArray(graph.series) ? graph.series : [];
  graphRows.forEach((row, index) => descriptors.push(atlasSourceTruthDescriptor({
    id: `graph-${row?.symbol || index}`,
    provider: graph.provider || row?.source || "Historique graphique",
    rawMode: row?.source_mode || graph.truth_source,
    status: graph.status,
    timestamp: row?.last_time || graph.timestamp,
    role: "Série du Graphique Analyste",
    instrument: row?.symbol || null,
    limitations: Number(row?.points || 0) < 2 ? ["Série insuffisante"] : []
  })));
  const news = contract?.news || {};
  descriptors.push(atlasSourceTruthDescriptor({
    id: "news-sentinel",
    provider: news?.lead_event?.source_name || "News Sentinel",
    rawMode: news.status === "ready" ? "archive-composite" : news.status,
    status: news.status,
    timestamp: news.archive_time || news?.lead_event?.event_time,
    role: "Veille d'événements et preuves",
    limitations: news?.lead_event ? [] : ["Aucun événement directeur"]
  }));
  descriptors.push(atlasSourceTruthDescriptor({
    id: "coinbase-advanced-trade",
    provider: "Coinbase Advanced Trade",
    rawMode: "backend-required-authentication",
    status: "backend requis",
    timestamp: null,
    role: "Intégration exchange future",
    limitations: ["JWT et backend requis", "Ne compte pas comme échec GitHub Pages"]
  }));
  const counts = {};
  Object.values(ATLAS_SOURCE_TRUTH_MODES).forEach(mode => { counts[mode] = 0; });
  descriptors.forEach(row => { counts[row.mode] = Number(counts[row.mode] || 0) + 1; });
  return {
    schema: ATLAS_SOURCE_TRUTH_SCHEMA,
    descriptors,
    counts,
    public_source_failures: descriptors.filter(row => row.mode === ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE && row.id !== "coinbase-advanced-trade").length,
    rule: "Une archive n'est jamais présentée comme directe ; BACKEND_REQUIS ne compte pas comme échec public."
  };
}

function atlasEvidenceNormalizeLevel(value, fallback = "INCONNU") {
  const text = String(value || "").toLocaleLowerCase("fr-FR");
  if (/primaire|primary/.test(text)) return "PRIMAIRE";
  if (/fort|strong|high|confirm/.test(text)) return "FORTE";
  if (/moyen|medium|moderate|corrobor/.test(text)) return "MOYENNE";
  if (/faible|weak|low|rumor|rumeur/.test(text)) return "FAIBLE";
  return fallback;
}

function atlasEvidenceLayerBuild(contract) {
  const lead = contract?.news?.lead_event || null;
  if (!lead) {
    return {
      schema: ATLAS_EVIDENCE_SCHEMA,
      events: [],
      counts: { CONFIRMÉE: 0, CORROBORÉE: 0, SIGNALÉE: 0, À_VÉRIFIER: 0 },
      rule: "Impact potentiel et certitude restent séparés."
    };
  }
  const reportedSources = Math.max(0, Number(lead.source_count || 0));
  const independent = Number.isFinite(Number(lead.independent_source_count))
    ? Math.max(0, Number(lead.independent_source_count))
    : (reportedSources > 0 ? 1 : 0);
  const proof = atlasEvidenceNormalizeLevel(lead.evidence, "FAIBLE");
  const impact = atlasEvidenceNormalizeLevel(lead.impact, "INCONNU");
  let confidence = "À_VÉRIFIER";
  if ((proof === "PRIMAIRE" || proof === "FORTE") && independent >= 2) confidence = "CONFIRMÉE";
  else if ((proof === "FORTE" || proof === "MOYENNE") && independent >= 2) confidence = "CORROBORÉE";
  else if (proof !== "FAIBLE" || reportedSources > 0) confidence = "SIGNALÉE";
  const event = {
    id: atlasSha256(atlasCanonicalStringify({ headline: lead.headline || "", event_time: lead.event_time || "", source: lead.source_name || "" })).slice(0, 20),
    headline: lead.headline || "Événement non nommé",
    event_time: atlasStrictTimestamp(lead.event_time),
    source_name: lead.source_name || null,
    impact_potential: impact,
    confidence,
    proof_quality: proof,
    reported_sources: reportedSources,
    independent_sources: independent,
    assets: Array.isArray(lead.assets) ? lead.assets : [],
    sectors: Array.isArray(lead.sectors) ? lead.sectors : [],
    action: "OBSERVATION_UNIQUEMENT",
    limitation: independent < reportedSources ? "Les reprises ne prouvent pas une indépendance éditoriale." : null
  };
  const counts = { CONFIRMÉE: 0, CORROBORÉE: 0, SIGNALÉE: 0, À_VÉRIFIER: 0 };
  counts[confidence] = 1;
  return {
    schema: ATLAS_EVIDENCE_SCHEMA,
    events: [event],
    counts,
    rule: "Deux liens ou deux domaines ne prouvent pas deux sources indépendantes."
  };
}

function atlasMathGate(metric, value, observations, required, recommended, completeness, options = {}) {
  const numeric = value === null || value === undefined || value === "" ? null : Number(value);
  const count = Number(observations || 0);
  const complete = Number(completeness || 0);
  let status = "NOT_APPLICABLE";
  let reason = "Mesure absente du contexte courant";
  if (Number.isFinite(numeric)) {
    if (count < required) {
      status = "BLOCKED";
      reason = `${count} observations · minimum ${required}`;
    } else if (complete > 0 && complete < 70) {
      status = "BLOCKED";
      reason = `Complétude ${complete.toFixed(1)} % · minimum 70 %`;
    } else if (count < recommended || (complete > 0 && complete < 85)) {
      status = "DEGRADED";
      reason = `${count} observations · recommandation ${recommended}${complete > 0 ? ` · complétude ${complete.toFixed(1)} %` : ""}`;
    } else {
      status = "PUBLISHED";
      reason = `${count} observations · gate satisfait`;
    }
  }
  return {
    metric,
    value: status === "BLOCKED" ? null : (Number.isFinite(numeric) ? numeric : null),
    raw_value: Number.isFinite(numeric) ? numeric : null,
    unit: options.unit || "%",
    status,
    observations: count,
    required_observations: required,
    recommended_observations: recommended,
    reason,
    method_version: "quality-gates-v2"
  };
}

function atlasMathQualityGatesBuild(mathContract) {
  const windowData = mathContract?.active_window || {};
  const risk = mathContract?.historical_risk || {};
  const returns = Number(windowData.returns_count || Math.max(0, Number(windowData.observations || 0) - 1));
  const completeness = Number(windowData.completeness_pct || 0);
  const benchmark = Number(risk.benchmark_observations || 0);
  const gates = [
    atlasMathGate("realized_volatility_window_pct", risk.realized_volatility_window_pct, returns, 20, 30, completeness),
    atlasMathGate("realized_volatility_annualized_pct", risk.realized_volatility_annualized_pct, returns, 20, 30, completeness),
    atlasMathGate("ewma_volatility_annualized_pct", risk.ewma_volatility_annualized_pct, returns, 30, 60, completeness),
    atlasMathGate("downside_deviation_annualized_pct", risk.downside_deviation_annualized_pct, returns, 30, 60, completeness),
    atlasMathGate("max_drawdown_pct", risk.max_drawdown_pct, returns, 20, 30, completeness),
    atlasMathGate("var_historical_95_step_pct", risk.var_historical_95_step_pct, returns, 100, 200, completeness),
    atlasMathGate("expected_shortfall_historical_95_step_pct", risk.expected_shortfall_historical_95_step_pct, returns, 200, 300, completeness),
    atlasMathGate("correlation_btc", risk.correlation_btc, benchmark, 60, 120, completeness, { unit: "coefficient" }),
    atlasMathGate("beta_btc", risk.beta_btc, benchmark, 60, 120, completeness, { unit: "coefficient" }),
    atlasMathGate("bootstrap_volatility_window_ci95_pct", Array.isArray(risk.bootstrap_volatility_window_ci95_pct) && risk.bootstrap_volatility_window_ci95_pct.every(Number.isFinite) ? 1 : null, returns, 60, 120, completeness, { unit: "intervalle" })
  ];
  const counts = { PUBLISHED: 0, DEGRADED: 0, BLOCKED: 0, NOT_APPLICABLE: 0 };
  gates.forEach(gate => { counts[gate.status] = Number(counts[gate.status] || 0) + 1; });
  return {
    schema: ATLAS_MATH_GATES_SCHEMA,
    granularity: windowData.granularity || null,
    observations: Number(windowData.observations || 0),
    returns_count: returns,
    completeness_pct: Number.isFinite(completeness) ? completeness : null,
    gates,
    counts,
    rule: "Une formule disponible ne signifie pas qu'une mesure est publiable."
  };
}

function atlasMathApplyQualityGates(mathContract, quality) {
  const clone = atlasSharedSynthesisClone(mathContract || {});
  clone.quality_gates = quality;
  clone.blocked_measures = quality.gates.filter(gate => gate.status === "BLOCKED").map(gate => ({ metric: gate.metric, reason: gate.reason }));
  const risk = clone.historical_risk || {};
  quality.gates.forEach(gate => {
    if (gate.status !== "BLOCKED") return;
    if (gate.metric === "bootstrap_volatility_window_ci95_pct") risk.bootstrap_volatility_window_ci95_pct = [null, null];
    else if (Object.prototype.hasOwnProperty.call(risk, gate.metric)) risk[gate.metric] = null;
  });
  clone.historical_risk = risk;
  return clone;
}

function atlasContradictionsV2Build(contract, sourceTruth, mathQuality, evidence) {
  const rows = [];
  const severityMap = { "confirmé": "MEDIUM", "à vérifier": "LOW", "stop": "STOP" };
  (Array.isArray(contract?.contradictions) ? contract.contradictions : []).forEach(item => rows.push({
    id: item.code || atlasSha256(item.text || "contradiction").slice(0, 16),
    severity: severityMap[String(item.level || "").toLocaleLowerCase("fr-FR")] || "INFO",
    status: String(item.level || "").toLocaleLowerCase("fr-FR").includes("vérifier") ? "TO_VERIFY" : "CONFIRMED",
    statement: item.text || item.code || "Contradiction non détaillée",
    affects: [],
    stop_gate: String(item.level || "").toLocaleLowerCase("fr-FR") === "stop"
  }));
  const blocked = Number(mathQuality?.counts?.BLOCKED || 0);
  if (blocked > 0) rows.push({
    id: "math-measures-blocked",
    severity: blocked >= 4 ? "HIGH" : "MEDIUM",
    status: "CONFIRMED",
    statement: `${blocked} mesure${blocked > 1 ? "s" : ""} Math Core bloquée${blocked > 1 ? "s" : ""} par les Quality Gates.`,
    affects: ["math_core", "atlas", "aerith"],
    stop_gate: false
  });
  const unavailable = Number(sourceTruth?.counts?.[ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE] || 0);
  if (unavailable > 0) rows.push({
    id: "sources-unavailable",
    severity: "MEDIUM",
    status: "CONFIRMED",
    statement: `${unavailable} source${unavailable > 1 ? "s" : ""} indisponible${unavailable > 1 ? "s" : ""}.`,
    affects: ["source_truth"],
    stop_gate: false
  });
  const event = evidence?.events?.[0];
  if (event && event.reported_sources > event.independent_sources) rows.push({
    id: "news-syndication-not-independence",
    severity: "LOW",
    status: "ACCEPTED_LIMIT",
    statement: `${event.reported_sources} reprises News, mais ${event.independent_sources} source indépendante démontrée.`,
    affects: ["news_sentinel", "atlas", "aerith"],
    stop_gate: false
  });
  return {
    schema: ATLAS_CONTRADICTION_SCHEMA,
    items: rows,
    counts: {
      total: rows.length,
      stop: rows.filter(row => row.stop_gate).length,
      high: rows.filter(row => row.severity === "HIGH").length,
      to_verify: rows.filter(row => row.status === "TO_VERIFY").length
    }
  };
}

function atlasAnalyticalTargetMode() {
  const preset = String(state.dataBroker?.comparison?.preset || document.getElementById("targetTop5Cycle")?.dataset?.cyclePreset || "rank-5");
  return preset;
}

function atlasAnalyticalFingerprintPayload(envelope) {
  const targetAssets = Array.isArray(envelope?.target?.assets) ? envelope.target.assets : [];
  const sourceDescriptors = Array.isArray(envelope?.source_truth?.descriptors) ? envelope.source_truth.descriptors : [];
  return {
    schema: envelope.schema,
    application: envelope.application,
    market: {
      timestamp: envelope.market?.timestamp || null,
      assets_loaded: envelope.market?.assets_loaded || 0,
      target_assets: envelope.market?.target_assets || 250,
      quote_currency: envelope.market?.quote_currency || "EUR",
      mode: envelope.market?.mode || null,
      breadth_24h: envelope.market?.breadth_24h || null
    },
    target: {
      mode: envelope.target?.mode || null,
      symbols: targetAssets.map(row => row?.symbol || null),
      availability: targetAssets.map(row => !!row?.available),
      source_status: targetAssets.map(row => row?.quote_status || row?.source || null)
    },
    graph: {
      period_days: envelope.graph?.period_days || null,
      view: envelope.graph?.view || null,
      scale: envelope.graph?.scale || null,
      selected_ids: envelope.graph?.selected_ids || [],
      selected_symbols: envelope.graph?.selected_symbols || [],
      status: envelope.graph?.status || null,
      timestamp: envelope.graph?.timestamp || null,
      series: (envelope.graph?.series || []).map(row => ({
        symbol: row?.symbol || null,
        points: row?.points || 0,
        first_time: row?.first_time || null,
        last_time: row?.last_time || null,
        source_mode: row?.source_mode || null
      }))
    },
    scanner: envelope.scanner,
    math_core: {
      asset: envelope.math_core?.asset || null,
      active_window: envelope.math_core?.active_window || null,
      historical_risk: envelope.math_core?.historical_risk || null,
      quality_counts: envelope.quality_gates?.counts || null,
      method_version: envelope.quality_gates?.schema || null
    },
    news_sentinel: {
      status: envelope.news_sentinel?.status || null,
      archive_time: envelope.news_sentinel?.archive_time || null,
      event_ids: (envelope.evidence?.events || []).map(row => row.id),
      confidence: (envelope.evidence?.events || []).map(row => row.confidence)
    },
    watchlist: envelope.watchlist,
    source_truth: sourceDescriptors.map(row => ({
      id: row.id,
      provider: row.provider,
      mode: row.mode,
      freshness: row.freshness,
      instrument: row.instrument
    })),
    contradictions: (envelope.contradictions?.items || []).map(row => ({
      id: row.id,
      severity: row.severity,
      status: row.status,
      stop_gate: row.stop_gate
    }))
  };
}

function atlasAnalyticalBuildEnvelope(snapshot) {
  const contract = snapshot?.strict_contract || {};
  const sourceTruth = contract.source_truth_v2 || atlasSourceTruthBuild(contract);
  const evidence = contract.evidence_v2 || atlasEvidenceLayerBuild(contract);
  const quality = contract.math_quality_gates_v2 || atlasMathQualityGatesBuild(contract.math || {});
  const contradictions = contract.contradictions_v2 || atlasContradictionsV2Build(contract, sourceTruth, quality, evidence);
  const envelope = {
    schema: ATLAS_ANALYTICAL_STATE_SCHEMA,
    generated_at: snapshot?.generated_at || new Date().toISOString(),
    application: {
      interface_release: ATLAS_RELEASE,
      bridge_release: ATLAS_STABLE_STACK.bridge,
      control_center_release: ATLAS_STABLE_STACK.controlCenter,
      model: ATLAS_STABLE_STACK.model,
      fact_contract: contract.schema || null,
      fingerprint_version: ATLAS_ANALYTICAL_FINGERPRINT_VERSION
    },
    market: atlasSharedSynthesisClone(contract.market || {}),
    target: {
      mode: atlasAnalyticalTargetMode(),
      ...atlasSharedSynthesisClone(contract.canonical_top5 || {})
    },
    graph: atlasSharedSynthesisClone(contract.graph || {}),
    scanner: atlasSharedSynthesisClone(contract.scanner_collector || { status: "empty" }),
    math_core: atlasSharedSynthesisClone(contract.math || {}),
    news_sentinel: atlasSharedSynthesisClone(contract.news || {}),
    watchlist: atlasSharedSynthesisClone(contract.watchlist || {}),
    source_truth: atlasSharedSynthesisClone(sourceTruth),
    evidence: atlasSharedSynthesisClone(evidence),
    quality_gates: atlasSharedSynthesisClone(quality),
    contradictions: atlasSharedSynthesisClone(contradictions),
    safety: atlasSharedSynthesisClone(snapshot?.safety || {})
  };
  const canonicalPayload = atlasAnalyticalFingerprintPayload(envelope);
  envelope.fingerprint = {
    algorithm: "SHA-256",
    canonical_payload_version: "v2",
    value: atlasSha256(atlasCanonicalStringify(canonicalPayload))
  };
  return envelope;
}

function atlasAnalyticalSetText(id, value) {
  setText(document.getElementById(id), value);
}

function atlasAnalyticalList(id, rows, empty = "Aucune donnée.") {
  const node = document.getElementById(id);
  if (!node) return;
  const safe = Array.isArray(rows) && rows.length ? rows : [empty];
  node.innerHTML = safe.map(row => `<li>${atlasLocalEscapeHtml(row)}</li>`).join("");
}

function atlasAnalyticalSourceSummary(sourceTruth) {
  const counts = sourceTruth?.counts || {};
  const direct = Number(counts[ATLAS_SOURCE_TRUTH_MODES.DIRECT] || 0) + Number(counts[ATLAS_SOURCE_TRUTH_MODES.DERIVED_DIRECT] || 0);
  const conserved = Number(counts[ATLAS_SOURCE_TRUTH_MODES.DIRECT_CONSERVED] || 0);
  const cached = Number(counts[ATLAS_SOURCE_TRUTH_MODES.CACHE_RECENT] || 0) + Number(counts[ATLAS_SOURCE_TRUTH_MODES.CACHE_DATED] || 0);
  const archived = Number(counts[ATLAS_SOURCE_TRUTH_MODES.ARCHIVE] || 0);
  const unavailable = Number(counts[ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE] || 0);
  const parts = [`${direct} direct${direct > 1 ? "es" : "e"}`];
  if (conserved) parts.push(`${conserved} conservée${conserved > 1 ? "s" : ""}`);
  if (cached) parts.push(`${cached} cache${cached > 1 ? "s" : ""}`);
  if (archived) parts.push(`${archived} archive${archived > 1 ? "s" : ""}`);
  if (unavailable) parts.push(`${unavailable} indisponible${unavailable > 1 ? "s" : ""}`);
  return parts.join(" · ");
}

function atlasAnalyticalTruthRender(envelope = null) {
  const panel = document.getElementById("atlasAnalyticalTruth");
  if (!panel) return false;
  const pkg = atlasSharedSynthesisState?.package || null;
  const current = envelope || atlasAnalyticalTruthState.currentEnvelope || pkg?.analytical_state || null;
  const analysisFingerprint = atlasLocalDialogueState?.conclusionResponse?.fingerprint || pkg?.fingerprint || atlasAnalyticalTruthState.analysisFingerprint || "";
  const currentFingerprint = current?.fingerprint?.value ? `sha256:${current.fingerprint.value}` : "";
  atlasAnalyticalTruthState.analysisFingerprint = analysisFingerprint;
  let stateName = "waiting";
  let badge = "En attente";
  let context = "En attente";
  let contextDetail = "Aucun snapshot analytique V2 calculé.";
  let analysis = "Non produite";
  let analysisDetail = "Les quatre rapports et la conclusion restent transactionnels.";
  if (current) {
    context = "Cohérent";
    contextDetail = `${current.graph?.period_label || "Période inconnue"} · ${current.graph?.selected_symbols?.join(" · ") || current.target?.symbols?.join(" · ") || "sélection courante"}`;
    stateName = "ready";
    badge = "Vérifiée";
    if (analysisFingerprint) {
      const normalizedAnalysis = String(analysisFingerprint).replace(/^sha256:/, "");
      if (normalizedAnalysis === current.fingerprint?.value) {
        analysis = "Actuelle";
        analysisDetail = "Rapports 4/4 et conclusion liés à cette empreinte.";
      } else {
        analysis = "Conservée";
        analysisDetail = "Le contexte affiché a changé ; l’analyse précédente reste intacte.";
        stateName = "conserved";
        badge = "Conservée";
      }
    } else if (pkg) {
      analysis = "Conservée";
      analysisDetail = "Synthèse restaurée en lecture ; moteur local non requis.";
      stateName = "reading";
      badge = "Lecture";
    }
  } else if (pkg) {
    stateName = "reading";
    badge = "Lecture legacy";
    context = "Non vérifié";
    contextDetail = "Synthèse antérieure sans Analytical State V2.";
    analysis = "Conservée";
    analysisDetail = "Import lisible, empreinte V2 absente.";
  }
  panel.dataset.state = stateName;
  const badgeNode = document.getElementById("atlasAnalyticalTruthBadge");
  if (badgeNode) {
    badgeNode.textContent = badge;
    badgeNode.className = `pill ${["ready", "reading"].includes(stateName) ? "ok" : "warn"}`;
  }
  atlasAnalyticalSetText("atlasTruthContext", context);
  atlasAnalyticalSetText("atlasTruthContextDetail", contextDetail);
  atlasAnalyticalSetText("atlasTruthFingerprint", currentFingerprint ? `${currentFingerprint.slice(0, 20)}…` : "—");
  atlasAnalyticalSetText("atlasTruthFingerprintDetail", currentFingerprint ? "SHA-256 canonique · contexte analytique V2" : "SHA-256 canonique.");
  const sourceTruth = current?.source_truth || null;
  atlasAnalyticalSetText("atlasTruthSources", sourceTruth ? atlasAnalyticalSourceSummary(sourceTruth) : "—");
  atlasAnalyticalSetText("atlasTruthSourcesDetail", sourceTruth ? "Taxonomie Source Truth V2 appliquée." : "Aucune source normalisée.");
  const evidenceEvent = current?.evidence?.events?.[0] || null;
  atlasAnalyticalSetText("atlasTruthNews", evidenceEvent ? `${evidenceEvent.confidence} · preuve ${evidenceEvent.proof_quality}` : "Aucun événement");
  atlasAnalyticalSetText("atlasTruthNewsDetail", evidenceEvent ? `Impact ${evidenceEvent.impact_potential} · ${evidenceEvent.independent_sources} source indépendante.` : "Impact séparé de la confiance.");
  const quality = current?.quality_gates || null;
  const q = quality?.counts || {};
  atlasAnalyticalSetText("atlasTruthMath", quality ? `${q.PUBLISHED || 0} publiées · ${q.DEGRADED || 0} dégradées · ${q.BLOCKED || 0} bloquées` : "—");
  atlasAnalyticalSetText("atlasTruthMathDetail", quality ? `${quality.returns_count || 0} rendements · complétude ${Number(quality.completeness_pct || 0).toFixed(1)} %.` : "Aucune mesure évaluée.");
  const contradictions = current?.contradictions || null;
  atlasAnalyticalSetText("atlasTruthContradictions", contradictions ? `${contradictions.counts?.total || 0} enregistrées` : "—");
  atlasAnalyticalSetText("atlasTruthContradictionsDetail", contradictions ? `${contradictions.counts?.stop || 0} stop gate · ${contradictions.counts?.to_verify || 0} à vérifier.` : "Limites et stop gates structurés.");
  atlasAnalyticalSetText("atlasTruthAnalysis", analysis);
  atlasAnalyticalSetText("atlasTruthAnalysisDetail", analysisDetail);
  atlasAnalyticalList("atlasTruthContextList", current ? [
    `Interface : ${current.application?.interface_release || ATLAS_RELEASE}`,
    `Graphique : ${current.graph?.period_label || "—"} · ${current.graph?.view || "—"} · ${current.graph?.scale || "—"}`,
    `Séries : ${(current.graph?.selected_symbols || []).join(" · ") || "—"}`,
    `Scanner : ${current.scanner?.status || "—"} · ${current.scanner?.collected_at || "aucun snapshot"}`,
    `Empreinte : ${currentFingerprint || "—"}`
  ] : []);
  atlasAnalyticalList("atlasTruthSourceList", sourceTruth?.descriptors?.map(row => `${row.provider} · ${row.mode} · ${row.freshness}${row.instrument ? ` · ${row.instrument}` : ""}`) || []);
  atlasAnalyticalList("atlasTruthEvidenceList", evidenceEvent ? [
    `${evidenceEvent.headline}`,
    `Impact potentiel : ${evidenceEvent.impact_potential}`,
    `Confiance : ${evidenceEvent.confidence}`,
    `Preuve : ${evidenceEvent.proof_quality}`,
    `Sources : ${evidenceEvent.reported_sources} reprise(s) · ${evidenceEvent.independent_sources} indépendante(s)`,
    "Action : observation uniquement"
  ] : []);
  atlasAnalyticalList("atlasTruthMathList", quality?.gates?.map(gate => `${gate.metric} · ${gate.status} · ${gate.reason}`) || []);
  atlasAnalyticalList("atlasTruthContradictionList", contradictions?.items?.map(row => `[${row.severity}] ${row.statement}${row.stop_gate ? " · STOP" : ""}`) || []);
  atlasAnalyticalSetText(
    "atlasAnalyticalTruthStatus",
    current
      ? `${analysis} · empreinte ${currentFingerprint ? "vérifiée" : "absente"} · aucune prévision ni action financière.`
      : "Empreinte V2 en attente · aucune action financière."
  );
  atlasAnalyticalTruthState.lastRenderedFingerprint = currentFingerprint;
  return true;
}

/* Le contrat factuel final reçoit Source Truth, Evidence, Quality Gates
   et contradictions structurées avant tout envoi au Bridge. */
const atlasBuildStrictFactContractV96 = atlasBuildStrictFactContract;
atlasBuildStrictFactContract = function atlasBuildStrictFactContractV97(period, chart, chartResult, comparisonIds, chartTruth) {
  const contract = atlasBuildStrictFactContractV96(period, chart, chartResult, comparisonIds, chartTruth);
  const sourceTruth = atlasSourceTruthBuild(contract);
  const evidence = atlasEvidenceLayerBuild(contract);
  const quality = atlasMathQualityGatesBuild(contract.math || {});
  contract.math = atlasMathApplyQualityGates(contract.math || {}, quality);
  contract.source_truth_v2 = sourceTruth;
  contract.evidence_v2 = evidence;
  contract.math_quality_gates_v2 = quality;
  contract.contradictions_v2 = atlasContradictionsV2Build(contract, sourceTruth, quality, evidence);
  contract.schema = "atlas_crypto_fact_contract_v3_truth_evidence";
  contract.rules = {
    ...(contract.rules || {}),
    analytical_fingerprint_v2: true,
    source_truth_v2: true,
    evidence_independence_required: true,
    metric_quality_gates: true,
    transactional_conclusion: true
  };
  return contract;
};

/* Chaque snapshot reçoit son enveloppe et son empreinte canonique. */
const atlasBuildCryptoPageSnapshotV96 = atlasBuildCryptoPageSnapshot;
atlasBuildCryptoPageSnapshot = function atlasBuildCryptoPageSnapshotV97() {
  const snapshot = atlasBuildCryptoPageSnapshotV96();
  const envelope = atlasAnalyticalBuildEnvelope(snapshot);
  snapshot.schema = "atlas_crypto_page_snapshot_v3_truth_evidence";
  snapshot.analytical_state = envelope;
  snapshot.fingerprint = `sha256:${envelope.fingerprint.value}`;
  atlasAnalyticalTruthState.currentEnvelope = envelope;
  atlasAnalyticalTruthState.currentFingerprint = snapshot.fingerprint;
  atlasAnalyticalTruthRender(envelope);
  return snapshot;
};

/* Les quatre rapports et la conclusion utilisent maintenant la même
   empreinte complète au lieu du résumé Build|timestamp|count|currency. */
atlasLocalReportSnapshotFingerprint = function atlasLocalReportSnapshotFingerprintV2(snapshot) {
  if (!snapshot) return "";
  if (!snapshot.analytical_state) snapshot.analytical_state = atlasAnalyticalBuildEnvelope(snapshot);
  const value = snapshot?.analytical_state?.fingerprint?.value;
  return value ? `sha256:${value}` : "";
};

/* Validation de conclusion structurée : six familles sémantiques,
   sans dépendre exactement d'une seule orthographe de titre. */
atlasLocalConclusionMeaningful = function atlasLocalConclusionMeaningfulV2(result) {
  const answer = String(result?.answer || "").replace(/\r\n?/g, "\n").trim();
  if (answer.length < 240) return false;
  const lower = answer.toLocaleLowerCase("fr-FR");
  const families = [
    ["situation générale", "situation du marché", "état général"],
    ["signal dominant", "lecture dominante", "signal principal"],
    ["points de vigilance", "vigilance", "risques observés"],
    ["contradictions importantes", "contradictions", "points contradictoires"],
    ["surveiller ensuite", "surveillance suivante", "à surveiller"],
    ["limites et stop point", "limites", "stop point"]
  ];
  const matched = families.filter(group => group.some(marker => lower.includes(marker))).length;
  const forbidden = /(acheter maintenant|vendre maintenant|ordre automatique|garanti|gain certain)/i.test(answer);
  return matched >= 5 && lower.includes("validation humaine") && !forbidden;
};

/* Les paquets IndexedDB/Book conservent la preuve analytique V2. */
const atlasSharedSynthesisNormalizePackageV96 = atlasSharedSynthesisNormalizePackage;
atlasSharedSynthesisNormalizePackage = function atlasSharedSynthesisNormalizePackageV97(input) {
  const normalized = atlasSharedSynthesisNormalizePackageV96(input);
  normalized.fingerprint_version = String(input?.fingerprint_version || input?.analytical_state?.application?.fingerprint_version || "legacy");
  normalized.analytical_state = atlasSharedSynthesisClone(input?.analytical_state || input?.snapshot?.analytical_state || null);
  if (normalized.analytical_state?.fingerprint?.value) {
    const analyticalFingerprint = `sha256:${normalized.analytical_state.fingerprint.value}`;
    if (normalized.fingerprint && normalized.fingerprint !== analyticalFingerprint) {
      throw new Error("empreinte analytique différente de la synthèse");
    }
    normalized.fingerprint = analyticalFingerprint;
    normalized.fingerprint_version = ATLAS_ANALYTICAL_FINGERPRINT_VERSION;
  }
  normalized.status = {
    ...(normalized.status || {}),
    analytical_truth: normalized.analytical_state ? "verified_v2" : "legacy_unverified"
  };
  return normalized;
};

const atlasSharedSynthesisBuildSummaryV96 = atlasSharedSynthesisBuildSummary;
atlasSharedSynthesisBuildSummary = function atlasSharedSynthesisBuildSummaryV97(snapshot) {
  const envelope = snapshot?.analytical_state || atlasAnalyticalBuildEnvelope(snapshot);
  const sourceSummary = atlasAnalyticalSourceSummary(envelope.source_truth);
  const quality = envelope.quality_gates?.counts || {};
  const event = envelope.evidence?.events?.[0] || null;
  const truth = [
    "**0. Vérité analytique**",
    `- Empreinte : sha256:${envelope.fingerprint.value}.`,
    `- Sources : ${sourceSummary}.`,
    `- News : ${event ? `${event.confidence} · preuve ${event.proof_quality} · impact ${event.impact_potential}` : "aucun événement directeur"}.`,
    `- Math Core : ${quality.PUBLISHED || 0} publiées · ${quality.DEGRADED || 0} dégradées · ${quality.BLOCKED || 0} bloquées.`,
    `- Contradictions : ${envelope.contradictions?.counts?.total || 0} · stop gates ${envelope.contradictions?.counts?.stop || 0}.`,
    ""
  ].join("\n");
  return truth + atlasSharedSynthesisBuildSummaryV96(snapshot);
};

const atlasSharedSynthesisPackageMarkdownV96 = atlasSharedSynthesisPackageMarkdown;
atlasSharedSynthesisPackageMarkdown = function atlasSharedSynthesisPackageMarkdownV97(pkg) {
  const base = atlasSharedSynthesisPackageMarkdownV96(pkg);
  const envelope = pkg?.analytical_state;
  if (!envelope) return base + "\n\n## Vérité analytique\n\nSynthèse legacy : empreinte analytique V2 absente.";
  return base + [
    "", "## Vérité analytique V2", "",
    `- Schéma : ${envelope.schema}`,
    `- Empreinte : sha256:${envelope.fingerprint?.value || "—"}`,
    `- Source Truth : ${atlasAnalyticalSourceSummary(envelope.source_truth)}`,
    `- Math Core : ${envelope.quality_gates?.counts?.PUBLISHED || 0} publiées · ${envelope.quality_gates?.counts?.DEGRADED || 0} dégradées · ${envelope.quality_gates?.counts?.BLOCKED || 0} bloquées`,
    `- Contradictions : ${envelope.contradictions?.counts?.total || 0}`,
    "- Action : observation uniquement · validation humaine obligatoire"
  ].join("\n");
};

const atlasSharedSynthesisActivateV96 = atlasSharedSynthesisActivate;
atlasSharedSynthesisActivate = function atlasSharedSynthesisActivateV97(pkg, source) {
  const clean = atlasSharedSynthesisActivateV96(pkg, source);
  atlasAnalyticalTruthState.analysisFingerprint = clean?.fingerprint || "";
  if (clean?.analytical_state) atlasAnalyticalTruthState.currentEnvelope = clean.analytical_state;
  atlasAnalyticalTruthRender(clean?.analytical_state || null);
  return clean;
};

const atlasSharedSynthesisRenderV96 = atlasSharedSynthesisRender;
atlasSharedSynthesisRender = function atlasSharedSynthesisRenderV97() {
  const result = atlasSharedSynthesisRenderV96();
  atlasAnalyticalTruthRender();
  return result;
};

const atlasStableStackRenderV96 = atlasStableStackRender;
atlasStableStackRender = function atlasStableStackRenderV97() {
  const result = atlasStableStackRenderV96();
  atlasAnalyticalTruthRender();
  return result;
};

const atlasLocalReportStoreV96 = atlasLocalReportStore;
atlasLocalReportStore = function atlasLocalReportStoreV97(mode, result, snapshot, options = {}) {
  const report = atlasLocalReportStoreV96(mode, result, snapshot, options);
  if (report) {
    report.fingerprint_version = ATLAS_ANALYTICAL_FINGERPRINT_VERSION;
    report.analytical_state_schema = snapshot?.analytical_state?.schema || null;
    atlasAnalyticalTruthState.analysisFingerprint = report.fingerprint || atlasAnalyticalTruthState.analysisFingerprint;
    atlasAnalyticalTruthRender(snapshot?.analytical_state || null);
  }
  return report;
};

function atlasAnalyticalTruthIsBusy() {
  return !!atlasScannerTransaction
    || !!atlasScannerQueuedRequest
    || !!state.chartEngineV2?.loading
    || !!atlasLocalReportsState.running
    || !!atlasLocalConclusionState.running;
}

function atlasAnalyticalTruthSchedule(delay = 650) {
  if (atlasAnalyticalTruthState.timer) window.clearTimeout(atlasAnalyticalTruthState.timer);
  atlasAnalyticalTruthState.timer = window.setTimeout(() => {
    atlasAnalyticalTruthState.timer = 0;
    if (document.visibilityState !== "visible") return;
    if (atlasAnalyticalTruthIsBusy()) {
      atlasAnalyticalTruthSchedule(900);
      return;
    }
    if (Array.isArray(state.coins) && state.coins.length) {
      try { atlasBuildCryptoPageSnapshot(); }
      catch (error) {
        console.warn("Vérité analytique différée :", error);
        atlasAnalyticalTruthRender();
      }
    } else {
      atlasAnalyticalTruthRender();
    }
  }, Math.max(0, Number(delay) || 0));
  return true;
}

function atlasAnalyticalTruthInit() {
  if (atlasAnalyticalTruthState.initialized) return true;
  atlasAnalyticalTruthState.initialized = true;
  atlasAnalyticalTruthRender();

  window.addEventListener("online", () => atlasAnalyticalTruthSchedule(500));
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") atlasAnalyticalTruthSchedule(500);
  });

  /* Additif uniquement : les fonctions Target, Scanner, Graphique,
     Market Flow et leurs transactions restent celles de la 28.1.96.
     L'empreinte attend la fin de toute transaction avant de lire l'état. */
  document.addEventListener("click", () => atlasAnalyticalTruthSchedule(700), true);
  document.addEventListener("change", () => atlasAnalyticalTruthSchedule(700), true);

  atlasAnalyticalTruthSchedule(2200);
  return true;
}

/* =========================================================
   Build 28.2.74 — Rapport Métaux public automatique
   - GitHub Actions publie les cotations et l’historique public ;
   - l’Interface produit un rapport local déterministe ;
   - IndexedDB conserve le dernier rapport public valide sur chaque poste ;
   - la comparaison visible utilise uniquement la série Futures historique ;
   - la cotation indicative courante reste distincte de cette série ;
   - aucune requête fournisseur n’est déclenchée par la page.
   ========================================================= */
const ATLAS_METALS_REPORT_SCHEMA = "agent_crypto_metals_public_report_v1";
const ATLAS_METALS_REPORT_STORAGE_SCHEMA = "agent_crypto_metals_public_report_indexeddb_v1";
const ATLAS_METALS_REPORT_DB_NAME = "agent_crypto_metals_public_report_memory_v2";
const ATLAS_METALS_REPORT_DB_VERSION = 1;
const ATLAS_METALS_REPORT_STORE = "reports";
const ATLAS_METALS_REPORT_RECORD_ID = "current";
const ATLAS_METALS_REPORT_LIMIT_BYTES = 5 * 1024 * 1024;
const ATLAS_METALS_REPORT_INTERFACE_PATH = null;

const atlasMetalsReportState = {
  initialized: false,
  package: null,
  source: "none",
  persistence: { ok: false, bytes: 0, error: "Non enregistrée" },
  restorePromise: null,
  operation: 0
};

function atlasMetalsReportClone(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function atlasMetalsReportUtf8Bytes(text) {
  try { return new TextEncoder().encode(String(text || "")).byteLength; }
  catch { return unescape(encodeURIComponent(String(text || ""))).length; }
}

function atlasMetalsReportStableValue(value) {
  if (Array.isArray(value)) return value.map(atlasMetalsReportStableValue);
  if (value && typeof value === "object") {
    return Object.keys(value).sort().reduce((out, key) => {
      out[key] = atlasMetalsReportStableValue(value[key]);
      return out;
    }, {});
  }
  return value;
}

async function atlasMetalsReportSha256(value) {
  const canonical = JSON.stringify(atlasMetalsReportStableValue(value));
  const bytes = new TextEncoder().encode(canonical);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)]
    .map(byte => byte.toString(16).padStart(2, "0"))
    .join("");
}

function atlasMetalsReportIso(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const time = Date.parse(raw);
  return Number.isFinite(time) ? new Date(time).toISOString() : null;
}

function atlasMetalsReportDate(value) {
  const iso = atlasMetalsReportIso(value);
  if (!iso) return "—";
  return new Date(iso).toLocaleString("fr-FR", {
    day: "2-digit", month: "2-digit", year: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit"
  });
}

function atlasMetalsReportPrice(quote) {
  return atlasMetalsQuoteFoundationPriceText(quote);
}

function atlasMetalsReportPercent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "—";
  return `${number > 0 ? "+" : ""}${new Intl.NumberFormat("fr-FR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(number)} %`;
}

function atlasMetalsReportSnapshotTime(snapshot) {
  return atlasMetalsReportIso(snapshot?.saved_at)
    || atlasMetalsReportIso(snapshot?.quotes?.[0]?.received_at)
    || atlasMetalsReportIso(snapshot?.quotes?.[0]?.source_time)
    || null;
}

function atlasMetalsReportSanitizeCollector(collector) {
  return {
    schema: String(collector?.schema || "agent_crypto_metals_collector_status_v1"),
    status: String(collector?.status || "unknown"),
    provider_id: collector?.provider_id || null,
    provider_name: collector?.provider_name || null,
    last_success_at: atlasMetalsReportIso(collector?.last_success_at),
    assets_expected: Number(collector?.assets_expected || 5),
    assets_received: Number(collector?.assets_received || 0),
    history: atlasMetalsReportClone(collector?.history || null)
  };
}

function atlasMetalsReportHistorySnapshots() {
  const snapshots = Array.isArray(atlasMetalsQuoteFoundationState.history)
    ? atlasMetalsQuoteFoundationState.history
    : [];
  const map = new Map();
  snapshots.filter(Boolean).forEach(snapshot => {
    const quotes = Array.isArray(snapshot?.quotes) ? snapshot.quotes : [];
    if (!quotes.length || quotes.some(quote => quote?.instrument_type !== "future_continuous")) return;
    const key = String(
      snapshot?.snapshot_id
      || atlasMetalsReportSnapshotTime(snapshot)
      || JSON.stringify(quotes)
    );
    if (key) map.set(key, atlasMetalsReportClone(snapshot));
  });
  return [...map.values()].sort((left, right) => {
    return Date.parse(atlasMetalsReportSnapshotTime(left) || 0)
      - Date.parse(atlasMetalsReportSnapshotTime(right) || 0);
  });
}

function atlasMetalsReportHistoryForAsset(assetId, snapshots) {
  return snapshots.map(snapshot => {
    const quote = (Array.isArray(snapshot?.quotes) ? snapshot.quotes : [])
      .find(row => row?.asset_id === assetId && Number.isFinite(Number(row?.price)));
    if (!quote) return null;
    return {
      time: atlasMetalsReportSnapshotTime(snapshot)
        || atlasMetalsReportIso(quote.received_at)
        || atlasMetalsReportIso(quote.source_time),
      price: Number(quote.price),
      currency: String(quote.currency || "").toUpperCase(),
      unit: String(quote.unit || "")
    };
  }).filter(row => row?.time && Number.isFinite(row.price));
}

function atlasMetalsReportHistoryReading(points) {
  if (points.length < 2) {
    return {
      count: points.length,
      change_percent: null,
      label: points.length === 1
        ? "1 relevé réel · trajectoire non calculable"
        : "aucun relevé historique exploitable"
    };
  }
  const first = points[0];
  const last = points[points.length - 1];
  const change = first.price !== 0
    ? ((last.price - first.price) / first.price) * 100
    : null;
  return {
    count: points.length,
    change_percent: Number.isFinite(change) ? change : null,
    label: Number.isFinite(change)
      ? `${points.length} séances Futures · évolution observée ${atlasMetalsReportPercent(change)}`
      : `${points.length} séances Futures · évolution non calculable`
  };
}

function atlasMetalsReportAssetRows(snapshot, historySnapshots) {
  const quotes = Array.isArray(snapshot?.quotes) ? snapshot.quotes : [];
  return ATLAS_METALS_ASSETS.map(base => {
    const quote = quotes.find(row => row?.asset_id === base.id) || null;
    const structure = atlasMetalsStructuralAsset(base.id) || {};
    const points = atlasMetalsReportHistoryForAsset(base.id, historySnapshots);
    const history = atlasMetalsReportHistoryReading(points);
    return {
      id: base.id,
      name: base.name,
      symbol: base.symbol,
      family: base.family,
      quote: quote ? {
        asset_id: base.id,
        symbol: base.symbol,
        price: Number.isFinite(Number(quote.price)) ? Number(quote.price) : null,
        price_eur: Number.isFinite(Number(quote.price_eur)) ? Number(quote.price_eur) : null,
        fx_source_date: quote.fx_source_date || null,
        currency: String(quote.currency || "").toUpperCase(),
        unit: String(quote.unit || ""),
        change_percent:
          quote.change_percent !== null
          && quote.change_percent !== undefined
          && quote.change_percent !== ""
          && Number.isFinite(Number(quote.change_percent))
            ? Number(quote.change_percent)
            : null,
        data_state: String(quote.data_state || "unknown"),
        source_id: quote.source_id || quote.provider_id || null,
        source_name: quote.source_name || quote.provider_name || null,
        source_time: atlasMetalsReportIso(quote.source_time),
        received_at: atlasMetalsReportIso(quote.received_at)
      } : null,
      history,
      history_points: points,
      structure: {
        production: String(structure?.production?.display || "—"),
        reserves: String(structure?.reserves?.display || "—"),
        producers: String(structure?.production?.top_display || "—"),
        uses: String(structure?.uses?.display || "—"),
        eu_status: String(structure?.eu_status?.display || "—"),
        source_ids: Array.isArray(structure?.source_ids)
          ? [...structure.source_ids]
          : []
      }
    };
  });
}

function atlasMetalsReportWarnings(assets, snapshot, historySnapshots) {
  const warnings = [];
  const delayed = assets.filter(asset => asset.quote?.data_state === "data_delayed");
  if (delayed.length) {
    warnings.push(`Cotations différées : ${delayed.map(asset => asset.symbol).join(" / ")}.`);
  }
  const missing = assets.filter(asset => !Number.isFinite(Number(asset.quote?.price)));
  if (missing.length) {
    warnings.push(`Cotations absentes : ${missing.map(asset => asset.symbol).join(" / ")}.`);
  }
  if (historySnapshots.length < 2) {
    warnings.push("Historique insuffisant : une seule séance Futures ne permet pas d’établir une trajectoire.");
  }
  const currencies = new Set(assets.map(asset => asset.quote?.currency).filter(Boolean));
  if (currencies.size > 1) warnings.push("Unités monétaires multiples : comparaison directe des niveaux de prix interdite.");
  if (snapshot?.integrity?.no_invented_values !== true) {
    warnings.push("Verrou anti-invention absent du snapshot.");
  }
  return warnings;
}

function atlasMetalsReportBuildMarkdown(pkg) {
  const assets = pkg.assets;
  const warnings = pkg.warnings;
  const historyCount = pkg.history.length;
  const quoteLines = assets.map(asset => {
    const providerChange = asset.quote?.change_percent;
    const providerChangeAvailable =
      providerChange !== null
      && providerChange !== undefined
      && providerChange !== ""
      && Number.isFinite(Number(providerChange));
    const providerPart = providerChangeAvailable
      ? ` · variation fournisseur ${atlasMetalsReportPercent(providerChange)}`
      : " · variation fournisseur non fournie";
    const eurPart = Number.isFinite(Number(asset.quote?.price_eur))
      ? ` · ${atlasMetalsQuoteFoundationEurText(asset.quote)} indicatif BCE`
      : "";
    return `- ${asset.name} (${asset.symbol}) : ${atlasMetalsReportPrice(asset.quote)}${eurPart}${providerPart} · ${atlasMetalsQuoteFoundationStateLabel(asset.quote)}.`;
  });
  const historyLines = assets.map(asset => `- ${asset.symbol} : ${asset.history.label}.`);
  const structureLines = assets.map(asset => {
    return `- ${asset.symbol} : production ${asset.structure.production} · réserves ${asset.structure.reserves} · producteurs ${asset.structure.producers} · usages ${asset.structure.uses} · UE ${asset.structure.eu_status}.`;
  });
  const warningLines = warnings.length
    ? warnings.map(item => `- ${item}`)
    : ["- Aucune incohérence bloquante détectée dans le paquet 5/5."];
  const watchLines = [
    "- Vérifier l’âge du dernier snapshot public et l’état du collecteur.",
    "- Contrôler la continuité des cinq symboles XAU / XAG / XPT / XPD / HG.",
    "- Comparer les trajectoires uniquement dans la série Futures quotidienne homogène.",
    "- Distinguer cotations spot, futures US, conversion BCE et données structurelles."
  ];
  const complete = assets.every(asset => Number.isFinite(Number(asset.quote?.price)));
  const conclusion = complete
    ? (historyCount >= 2
      ? "Le panier Métaux est complet 5/5. Les variations historiques affichées reposent uniquement sur la série Futures quotidienne conservée ; elles décrivent l’état observé et non une évolution future."
      : "Le panier Métaux est complet 5/5, mais l’historique reste trop court pour qualifier une trajectoire. Le rapport décrit uniquement le snapshot observé.")
    : "Le panier Métaux est incomplet. Le rapport conserve les données disponibles sans remplacer les valeurs absentes.";

  return [
    "**1. État de la collecte**",
    `- Origine : ${pkg.origin.label}.`,
    `- Snapshot : ${atlasMetalsReportDate(pkg.snapshot_at)} · couverture ${pkg.status.quotes}/5.`,
    `- Source de cotation : ${pkg.source.provider_name || "Sources publiques"} · état ${pkg.source.status}.`,
    "- La lecture du rapport ne déclenche aucune requête fournisseur : les données sont déjà publiées par GitHub Actions.",
    "",
    "**2. Panier Métaux précieux et industriels**",
    ...quoteLines,
    "",
    "**3. Lecture des cotations**",
    `- ${complete ? "Les cinq cotations attendues sont présentes." : "Le panier contient des valeurs manquantes."}`,
    "- Les niveaux de prix sont conservés dans leur devise et leur unité source ; la conversion EUR BCE reste informative.",
    "- La variation fournisseur, lorsqu’elle est fournie, reste séparée de la variation calculée sur l’historique Futures public.",
    "",
    "**4. Historique réel et comparaison**",
    `- ${historyCount} séance${historyCount > 1 ? "s" : ""} Futures quotidienne${historyCount > 1 ? "s" : ""} conservée${historyCount > 1 ? "s" : ""}.`,
    ...historyLines,
    "",
    "**5. Structure physique et sources publiques**",
    ...structureLines,
    `- Sources préparées : ${pkg.source.public_sources.join(" · ")}.`,
    "",
    "**6. Contradictions et données manquantes**",
    ...warningLines,
    "",
    "**7. Ce qu’il faut surveiller ensuite**",
    ...watchLines,
    "",
    "**8. Limites et stop point**",
    "- Observation uniquement : aucune prévision, aucun ordre et aucun signal d’exécution.",
    "- Arrêter toute comparaison si les dates, devises, unités ou états de données ne sont plus cohérents.",
    "- Les données structurelles décrivent production, réserves et usages ; elles ne remplacent jamais une cotation de marché.",
    "- Validation humaine obligatoire.",
    "",
    "**9. Conclusion du rapport Métaux public**",
    `- ${conclusion}`
  ].join("\n");
}

async function atlasMetalsReportBuildPackage() {
  const snapshot = atlasMetalsReportClone(atlasMetalsQuoteFoundationState.snapshot);
  if (!snapshot) throw new Error("snapshot Métaux absent");
  const history = atlasMetalsReportHistorySnapshots();
  const assets = atlasMetalsReportAssetRows(snapshot, history);
  const quoteCount = assets.filter(asset => Number.isFinite(Number(asset.quote?.price))).length;
  if (quoteCount !== 5) throw new Error(`panier Métaux incomplet : ${quoteCount}/5`);
  const publicSources = atlasMetalsStructuralArray(atlasMetalsStructuralRegistry()?.sources)
    .map(source => String(source?.short_name || source?.name || "").trim())
    .filter(Boolean);
  const snapshotAt = atlasMetalsReportSnapshotTime(snapshot);
  const source = atlasMetalsReportSanitizeCollector(atlasMetalsQuoteFoundationState.collector);
  const signature = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    snapshot,
    history,
    structural_version: atlasMetalsStructuralRegistry()?.version || null,
    assets: assets.map(asset => ({
      id: asset.id,
      quote: asset.quote,
      history_points: asset.history_points,
      structure: asset.structure
    }))
  };
  const fingerprint = `sha256:${await atlasMetalsReportSha256(signature)}`;
  const pkg = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    storage_schema: ATLAS_METALS_REPORT_STORAGE_SCHEMA,
    build: ATLAS_BUILD,
    generated_at: new Date().toISOString(),
    snapshot_at: snapshotAt,
    fingerprint,
    origin: {
      machine: atlasMetalsQuoteFoundationState.origin === "github_archive" ? "github_actions" : "local_cache",
      label: atlasMetalsQuoteFoundationState.origin === "github_archive"
        ? "GitHub Actions · Public Metals Archive"
        : "Cache local complémentaire",
      mode: atlasMetalsQuoteFoundationState.origin
    },
    status: {
      quotes: quoteCount,
      expected: 5,
      history_snapshots: history.length,
      observation_only: true,
      human_validation_required: true,
      provider_requests_for_report: 0
    },
    source: {
      status: source.status,
      provider_id: source.provider_id || snapshot?.provider_id || null,
      provider_name: source.provider_name || snapshot?.provider_name || "Sources publiques",
      last_success_at: source.last_success_at || snapshotAt,
      public_sources: [...new Set(publicSources)]
    },
    snapshot,
    history,
    collector: source,
    assets,
    warnings: atlasMetalsReportWarnings(assets, snapshot, history),
    report_markdown: ""
  };
  pkg.report_markdown = atlasMetalsReportBuildMarkdown(pkg);
  return pkg;
}

async function atlasMetalsReportValidatePackage(input) {
  if (!input || input.schema !== ATLAS_METALS_REPORT_SCHEMA) {
    throw new Error("ce fichier n’est pas un rapport Métaux public");
  }
  if (String(input?.source?.provider_id || input?.snapshot?.provider_id || "") === "metals_dev") {
    throw new Error("ancien rapport Metals.Dev classé archive historique");
  }
  const text = JSON.stringify(input);
  if (atlasMetalsReportUtf8Bytes(text) > ATLAS_METALS_REPORT_LIMIT_BYTES) {
    throw new Error("rapport Métaux trop volumineux");
  }
  const hasForbiddenSecretKey = value => {
    if (Array.isArray(value)) return value.some(hasForbiddenSecretKey);
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).some(([key, child]) => {
      if (/^(?:api[_-]?key|access[_-]?token|github[_-]?token|password|secret)$/i.test(key)) return true;
      return hasForbiddenSecretKey(child);
    });
  };
  if (hasForbiddenSecretKey(input)) {
    throw new Error("champ secret interdit dans la mémoire Métaux");
  }
  const snapshot = atlasMetalsQuoteFoundationValidateSnapshot(input.snapshot);
  const history = (Array.isArray(input.history) ? input.history : [])
    .map(atlasMetalsQuoteFoundationValidateSnapshot);
  if (!String(input.report_markdown || "").trim()) throw new Error("rapport Métaux absent");
  if (!String(input.fingerprint || "").startsWith("sha256:")) throw new Error("empreinte Métaux absente");
  const signature = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    snapshot,
    history,
    structural_version: atlasMetalsStructuralRegistry()?.version || null,
    assets: (Array.isArray(input.assets) ? input.assets : []).map(asset => ({
      id: asset.id,
      quote: asset.quote,
      history_points: asset.history_points,
      structure: asset.structure
    }))
  };
  const expected = `sha256:${await atlasMetalsReportSha256(signature)}`;
  if (expected !== input.fingerprint) throw new Error("empreinte Métaux différente");
  return {
    ...atlasMetalsReportClone(input),
    snapshot,
    history
  };
}

function atlasMetalsReportOpenDb() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) return reject(new Error("IndexedDB indisponible"));
    const request = indexedDB.open(ATLAS_METALS_REPORT_DB_NAME, ATLAS_METALS_REPORT_DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(ATLAS_METALS_REPORT_STORE)) {
        db.createObjectStore(ATLAS_METALS_REPORT_STORE, { keyPath: "id" });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("ouverture IndexedDB refusée"));
    request.onblocked = () => reject(new Error("IndexedDB bloquée par un autre onglet"));
  });
}

async function atlasMetalsReportDbGet() {
  const db = await atlasMetalsReportOpenDb();
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(ATLAS_METALS_REPORT_STORE, "readonly");
      const request = tx.objectStore(ATLAS_METALS_REPORT_STORE).get(ATLAS_METALS_REPORT_RECORD_ID);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error || new Error("lecture IndexedDB refusée"));
    });
  } finally { db.close(); }
}

async function atlasMetalsReportDbPut(pkg) {
  const text = JSON.stringify(pkg);
  const bytes = atlasMetalsReportUtf8Bytes(text);
  if (bytes > ATLAS_METALS_REPORT_LIMIT_BYTES) throw new Error("mémoire Métaux trop volumineuse");
  const db = await atlasMetalsReportOpenDb();
  try {
    await new Promise((resolve, reject) => {
      const tx = db.transaction(ATLAS_METALS_REPORT_STORE, "readwrite");
      tx.objectStore(ATLAS_METALS_REPORT_STORE).put({
        id: ATLAS_METALS_REPORT_RECORD_ID,
        package: pkg,
        fingerprint: pkg.fingerprint,
        saved_at: new Date().toISOString()
      });
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error("écriture IndexedDB refusée"));
      tx.onabort = () => reject(tx.error || new Error("écriture IndexedDB annulée"));
    });
    const record = await atlasMetalsReportDbGet();
    const verified = await atlasMetalsReportValidatePackage(record?.package);
    return { ok: true, bytes, package: verified };
  } finally { db.close(); }
}

function atlasMetalsReportSetStatus(stateName, message, badgeText) {
  const card = document.getElementById("atlasMetalsReportCard");
  const status = document.getElementById("atlasMetalsReportStatus");
  const badge = document.getElementById("atlasMetalsReportBadge");
  if (card) card.dataset.state = stateName;
  if (status) status.textContent = message;
  if (badge) {
    badge.textContent = badgeText;
    badge.className = `pill ${stateName === "ready" ? "ok" : stateName === "warning" || stateName === "error" ? "warn" : ""}`.trim();
  }
}

function atlasMetalsReportHydrateQuoteState(pkg, origin = "book_memory") {
  if (!pkg?.snapshot) return false;
  atlasMetalsQuoteFoundationState.snapshot = pkg.snapshot;
  atlasMetalsQuoteFoundationState.collector = pkg.collector || null;
  atlasMetalsQuoteFoundationState.historyIndex = null;
  atlasMetalsQuoteFoundationState.history = Object.freeze([...(pkg.history || [])]);
  atlasMetalsQuoteFoundationState.contract = atlasMetalsQuoteFoundationState.contract || null;
  atlasMetalsQuoteFoundationState.quotes = Object.freeze([...(pkg.snapshot.quotes || [])]);
  atlasMetalsQuoteFoundationState.status = "loaded";
  atlasMetalsQuoteFoundationState.origin = origin;
  atlasMetalsQuoteFoundationState.loadedAt = new Date().toISOString();
  atlasMetalsQuoteFoundationState.error = null;
  atlasParallelMarketRenderMetals();
  return true;
}

function atlasMetalsReportEscapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function atlasMetalsReportComparisonForAsset(asset) {
  const points = (Array.isArray(asset?.history_points) ? asset.history_points : [])
    .filter(point => point?.time && Number.isFinite(Number(point?.price)))
    .map(point => ({
      time: atlasMetalsReportIso(point.time),
      price: Number(point.price),
      currency: String(point.currency || asset?.quote?.currency || "").toUpperCase(),
      unit: String(point.unit || asset?.quote?.unit || "")
    }))
    .filter(point => point.time)
    .sort((left, right) => Date.parse(left.time) - Date.parse(right.time));

  if (points.length < 2) {
    return {
      comparable: false,
      previous: points.at(-1) || null,
      latest: points.at(-1) || null,
      delta_value: null,
      delta_percent: null,
      direction: "insufficient"
    };
  }

  const previous = points.at(-2);
  const latest = points.at(-1);
  const coherent = previous.currency === latest.currency && previous.unit === latest.unit;
  if (!coherent) {
    return {
      comparable: false,
      previous,
      latest,
      delta_value: null,
      delta_percent: null,
      direction: "incoherent"
    };
  }

  const deltaValue = latest.price - previous.price;
  const deltaPercent = previous.price !== 0
    ? (deltaValue / previous.price) * 100
    : null;
  const epsilon = Math.max(Math.abs(previous.price), Math.abs(latest.price), 1) * 1e-12;
  const direction = Math.abs(deltaValue) <= epsilon
    ? "stable"
    : deltaValue > 0 ? "up" : "down";

  return {
    comparable: true,
    previous,
    latest,
    delta_value: deltaValue,
    delta_percent: Number.isFinite(deltaPercent) ? deltaPercent : null,
    direction
  };
}

function atlasMetalsReportSignedValue(value, point) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "—";
  const absolute = Math.abs(number);
  const maximumFractionDigits = absolute >= 1000 ? 2 : absolute >= 100 ? 3 : absolute >= 1 ? 4 : 6;
  const formatted = new Intl.NumberFormat("fr-FR", {
    minimumFractionDigits: 0,
    maximumFractionDigits
  }).format(absolute);
  const sign = number > 0 ? "+" : number < 0 ? "−" : "";
  const currency = String(point?.currency || "").toUpperCase();
  return `${sign}${formatted}${currency ? ` ${currency}` : ""}`;
}

function atlasMetalsReportComparisonDirection(direction) {
  if (direction === "up") return { label: "Hausse", className: "is-up", symbol: "↗" };
  if (direction === "down") return { label: "Baisse", className: "is-down", symbol: "↘" };
  if (direction === "stable") return { label: "Stable", className: "is-stable", symbol: "→" };
  if (direction === "incoherent") return { label: "Incohérent", className: "is-warning", symbol: "!" };
  return { label: "Insuffisant", className: "is-warning", symbol: "·" };
}

function atlasMetalsReportSnapshotCoverage(snapshot) {
  const expected = new Set(["gold", "silver", "platinum", "palladium", "copper"]);
  const received = new Set(
    (Array.isArray(snapshot?.quotes) ? snapshot.quotes : [])
      .filter(quote => expected.has(quote?.asset_id) && Number.isFinite(Number(quote?.price)))
      .map(quote => quote.asset_id)
  );
  return `${received.size}/5`;
}

function atlasMetalsReportRenderComparison(pkg) {
  const rows = document.getElementById("atlasMetalsComparisonRows");
  const windowText = document.getElementById("atlasMetalsComparisonWindow");
  const summary = document.getElementById("atlasMetalsComparisonSummary");
  const strip = document.getElementById("atlasMetalsSnapshotStrip");
  const note = document.getElementById("atlasMetalsComparisonNote");
  if (!rows || !windowText || !summary || !strip) return false;

  const assets = Array.isArray(pkg?.assets) ? pkg.assets : [];
  const comparisons = assets.map(asset => ({
    asset,
    comparison: atlasMetalsReportComparisonForAsset(asset)
  }));
  const comparable = comparisons.filter(item => item.comparison.comparable);
  const counts = comparable.reduce((accumulator, item) => {
    accumulator[item.comparison.direction] = (accumulator[item.comparison.direction] || 0) + 1;
    return accumulator;
  }, { up: 0, down: 0, stable: 0 });

  if (!assets.length) {
    rows.innerHTML = '<tr><td colspan="6">Aucune comparaison disponible.</td></tr>';
  } else {
    rows.innerHTML = comparisons.map(({ asset, comparison }) => {
      const direction = atlasMetalsReportComparisonDirection(comparison.direction);
      const previous = comparison.previous ? atlasMetalsReportPrice(comparison.previous) : "—";
      const latest = comparison.latest ? atlasMetalsReportPrice(comparison.latest) : "—";
      const delta = atlasMetalsReportSignedValue(comparison.delta_value, comparison.latest);
      const percent = atlasMetalsReportPercent(comparison.delta_percent);
      return `
        <tr data-direction="${atlasMetalsReportEscapeHtml(comparison.direction)}">
          <td><b>${atlasMetalsReportEscapeHtml(asset?.symbol || "—")}</b><span>${atlasMetalsReportEscapeHtml(asset?.name || asset?.id || "Métal")}</span></td>
          <td>${atlasMetalsReportEscapeHtml(previous)}</td>
          <td>${atlasMetalsReportEscapeHtml(latest)}</td>
          <td>${atlasMetalsReportEscapeHtml(delta)}</td>
          <td>${atlasMetalsReportEscapeHtml(percent)}</td>
          <td><span class="atlas-metals-trend ${direction.className}"><i aria-hidden="true">${direction.symbol}</i>${direction.label}</span></td>
        </tr>`;
    }).join("");
  }

  const comparableTimes = comparable
    .flatMap(item => [item.comparison.previous?.time, item.comparison.latest?.time])
    .filter(Boolean)
    .sort((left, right) => Date.parse(left) - Date.parse(right));
  const previousAt = comparableTimes[0] || null;
  const latestAt = comparableTimes.at(-1) || null;
  windowText.textContent = comparable.length
    ? `Comparaison du ${atlasMetalsReportDate(previousAt)} au ${atlasMetalsReportDate(latestAt)} · ${comparable.length}/5 métaux cohérents.`
    : "Historique insuffisant ou unités incohérentes : aucune variation calculée.";

  summary.textContent = comparable.length
    ? `↑ ${counts.up} · ↓ ${counts.down} · → ${counts.stable}`
    : "0 comparé";
  summary.className = `pill ${comparable.length === 5 ? "ok" : "warn"}`;

  const snapshots = (Array.isArray(pkg?.history) ? pkg.history : [])
    .filter(Boolean)
    .map(snapshot => ({
      snapshot,
      time: atlasMetalsReportSnapshotTime(snapshot)
    }))
    .filter(item => item.time)
    .sort((left, right) => Date.parse(left.time) - Date.parse(right.time))
    .slice(-8);
  strip.innerHTML = snapshots.length
    ? snapshots.map((item, index) => `
        <span class="${index === snapshots.length - 1 ? "is-latest" : ""}">
          <b>${atlasMetalsReportEscapeHtml(atlasMetalsReportDate(item.time))}</b>
          <small>${atlasMetalsReportEscapeHtml(atlasMetalsReportSnapshotCoverage(item.snapshot))} réel</small>
        </span>`).join("")
    : "<span>Aucune séance Futures conservée.</span>";

  if (note) {
    note.textContent = comparable.length === 5
      ? "Écarts calculés entre les deux dernières séances Futures réelles de chaque métal · aucune prévision · aucune requête fournisseur."
      : "Comparaison suspendue pour toute série incomplète ou incohérente · aucune valeur remplacée ou inventée.";
  }
  return true;
}

function atlasMetalsReportRender() {
  const pkg = atlasMetalsReportState.package;
  const content = document.getElementById("atlasMetalsReportContent");
  if (!pkg) {
    if (content) content.innerHTML = '<p class="atlas-local-response-empty">Aucun rapport Métaux public disponible. Il apparaîtra automatiquement après la première collecte publique complète 5/5.</p>';
    setText(document.getElementById("atlasMetalsReportSnapshot"), "—");
    setText(document.getElementById("atlasMetalsReportOrigin"), "—");
    setText(document.getElementById("atlasMetalsReportQuotes"), "0/5");
    setText(document.getElementById("atlasMetalsReportHistory"), "0 séance Futures");
    setText(document.getElementById("atlasMetalsReportPersistence"), "Non enregistrée");
    atlasMetalsReportRenderComparison(null);
    ["btnAtlasMetalsReportCopy", "btnAtlasMetalsReportExportMd"]
      .forEach(id => document.getElementById(id)?.setAttribute("disabled", ""));
    return false;
  }
  if (content) content.innerHTML = atlasLocalReportHtml(pkg.report_markdown);
  atlasMetalsReportRenderComparison(pkg);
  setText(document.getElementById("atlasMetalsReportSnapshot"), atlasMetalsReportDate(pkg.snapshot_at));
  setText(document.getElementById("atlasMetalsReportOrigin"), pkg.origin?.label || "Archive publique");
  setText(document.getElementById("atlasMetalsReportQuotes"), `${pkg.status?.quotes || 0}/5`);
  const count = Number(pkg.status?.history_snapshots || pkg.history?.length || 0);
  setText(document.getElementById("atlasMetalsReportHistory"), `${count} séances Futures`);
  setText(
    document.getElementById("atlasMetalsReportPersistence"),
    atlasMetalsReportState.persistence.ok
      ? `IndexedDB · ${Math.max(1, Math.round(atlasMetalsReportState.persistence.bytes / 1024))} Ko vérifiés`
      : "IndexedDB · non vérifiée"
  );
  ["btnAtlasMetalsReportCopy", "btnAtlasMetalsReportExportMd"]
    .forEach(id => document.getElementById(id)?.removeAttribute("disabled"));
  return true;
}

async function atlasMetalsReportActivate(pkg, source, persist = true) {
  const clean = await atlasMetalsReportValidatePackage(pkg);
  atlasMetalsReportState.package = clean;
  atlasMetalsReportState.source = source;
  atlasMetalsReportState.persistence = { ok: false, bytes: 0, error: "Non vérifiée" };
  atlasMetalsReportRender();
  if (persist) {
    const saved = await atlasMetalsReportDbPut(clean);
    atlasMetalsReportState.package = saved.package;
    atlasMetalsReportState.persistence = { ok: true, bytes: saved.bytes, error: "" };
  }
  atlasMetalsReportHydrateQuoteState(
    atlasMetalsReportState.package,
    source === "public" ? "github_archive"
      : source === "local" ? "local_bridge"
        : source === "indexeddb" ? "book_memory"
          : "book_memory"
  );
  atlasMetalsReportRender();
  const label = source === "public" ? "Publique" : source === "local" ? "Locale" : source === "indexeddb" ? "Restaurée" : "Importée";
  atlasMetalsReportSetStatus(
    "ready",
    `${label} · rapport Métaux ${clean.status.quotes}/5 · ${clean.status.history_snapshots} séance${clean.status.history_snapshots > 1 ? "s" : ""} Futures · IndexedDB vérifiée.`,
    label
  );
  return clean;
}

async function atlasMetalsReportLoadFromInterface() {
  if (!ATLAS_METALS_REPORT_INTERFACE_PATH) return null;
  try {
    const separator = ATLAS_METALS_REPORT_INTERFACE_PATH.includes("?") ? "&" : "?";
    const response = await fetch(
      `${ATLAS_METALS_REPORT_INTERFACE_PATH}${separator}build=${encodeURIComponent(ATLAS_BUILD)}`,
      { cache: "no-store", headers: { "Accept": "application/json" } }
    );
    if (!response.ok) throw new Error(`mémoire Interface indisponible (${response.status})`);
    const candidate = await atlasMetalsReportValidatePackage(await response.json());
    const current = atlasMetalsReportState.package;
    const candidateTime = Date.parse(candidate.snapshot_at || candidate.generated_at || 0) || 0;
    const currentTime = Date.parse(current?.snapshot_at || current?.generated_at || 0) || 0;
    if (current && currentTime > candidateTime) return current;
    await atlasMetalsReportActivate(candidate, "interface", true);
    atlasMetalsReportSetStatus(
      "ready",
      `Inscrite dans l’Interface · rapport Métaux ${candidate.status.quotes}/5 · lecture automatique sur ce poste.`,
      "Inscrite"
    );
    return candidate;
  } catch (error) {
    if (!atlasMetalsReportState.package) {
      atlasMetalsReportSetStatus("warning", `Rapport Interface indisponible : ${error?.message || error}.`, "À vérifier");
    }
    return null;
  }
}

async function atlasMetalsReportRestore() {
  atlasMetalsReportSetStatus("working", "Restauration de la mémoire Métaux…", "Restauration");
  try {
    const record = await atlasMetalsReportDbGet();
    if (!record?.package) {
      atlasMetalsReportSetStatus("empty", "En attente de la première collecte publique complète 5/5 · aucune publication manuelle requise.", "Prêt");
      return null;
    }
    const clean = await atlasMetalsReportValidatePackage(record.package);
    atlasMetalsReportState.package = clean;
    atlasMetalsReportState.source = "indexeddb";
    atlasMetalsReportState.persistence = {
      ok: true,
      bytes: atlasMetalsReportUtf8Bytes(JSON.stringify(clean)),
      error: ""
    };
    atlasMetalsReportHydrateQuoteState(clean, "book_memory");
    atlasMetalsReportRender();
    atlasMetalsReportSetStatus("ready", `Restaurée depuis IndexedDB · rapport Métaux ${clean.status.quotes}/5 disponible.`, "Restaurée");
    return clean;
  } catch (error) {
    atlasMetalsReportState.persistence = { ok: false, bytes: 0, error: String(error?.message || error) };
    atlasMetalsReportRender();
    atlasMetalsReportSetStatus("warning", `IndexedDB indisponible : ${atlasMetalsReportState.persistence.error}. Les données publiques restent consultables en ligne.`, "À vérifier");
    return null;
  }
}

async function atlasMetalsReportProduceFromCurrent() {
  if (!["github_archive", "local_bridge"].includes(atlasMetalsQuoteFoundationState.origin)) return false;
  const count = atlasMetalsQuoteFoundationSummary().quoteCount;
  if (count !== 5) return false;
  const operation = ++atlasMetalsReportState.operation;
  atlasMetalsReportSetStatus("working", "Données publiques 5/5 reçues · construction du rapport Métaux…", "Construction");
  try {
    const pkg = await atlasMetalsReportBuildPackage();
    if (operation !== atlasMetalsReportState.operation) return false;
    if (atlasMetalsReportState.package?.fingerprint === pkg.fingerprint) {
      atlasMetalsReportHydrateQuoteState(atlasMetalsReportState.package, atlasMetalsQuoteFoundationState.origin);
      atlasMetalsReportRender();
      atlasMetalsReportSetStatus("ready", "Rapport Métaux déjà inscrit pour ce snapshot · aucune nouvelle requête fournisseur.", "Conservé");
      return true;
    }
    await atlasMetalsReportActivate(pkg, atlasMetalsQuoteFoundationState.origin === "github_archive" ? "public" : "local", true);
    return true;
  } catch (error) {
    atlasMetalsReportSetStatus("warning", `Rapport non inscrit : ${error?.message || error}. Les cotations restent disponibles.`, "À vérifier");
    return false;
  }
}

async function atlasMetalsReportCopy() {
  const text = atlasMetalsReportState.package?.report_markdown || "";
  if (!text) return;
  try { await navigator.clipboard.writeText(text); }
  catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    document.execCommand("copy");
    area.remove();
  }
  atlasMetalsReportSetStatus("ready", "Rapport Métaux copié.", "Conservé");
}

function atlasMetalsReportExportJson() {
  const pkg = atlasMetalsReportState.package;
  if (!pkg) return;
  const stamp = new Date(pkg.snapshot_at || pkg.generated_at || Date.now())
    .toISOString().replace(/[:.]/g, "-");
  downloadTextFile(
    `agent_crypto_metals_report_${stamp}.json`,
    "application/json;charset=utf-8",
    JSON.stringify(pkg, null, 2)
  );
  atlasMetalsReportSetStatus("ready", "JSON du rapport Métaux exporté · aucune requête fournisseur.", "Exportée");
}

function atlasMetalsReportExportMd() {
  const pkg = atlasMetalsReportState.package;
  if (!pkg) return;
  const stamp = new Date(pkg.snapshot_at || pkg.generated_at || Date.now())
    .toISOString().replace(/[:.]/g, "-");
  const text = [
    "# Rapport Métaux public",
    "",
    `- Interface : ${ATLAS_RELEASE}`,
    `- Snapshot : ${atlasMetalsReportDate(pkg.snapshot_at)}`,
    `- Origine : ${pkg.origin?.label || "Archive publique"}`,
    `- Empreinte : ${pkg.fingerprint}`,
    "- Mode : observation uniquement",
    "",
    pkg.report_markdown
  ].join("\n");
  downloadTextFile(`agent_crypto_metals_report_${stamp}.md`, "text/markdown;charset=utf-8", text);
  atlasMetalsReportSetStatus("ready", "Rapport Métaux Markdown exporté.", "Exportée");
}

async function atlasMetalsReportImportFile(file) {
  if (!file) return false;
  if (file.size > ATLAS_METALS_REPORT_LIMIT_BYTES) throw new Error("fichier Métaux trop volumineux");
  const input = JSON.parse(await file.text());
  await atlasMetalsReportActivate(input, "import", true);
  return true;
}

function atlasMetalsReportInit() {
  if (atlasMetalsReportState.initialized) return atlasMetalsReportState.restorePromise;
  atlasMetalsReportState.initialized = true;
  document.getElementById("btnAtlasMetalsReportCopy")?.addEventListener("click", atlasMetalsReportCopy);
  document.getElementById("btnAtlasMetalsReportExportMd")?.addEventListener("click", atlasMetalsReportExportMd);
  atlasMetalsReportRender();
  atlasMetalsReportState.restorePromise = (async () => {
    await atlasMetalsReportRestore();
    return atlasMetalsReportState.package;
  })();
  return atlasMetalsReportState.restorePromise;
}

const atlasMetalsQuoteFoundationSummaryV56 = atlasMetalsQuoteFoundationSummary;
atlasMetalsQuoteFoundationSummary = function atlasMetalsQuoteFoundationSummaryV57() {
  const summary = atlasMetalsQuoteFoundationSummaryV56();
  if (!["book_memory", "interface_memory"].includes(atlasMetalsQuoteFoundationState.origin) || summary.quoteCount < 1) return summary;
  return {
    quoteCount: summary.quoteCount,
    short: `Archive publique ${summary.quoteCount}/5`,
    domain: `${summary.quoteCount}/5 cotations restaurées depuis le rapport public Métaux`,
    market: `${summary.quoteCount}/5 cotations conservées · historique public annuel`,
    truth: `${summary.quoteCount}/5 cotations réelles restaurées depuis GitHub / IndexedDB`
  };
};

const atlasMetalsQuoteFoundationLoadV56 = atlasMetalsQuoteFoundationLoad;
atlasMetalsQuoteFoundationLoad = async function atlasMetalsQuoteFoundationLoadV57() {
  const status = await atlasMetalsQuoteFoundationLoadV56();
  await atlasMetalsReportState.restorePromise;
  if (["local_bridge", "github_archive"].includes(atlasMetalsQuoteFoundationState.origin)
      && atlasMetalsQuoteFoundationSummary().quoteCount === 5) {
    await atlasMetalsReportProduceFromCurrent();
  } else if (atlasMetalsReportState.package
      && atlasMetalsQuoteFoundationSummary().quoteCount === 0) {
    atlasMetalsReportHydrateQuoteState(atlasMetalsReportState.package, "book_memory");
  }
  return status;
};

const atlasMetalsQuoteFoundationReloadHistoryV56 = atlasMetalsQuoteFoundationReloadHistory;
atlasMetalsQuoteFoundationReloadHistory = async function atlasMetalsQuoteFoundationReloadHistoryV57() {
  const ok = await atlasMetalsQuoteFoundationReloadHistoryV56();
  if (ok) await atlasMetalsReportProduceFromCurrent();
  return ok;
};


